window.ExtraBibleBooks=window.ExtraBibleBooks||{};window.ExtraBibleBooks["MIC"]={"book":"MIC","editions":{"hbo-source":[[1,1,"דְּבַר־יְהוָ֣ה ׀ אֲשֶׁ֣ר הָיָ֗ה אֶל־מִיכָה֙ הַ⁠מֹּ֣רַשְׁתִּ֔י בִּ⁠ימֵ֥י יוֹתָ֛ם אָחָ֥ז יְחִזְקִיָּ֖ה מַלְכֵ֣י יְהוּדָ֑ה אֲשֶׁר־חָזָ֥ה עַל־שֹׁמְר֖וֹן וִ⁠ירֽוּשָׁלִָֽם׃","dĕ̇bar-yĕhwá֣h ׀ ʼàşě֣r háyá֗h ʼel-miykáh֙ ha⁠mò֣̇raşĕ̌ţi̇֔y bi̇⁠ymé֥y ywòţá֛m ʼáẖá֥z yĕẖizĕqiyá֖̇h malĕké֣y yĕhẇdá֑h ʼàşěr-ẖázá֥h ʻal-şò̌mĕr֖wòn wi⁠yrֽẇşá̌liáֽm׃"],[1,2,"שִׁמְעוּ֙ עַמִּ֣ים כֻּלָּ֔⁠ם הַקְשִׁ֖יבִי אֶ֣רֶץ וּ⁠מְלֹאָ֑⁠הּ וִ⁠יהִי֩ אֲדֹנָ֨⁠י יְהוִ֤ה בָּ⁠כֶם֙ לְ⁠עֵ֔ד אֲדֹנָ֖⁠י מֵ⁠הֵיכַ֥ל קָדְשֽׁ⁠וֹ׃","şǐmĕʻẇ֙ ʻami֣̇ym ku̇lá̇֔⁠m haqĕşǐ֖ybiy ʼe֣reẕ ẇ⁠mĕlòʼá֑⁠ḣ wi⁠yhiy֩ ʼàdòná֨⁠y yĕhwi֤h bá̇⁠kem֙ lĕ⁠ʻé֔d ʼàdòná֖⁠y mé⁠héyka֥l qádĕşֽ̌⁠wò׃"],[1,3,"כִּֽי־הִנֵּ֥ה יְהוָ֖ה יֹצֵ֣א מִ⁠מְּקוֹמ֑⁠וֹ וְ⁠יָרַ֥ד וְ⁠דָרַ֖ךְ עַל־במותי אָֽרֶץ׃","kiֽ̇y-hiné֥̇h yĕhwá֖h yòẕé֣ʼ mi⁠mĕ̇qwòm֑⁠wò wĕ⁠yára֥d wĕ⁠dára֖kĕ ʻal-bmwţy ʼáֽreẕ׃"],[1,4,"וְ⁠נָמַ֤סּוּ הֶֽ⁠הָרִים֙ תַּחְתָּ֔י⁠ו וְ⁠הָ⁠עֲמָקִ֖ים יִתְבַּקָּ֑עוּ כַּ⁠דּוֹנַג֙ מִ⁠פְּנֵ֣י הָ⁠אֵ֔שׁ כְּ⁠מַ֖יִם מֻגָּרִ֥ים בְּ⁠מוֹרָֽד׃","wĕ⁠náma֤ṡẇ heֽ⁠háriym֙ ţȧẖĕţá̇֔y⁠w wĕ⁠há⁠ʻàmáqi֖ym yiţĕbȧqá֑̇ʻẇ kȧ⁠ḋwònag֙ mi⁠pĕ̇né֣y há⁠ʼé֔ş̌ kĕ̇⁠ma֖yim mugá̇ri֥ym bĕ̇⁠mwòráֽd׃"],[1,5,"בְּ⁠פֶ֤שַׁע יַֽעֲקֹב֙ כָּל־זֹ֔את וּ⁠בְ⁠חַטֹּ֖אות בֵּ֣ית יִשְׂרָאֵ֑ל מִֽי־פֶ֣שַׁע יַעֲקֹ֗ב הֲ⁠לוֹא֙ שֹֽׁמְר֔וֹן וּ⁠מִי֙ בָּמ֣וֹת יְהוּדָ֔ה הֲ⁠ל֖וֹא יְרוּשָׁלִָֽם׃","bĕ̇⁠pe֤şǎʻ yaֽʻàqòb֙ ká̇l-zò֔ʼţ ẇ⁠bĕ⁠ẖatò֖̇ʼwţ bé֣̇yţ yişĕ̂ráʼé֑l miֽy-pe֣şǎʻ yaʻàqò֗b hà⁠lwòʼ֙ şòֽ̌mĕr֔wòn ẇ⁠miy֙ bá̇m֣wòţ yĕhẇdá֔h hà⁠l֖wòʼ yĕrẇşá̌liáֽm׃"],[1,6,"וְ⁠שַׂמְתִּ֥י שֹׁמְר֛וֹן לְ⁠עִ֥י הַ⁠שָּׂדֶ֖ה לְ⁠מַטָּ֣עֵי כָ֑רֶם וְ⁠הִגַּרְתִּ֤י לַ⁠גַּי֙ אֲבָנֶ֔י⁠הָ וִ⁠יסֹדֶ֖י⁠הָ אֲגַלֶּֽה׃","wĕ⁠şâmĕţi֥̇y şò̌mĕr֛wòn lĕ⁠ʻi֥y ha⁠şá̇̂de֖h lĕ⁠matá֣̇ʻéy ká֑rem wĕ⁠higȧrĕţi֤̇y la⁠gȧy֙ ʼàbáne֔y⁠há wi⁠ysòde֖y⁠há ʼàgalėֽh׃"],[1,7,"וְ⁠כָל־פְּסִילֶ֣י⁠הָ יֻכַּ֗תּוּ וְ⁠כָל־אֶתְנַנֶּ֨י⁠הָ֙ יִשָּׂרְפ֣וּ בָ⁠אֵ֔שׁ וְ⁠כָל־עֲצַבֶּ֖י⁠הָ אָשִׂ֣ים שְׁמָמָ֑ה כִּ֠י מֵ⁠אֶתְנַ֤ן זוֹנָה֙ קִבָּ֔צָה וְ⁠עַד־אֶתְנַ֥ן זוֹנָ֖ה יָשֽׁוּבוּ׃","wĕ⁠kál-pĕ̇siyle֣y⁠há yukȧ֗ţ̇ẇ wĕ⁠kál-ʼeţĕnanė֨y⁠há֙ yişá̇̂rĕp֣ẇ bá⁠ʼé֔ş̌ wĕ⁠kál-ʻàẕabė֖y⁠há ʼáşî֣ym şĕ̌mámá֑h ki̇֠y mé⁠ʼeţĕna֤n zwònáh֙ qibá̇֔ẕáh wĕ⁠ʻad-ʼeţĕna֥n zwòná֖h yáşֽ̌ẇbẇ׃"],[1,8,"עַל־זֹאת֙ אֶסְפְּדָ֣ה וְ⁠אֵילִ֔ילָה אֵילְכָ֥ה שילל וְ⁠עָר֑וֹם אֶעֱשֶׂ֤ה מִסְפֵּד֙ כַּ⁠תַּנִּ֔ים וְ⁠אֵ֖בֶל כִּ⁠בְנ֥וֹת יַעֲנָֽה׃","ʻal-zòʼţ֙ ʼesĕpĕ̇dá֣h wĕ⁠ʼéyli֔yláh ʼéylĕká֥h şyll wĕ⁠ʻár֑wòm ʼeʻèşê֤h misĕpé̇d֙ kȧ⁠ţȧni̇֔ym wĕ⁠ʼé֖bel ki̇⁠bĕn֥wòţ yaʻànáֽh׃"],[1,9,"כִּ֥י אֲנוּשָׁ֖ה מַכּוֹתֶ֑י⁠הָ כִּי־בָ֨אָה֙ עַד־יְהוּדָ֔ה נָגַ֛ע עַד־שַׁ֥עַר עַמִּ֖⁠י עַד־יְרוּשָׁלִָֽם׃","ki֥̇y ʼànẇşá֖̌h mak̇wòţe֑y⁠há ki̇y-bá֨ʼáh֙ ʻad-yĕhẇdá֔h nága֛ʻ ʻad-şǎ֥ʻar ʻami֖̇⁠y ʻad-yĕrẇşá̌liáֽm׃"],[1,10,"בְּ⁠גַת֙ אַל־תַּגִּ֔ידוּ בָּכ֖וֹ אַל־תִּבְכּ֑וּ בְּ⁠בֵ֣ית לְעַפְרָ֔ה עָפָ֖ר התפלשתי׃","bĕ̇⁠gaţ֙ ʼal-ţȧgi̇֔ydẇ bá̇k֖wò ʼal-ţi̇bĕk֑̇ẇ bĕ̇⁠bé֣yţ lĕʻapĕrá֔h ʻápá֖r hţplşţy׃"],[1,11,"עִבְרִ֥י לָ⁠כֶ֛ם יוֹשֶׁ֥בֶת שָׁפִ֖יר עֶרְיָה־בֹ֑שֶׁת לֹ֤א יָֽצְאָה֙ יוֹשֶׁ֣בֶת צַֽאֲנָ֔ן מִסְפַּד֙ בֵּ֣ית הָאֵ֔צֶל יִקַּ֥ח מִ⁠כֶּ֖ם עֶמְדָּתֽ⁠וֹ׃","ʻibĕri֥y lá⁠ke֛m ywòşě֥beţ şá̌pi֖yr ʻerĕyáh-bò֑şěţ lò֤ʼ yáֽẕĕʼáh֙ ywòşě֣beţ ẕaֽʼàná֔n misĕpȧd֙ bé֣̇yţ háʼé֔ẕel yiqȧ֥ẖ mi⁠kė֖m ʻemĕdá̇ţֽ⁠wò׃"],[1,12,"כִּֽי־חָ֥לָֽה לְ⁠ט֖וֹב יוֹשֶׁ֣בֶת מָר֑וֹת כִּֽי־יָ֤רַד רָע֙ מֵ⁠אֵ֣ת יְהוָ֔ה לְ⁠שַׁ֖עַר יְרוּשָׁלִָֽם׃","kiֽ̇y-ẖá֥láֽh lĕ⁠t֖wòb ywòşě֣beţ már֑wòţ kiֽ̇y-yá֤rad ráʻ֙ mé⁠ʼé֣ţ yĕhwá֔h lĕ⁠şǎ֖ʻar yĕrẇşá̌liáֽm׃"],[1,13,"רְתֹ֧ם הַ⁠מֶּרְכָּבָ֛ה לָ⁠רֶ֖כֶשׁ יוֹשֶׁ֣בֶת לָכִ֑ישׁ רֵאשִׁ֨ית חַטָּ֥את הִיא֙ לְ⁠בַת־צִיּ֔וֹן כִּי־בָ֥⁠ךְ נִמְצְא֖וּ פִּשְׁעֵ֥י יִשְׂרָאֵֽל׃","rĕţò֧m ha⁠mėrĕká̇bá֛h lá⁠re֖keş̌ ywòşě֣beţ láki֑yş̌ réʼşǐ֨yţ ẖatá֥̇ʼţ hiyʼ֙ lĕ⁠baţ-ẕiẏ֔wòn ki̇y-bá֥⁠kĕ nimĕẕĕʼ֖ẇ pi̇şĕ̌ʻé֥y yişĕ̂ráʼéֽl׃"],[1,14,"לָ⁠כֵן֙ תִּתְּנִ֣י שִׁלּוּחִ֔ים עַ֖ל מוֹרֶ֣שֶׁת גַּ֑ת בָּתֵּ֤י אַכְזִיב֙ לְ⁠אַכְזָ֔ב לְ⁠מַלְכֵ֖י יִשְׂרָאֵֽל׃","lá⁠kén֙ ţi̇ţĕ̇ni֣y şǐl̇ẇẖi֔ym ʻa֖l mwòre֣şěţ gȧ֑ţ bá̇ţé֤̇y ʼakĕziyb֙ lĕ⁠ʼakĕzá֔b lĕ⁠malĕké֖y yişĕ̂ráʼéֽl׃"],[1,15,"עֹ֗ד הַ⁠יֹּרֵשׁ֙ אָ֣בִי לָ֔⁠ךְ יוֹשֶׁ֖בֶת מָֽרֵשָׁ֑ה עַד־עֲדֻּלָּ֥ם יָב֖וֹא כְּב֥וֹד יִשְׂרָאֵֽל׃","ʻò֗d ha⁠yò̇réş̌֙ ʼá֣biy lá֔⁠kĕ ywòşě֖beţ máֽréşá֑̌h ʻad-ʻàdu̇lá֥̇m yáb֖wòʼ kĕ̇b֥wòd yişĕ̂ráʼéֽl׃"],[1,16,"קָרְחִ֣י וָ⁠גֹ֔זִּי עַל־בְּנֵ֖י תַּעֲנוּגָ֑יִ⁠ךְ הַרְחִ֤בִי קָרְחָתֵ⁠ךְ֙ כַּ⁠נֶּ֔שֶׁר כִּ֥י גָל֖וּ מִמֵּֽ⁠ךְ׃ס","qárĕẖi֣y wá⁠gò֔zi̇y ʻal-bĕ̇né֖y ţȧʻànẇgá֑yi⁠kĕ harĕẖi֤biy qárĕẖáţé⁠kĕ֙ kȧ⁠nė֔şěr ki֥̇y gál֖ẇ miméֽ̇⁠kĕ׃s"],[2,1,"ה֧וֹי חֹֽשְׁבֵי־אָ֛וֶן וּ⁠פֹ֥עֲלֵי רָ֖ע עַל־מִשְׁכְּבוֹתָ֑⁠ם בְּ⁠א֤וֹר הַ⁠בֹּ֨קֶר֙ יַעֲשׂ֔וּ⁠הָ כִּ֥י יֶשׁ־לְ⁠אֵ֖ל יָדָֽ⁠ם׃","h֧wòy ẖòֽşĕ̌béy-ʼá֛wen ẇ⁠pò֥ʻàléy rá֖ʻ ʻal-mişĕ̌kĕ̇bwòţá֑⁠m bĕ̇⁠ʼ֤wòr ha⁠bò̇֨qer֙ yaʻàş̂֔ẇ⁠há ki֥̇y yeş̌-lĕ⁠ʼé֖l yádáֽ⁠m׃"],[2,2,"וְ⁠חָמְד֤וּ שָׂדוֹת֙ וְ⁠גָזָ֔לוּ וּ⁠בָתִּ֖ים וְ⁠נָשָׂ֑אוּ וְ⁠עָֽשְׁקוּ֙ גֶּ֣בֶר וּ⁠בֵית֔⁠וֹ וְ⁠אִ֖ישׁ וְ⁠נַחֲלָתֽ⁠וֹ׃פ","wĕ⁠ẖámĕd֤ẇ şá̂dwòţ֙ wĕ⁠gázá֔lẇ ẇ⁠báţi֖̇ym wĕ⁠náşá֑̂ʼẇ wĕ⁠ʻáֽşĕ̌qẇ֙ gė֣ber ẇ⁠béyţ֔⁠wò wĕ⁠ʼi֖yş̌ wĕ⁠naẖàláţֽ⁠wò׃p"],[2,3,"לָ⁠כֵ֗ן כֹּ֚ה אָמַ֣ר יְהוָ֔ה הִנְ⁠נִ֥י חֹשֵׁ֛ב עַל־הַ⁠מִּשְׁפָּחָ֥ה הַ⁠זֹּ֖את רָעָ֑ה אֲ֠שֶׁר לֹֽא־תָמִ֨ישׁוּ מִ⁠שָּׁ֜ם צַוְּארֹֽתֵי⁠כֶ֗ם וְ⁠לֹ֤א תֵֽלְכוּ֙ רוֹמָ֔ה כִּ֛י עֵ֥ת רָעָ֖ה הִֽיא׃","lá⁠ké֗n kò֚̇h ʼáma֣r yĕhwá֔h hinĕ⁠ni֥y ẖòşé֛̌b ʻal-ha⁠mi̇şĕ̌pá̇ẖá֥h ha⁠zò֖̇ʼţ ráʻá֑h ʼà֠şěr lòֽʼ-ţámi֨yş̌ẇ mi⁠şá̇̌֜m ẕawĕ̇ʼròֽţéy⁠ke֗m wĕ⁠lò֤ʼ ţéֽlĕkẇ֙ rwòmá֔h ki֛̇y ʻé֥ţ ráʻá֖h hiֽyʼ׃"],[2,4,"בַּ⁠יּ֨וֹם הַ⁠ה֜וּא יִשָּׂ֧א עֲלֵי⁠כֶ֣ם מָשָׁ֗ל וְ⁠נָהָ֨ה נְהִ֤י נִֽהְיָה֙ אָמַר֙ שָׁד֣וֹד נְשַׁדֻּ֔נוּ חֵ֥לֶק עַמִּ֖⁠י יָמִ֑יר אֵ֚יךְ יָמִ֣ישׁ לִ֔⁠י לְ⁠שׁוֹבֵ֥ב שָׂדֵ֖י⁠נוּ יְחַלֵּֽק׃","bȧ⁠ẏ֨wòm ha⁠h֜ẇʼ yişá֧̇̂ʼ ʻàléy⁠ke֣m máşá̌֗l wĕ⁠náhá֨h nĕhi֤y niֽhĕyáh֙ ʼámar֙ şá̌d֣wòd nĕşǎdu̇֔nẇ ẖé֥leq ʻami֖̇⁠y yámi֑yr ʼé֚ykĕ yámi֣yş̌ li֔⁠y lĕ⁠ş̌wòbé֥b şá̂dé֖y⁠nẇ yĕẖaléֽ̇q׃"],[2,5,"לָ⁠כֵן֙ לֹֽא־יִֽהְיֶ֣ה לְ⁠ךָ֔ מַשְׁלִ֥יךְ חֶ֖בֶל בְּ⁠גוֹרָ֑ל בִּ⁠קְהַ֖ל יְהוָֽה׃","lá⁠kén֙ lòֽʼ-yiֽhĕye֣h lĕ⁠ká֔ maşĕ̌li֥ykĕ ẖe֖bel bĕ̇⁠gwòrá֑l bi̇⁠qĕha֖l yĕhwáֽh׃"],[2,6,"אַל־תַּטִּ֖פוּ יַטִּיפ֑וּ⁠ן לֹֽא־יַטִּ֣פוּ לָ⁠אֵ֔לֶּה לֹ֥א יִסַּ֖ג כְּלִמּֽוֹת׃","ʼal-ţȧti֖̇pẇ yati̇yp֑ẇ⁠n lòֽʼ-yati֣̇pẇ lá⁠ʼé֔lėh lò֥ʼ yisȧ֖g kĕ̇liṁֽwòţ׃"],[2,7,"הֶ⁠אָמ֣וּר בֵּֽית־יַעֲקֹ֗ב הֲ⁠קָצַר֙ ר֣וּחַ יְהוָ֔ה אִם־אֵ֖לֶּה מַעֲלָלָ֑י⁠ו הֲ⁠ל֤וֹא דְבָרַ֨⁠י יֵיטִ֔יבוּ עִ֖ם הַ⁠יָּשָׁ֥ר הוֹלֵֽךְ׃","he⁠ʼám֣ẇr béֽ̇yţ-yaʻàqò֗b hà⁠qáẕar֙ r֣ẇẖa yĕhwá֔h ʼim-ʼé֖lėh maʻàlálá֑y⁠w hà⁠l֤wòʼ dĕbára֨⁠y yéyti֔ybẇ ʻi֖m ha⁠yá̇şá֥̌r hwòléֽkĕ׃"],[2,8,"וְ⁠אֶתְמ֗וּל עַמִּ⁠י֙ לְ⁠אוֹיֵ֣ב יְקוֹמֵ֔ם מִ⁠מּ֣וּל שַׂלְמָ֔ה אֶ֖דֶר תַּפְשִׁט֑וּ⁠ן מֵ⁠עֹבְרִ֣ים בֶּ֔טַח שׁוּבֵ֖י מִלְחָמָֽה׃","wĕ⁠ʼeţĕm֗ẇl ʻami̇⁠y֙ lĕ⁠ʼwòyé֣b yĕqwòmé֔m mi⁠ṁ֣ẇl şâlĕmá֔h ʼe֖der ţȧpĕşǐt֑ẇ⁠n mé⁠ʻòbĕri֣ym bė֔taẖ ş̌ẇbé֖y milĕẖámáֽh׃"],[2,9,"נְשֵׁ֤י עַמִּ⁠י֙ תְּגָ֣רְשׁ֔וּ⁠ן מִ⁠בֵּ֖ית תַּֽעֲנֻגֶ֑י⁠הָ מֵ⁠עַל֙ עֹֽלָלֶ֔י⁠הָ תִּקְח֥וּ הֲדָרִ֖⁠י לְ⁠עוֹלָֽם׃","nĕşé֤̌y ʻami̇⁠y֙ ţĕ̇gá֣rĕş̌֔ẇ⁠n mi⁠bé֖̇yţ ţȧֽʻànuge֑y⁠há mé⁠ʻal֙ ʻòֽlále֔y⁠há ţi̇qĕẖ֥ẇ hàdári֖⁠y lĕ⁠ʻwòláֽm׃"],[2,10,"ק֣וּמוּ וּ⁠לְכ֔וּ כִּ֥י לֹא־זֹ֖את הַ⁠מְּנוּחָ֑ה בַּ⁠עֲב֥וּר טָמְאָ֛ה תְּחַבֵּ֖ל וְ⁠חֶ֥בֶל נִמְרָֽץ׃","q֣ẇmẇ ẇ⁠lĕk֔ẇ ki֥̇y lòʼ-zò֖ʼţ ha⁠mĕ̇nẇẖá֑h bȧ⁠ʻàb֥ẇr támĕʼá֛h ţĕ̇ẖabé֖̇l wĕ⁠ẖe֥bel nimĕráֽẕ׃"],[2,11,"לוּ־אִ֞ישׁ הֹלֵ֥ךְ ר֨וּחַ֙ וָ⁠שֶׁ֣קֶר כִּזֵּ֔ב אַטִּ֣ף לְ⁠ךָ֔ לַ⁠יַּ֖יִן וְ⁠לַ⁠שֵּׁכָ֑ר וְ⁠הָיָ֥ה מַטִּ֖יף הָ⁠עָ֥ם הַ⁠זֶּֽה׃","lẇ-ʼi֞yş̌ hòlé֥kĕ r֨ẇẖa֙ wá⁠şě֣qer ki̇zé̇֔b ʼati֣̇p lĕ⁠ká֔ la⁠yȧ֖yin wĕ⁠la⁠şé̇̌ká֑r wĕ⁠háyá֥h mati֖̇yp há⁠ʻá֥m ha⁠zėֽh׃"],[2,12,"אָסֹ֨ף אֶאֱסֹ֜ף יַעֲקֹ֣ב כֻּלָּ֗⁠ךְ קַבֵּ֤ץ אֲקַבֵּץ֙ שְׁאֵרִ֣ית יִשְׂרָאֵ֔ל יַ֥חַד אֲשִׂימֶ֖⁠נּוּ כְּ⁠צֹ֣אן בָּצְרָ֑ה כְּ⁠עֵ֨דֶר֙ בְּ⁠ת֣וֹךְ הַ⁠דָּֽבְר֔⁠וֹ תְּהִימֶ֖נָה מֵ⁠אָדָֽם׃","ʼásò֨p ʼeʼèsò֜p yaʻàqò֣b ku̇lá̇֗⁠kĕ qabé֤̇ẕ ʼàqabé̇ẕ֙ şĕ̌ʼéri֣yţ yişĕ̂ráʼé֔l ya֥ẖad ʼàşîyme֖⁠ṅẇ kĕ̇⁠ẕò֣ʼn bá̇ẕĕrá֑h kĕ̇⁠ʻé֨der֙ bĕ̇⁠ţ֣wòkĕ ha⁠dáֽ̇bĕr֔⁠wò ţĕ̇hiyme֖náh mé⁠ʼádáֽm׃"],[2,13,"עָלָ֤ה הַ⁠פֹּרֵץ֙ לִ⁠פְנֵי⁠הֶ֔ם פָּֽרְצוּ֙ וַֽ⁠יַּעֲבֹ֔רוּ שַׁ֖עַר וַ⁠יֵּ֣צְאוּ ב֑⁠וֹ וַ⁠יַּעֲבֹ֤ר מַלְכָּ⁠ם֙ לִ⁠פְנֵי⁠הֶ֔ם וַ⁠יהוָ֖ה בְּ⁠רֹאשָֽׁ⁠ם׃פ","ʻálá֤h ha⁠pò̇réẕ֙ li⁠pĕnéy⁠he֔m páֽ̇rĕẕẇ֙ waֽ⁠yȧʻàbò֔rẇ şǎ֖ʻar wa⁠yé֣̇ẕĕʼẇ b֑⁠wò wa⁠yȧʻàbò֤r malĕká̇⁠m֙ li⁠pĕnéy⁠he֔m wa⁠yhwá֖h bĕ̇⁠ròʼşáֽ̌⁠m׃p"],[3,1,"וָ⁠אֹמַ֗ר שִׁמְעוּ־נָא֙ רָאשֵׁ֣י יַעֲקֹ֔ב וּ⁠קְצִינֵ֖י בֵּ֣ית יִשְׂרָאֵ֑ל הֲ⁠ל֣וֹא לָ⁠כֶ֔ם לָ⁠דַ֖עַת אֶת־הַ⁠מִּשְׁפָּֽט׃","wá⁠ʼòma֗r şǐmĕʻẇ-náʼ֙ ráʼşé֣̌y yaʻàqò֔b ẇ⁠qĕẕiyné֖y bé֣̇yţ yişĕ̂ráʼé֑l hà⁠l֣wòʼ lá⁠ke֔m lá⁠da֖ʻaţ ʼeţ-ha⁠mi̇şĕ̌páֽ̇t׃"],[3,2,"שֹׂ֥נְאֵי ט֖וֹב וְ⁠אֹ֣הֲבֵי רעה גֹּזְלֵ֤י עוֹרָ⁠ם֙ מֵֽ⁠עֲלֵי⁠הֶ֔ם וּ⁠שְׁאֵרָ֖⁠ם מֵ⁠עַ֥ל עַצְמוֹתָֽ⁠ם׃","şò֥̂nĕʼéy t֖wòb wĕ⁠ʼò֣hàbéy rʻh gò̇zĕlé֤y ʻwòrá⁠m֙ méֽ⁠ʻàléy⁠he֔m ẇ⁠şĕ̌ʼérá֖⁠m mé⁠ʻa֥l ʻaẕĕmwòţáֽ⁠m׃"],[3,3,"וַ⁠אֲשֶׁ֣ר אָכְלוּ֮ שְׁאֵ֣ר עַמִּ⁠י֒ וְ⁠עוֹרָ⁠ם֙ מֵ⁠עֲלֵי⁠הֶ֣ם הִפְשִׁ֔יטוּ וְ⁠אֶת־עַצְמֹֽתֵי⁠הֶ֖ם פִּצֵּ֑חוּ וּ⁠פָרְשׂוּ֙ כַּ⁠אֲשֶׁ֣ר בַּ⁠סִּ֔יר וּ⁠כְ⁠בָשָׂ֖ר בְּ⁠ת֥וֹךְ קַלָּֽחַת׃","wa⁠ʼàşě֣r ʼákĕlẇ֮ şĕ̌ʼé֣r ʻami̇⁠y֒ wĕ⁠ʻwòrá⁠m֙ mé⁠ʻàléy⁠he֣m hipĕşǐ֔ytẇ wĕ⁠ʼeţ-ʻaẕĕmòֽţéy⁠he֖m pi̇ẕé֑̇ẖẇ ẇ⁠párĕş̂ẇ֙ kȧ⁠ʼàşě֣r bȧ⁠si̇֔yr ẇ⁠kĕ⁠báşá֖̂r bĕ̇⁠ţ֥wòkĕ qaláֽ̇ẖaţ׃"],[3,4,"אָ֚ז יִזְעֲק֣וּ אֶל־יְהוָ֔ה וְ⁠לֹ֥א יַעֲנֶ֖ה אוֹתָ֑⁠ם וְ⁠יַסְתֵּ֨ר פָּנָ֤י⁠ו מֵ⁠הֶם֙ בָּ⁠עֵ֣ת הַ⁠הִ֔יא כַּ⁠אֲשֶׁ֥ר הֵרֵ֖עוּ מַעַלְלֵי⁠הֶֽם׃פ","ʼá֚z yizĕʻàq֣ẇ ʼel-yĕhwá֔h wĕ⁠lò֥ʼ yaʻàne֖h ʼwòţá֑⁠m wĕ⁠yasĕţé̇֨r pá̇ná֤y⁠w mé⁠hem֙ bá̇⁠ʻé֣ţ ha⁠hi֔yʼ kȧ⁠ʼàşě֥r héré֖ʻẇ maʻalĕléy⁠heֽm׃p"],[3,5,"כֹּ֚ה אָמַ֣ר יְהוָ֔ה עַל־הַ⁠נְּבִיאִ֖ים הַ⁠מַּתְעִ֣ים אֶת־עַמִּ֑⁠י הַ⁠נֹּשְׁכִ֤ים בְּ⁠שִׁנֵּי⁠הֶם֙ וְ⁠קָרְא֣וּ שָׁל֔וֹם וַ⁠אֲשֶׁר֙ לֹא־יִתֵּ֣ן עַל־פִּי⁠הֶ֔ם וְ⁠קִדְּשׁ֥וּ עָלָ֖י⁠ו מִלְחָמָֽה׃","kò֚̇h ʼáma֣r yĕhwá֔h ʻal-ha⁠nĕ̇biyʼi֖ym ha⁠mȧţĕʻi֣ym ʼeţ-ʻami֑̇⁠y ha⁠nò̇şĕ̌ki֤ym bĕ̇⁠şǐné̇y⁠hem֙ wĕ⁠qárĕʼ֣ẇ şá̌l֔wòm wa⁠ʼàşěr֙ lòʼ-yiţé֣̇n ʻal-pi̇y⁠he֔m wĕ⁠qidĕ̇ş֥̌ẇ ʻálá֖y⁠w milĕẖámáֽh׃"],[3,6,"לָ⁠כֵ֞ן לַ֤יְלָה לָ⁠כֶם֙ מֵֽ⁠חָז֔וֹן וְ⁠חָשְׁכָ֥ה לָ⁠כֶ֖ם מִ⁠קְּסֹ֑ם וּ⁠בָ֤אָה הַ⁠שֶּׁ֨מֶשׁ֙ עַל־הַ⁠נְּבִיאִ֔ים וְ⁠קָדַ֥ר עֲלֵי⁠הֶ֖ם הַ⁠יּֽוֹם׃","lá⁠ké֞n la֤yĕláh lá⁠kem֙ méֽ⁠ẖáz֔wòn wĕ⁠ẖáşĕ̌ká֥h lá⁠ke֖m mi⁠qĕ̇sò֑m ẇ⁠bá֤ʼáh ha⁠şė̌֨meş̌֙ ʻal-ha⁠nĕ̇biyʼi֔ym wĕ⁠qáda֥r ʻàléy⁠he֖m ha⁠ẏֽwòm׃"],[3,7,"וּ⁠בֹ֣שׁוּ הַ⁠חֹזִ֗ים וְ⁠חָֽפְרוּ֙ הַ⁠קֹּ֣סְמִ֔ים וְ⁠עָט֥וּ עַל־שָׂפָ֖ם כֻּלָּ֑⁠ם כִּ֛י אֵ֥ין מַעֲנֵ֖ה אֱלֹהִֽים׃","ẇ⁠bò֣ş̌ẇ ha⁠ẖòzi֗ym wĕ⁠ẖáֽpĕrẇ֙ ha⁠qò֣̇sĕmi֔ym wĕ⁠ʻát֥ẇ ʻal-şá̂pá֖m ku̇lá֑̇⁠m ki֛̇y ʼé֥yn maʻàné֖h ʼèlòhiֽym׃"],[3,8,"וְ⁠אוּלָ֗ם אָנֹכִ֞י מָלֵ֤אתִי כֹ֨חַ֙ אֶת־ר֣וּחַ יְהוָ֔ה וּ⁠מִשְׁפָּ֖ט וּ⁠גְבוּרָ֑ה לְ⁠הַגִּ֤יד לְ⁠יַֽעֲקֹב֙ פִּשְׁע֔⁠וֹ וּ⁠לְ⁠יִשְׂרָאֵ֖ל חַטָּאתֽ⁠וֹ׃ס","wĕ⁠ʼẇlá֗m ʼánòki֞y málé֤ʼţiy kò֨ẖa֙ ʼeţ-r֣ẇẖa yĕhwá֔h ẇ⁠mişĕ̌pá֖̇t ẇ⁠gĕbẇrá֑h lĕ⁠hagi֤̇yd lĕ⁠yaֽʻàqòb֙ pi̇şĕ̌ʻ֔⁠wò ẇ⁠lĕ⁠yişĕ̂ráʼé֖l ẖatá̇ʼţֽ⁠wò׃s"],[3,9,"שִׁמְעוּ־נָ֣א זֹ֗את רָאשֵׁי֙ בֵּ֣ית יַעֲקֹ֔ב וּ⁠קְצִינֵ֖י בֵּ֣ית יִשְׂרָאֵ֑ל הַֽ⁠מֲתַעֲבִ֣ים מִשְׁפָּ֔ט וְ⁠אֵ֥ת כָּל־הַ⁠יְשָׁרָ֖ה יְעַקֵּֽשׁוּ׃","şǐmĕʻẇ-ná֣ʼ zò֗ʼţ ráʼşé̌y֙ bé֣̇yţ yaʻàqò֔b ẇ⁠qĕẕiyné֖y bé֣̇yţ yişĕ̂ráʼé֑l haֽ⁠màţaʻàbi֣ym mişĕ̌pá̇֔t wĕ⁠ʼé֥ţ ká̇l-ha⁠yĕşá̌rá֖h yĕʻaqéֽ̇ş̌ẇ׃"],[3,10,"בֹּנֶ֥ה צִיּ֖וֹן בְּ⁠דָמִ֑ים וִ⁠ירוּשָׁלִַ֖ם בְּ⁠עַוְלָֽה׃","bò̇ne֥h ẕiẏ֖wòn bĕ̇⁠dámi֑ym wi⁠yrẇşá̌lia֖m bĕ̇⁠ʻawĕláֽh׃"],[3,11,"רָאשֶׁ֣י⁠הָ ׀ בְּ⁠שֹׁ֣חַד יִשְׁפֹּ֗טוּ וְ⁠כֹהֲנֶ֨י⁠הָ֙ בִּ⁠מְחִ֣יר יוֹר֔וּ וּ⁠נְבִיאֶ֖י⁠הָ בְּ⁠כֶ֣סֶף יִקְסֹ֑מוּ וְ⁠עַל־יְהוָה֙ יִשָּׁעֵ֣נוּ לֵ⁠אמֹ֔ר הֲ⁠ל֤וֹא יְהוָה֙ בְּ⁠קִרְבֵּ֔⁠נוּ לֹֽא־תָב֥וֹא עָלֵ֖י⁠נוּ רָעָֽה׃","ráʼşě֣y⁠há ׀ bĕ̇⁠şò֣̌ẖad yişĕ̌pò̇֗tẇ wĕ⁠kòhàne֨y⁠há֙ bi̇⁠mĕẖi֣yr ywòr֔ẇ ẇ⁠nĕbiyʼe֖y⁠há bĕ̇⁠ke֣sep yiqĕsò֑mẇ wĕ⁠ʻal-yĕhwáh֙ yişá̇̌ʻé֣nẇ lé⁠ʼmò֔r hà⁠l֤wòʼ yĕhwáh֙ bĕ̇⁠qirĕbé̇֔⁠nẇ lòֽʼ-ţáb֥wòʼ ʻálé֖y⁠nẇ ráʻáֽh׃"],[3,12,"לָ⁠כֵן֙ בִּ⁠גְלַלְ⁠כֶ֔ם צִיּ֖וֹן שָׂדֶ֣ה תֵֽחָרֵ֑שׁ וִ⁠ירוּשָׁלִַ֨ם֙ עִיִּ֣ין תִּֽהְיֶ֔ה וְ⁠הַ֥ר הַ⁠בַּ֖יִת לְ⁠בָמ֥וֹת יָֽעַר׃פ","lá⁠kén֙ bi̇⁠gĕlalĕ⁠ke֔m ẕiẏ֖wòn şá̂de֣h ţéֽẖáré֑ş̌ wi⁠yrẇşá̌lia֨m֙ ʻiyi֣̇yn ţiֽ̇hĕye֔h wĕ⁠ha֥r ha⁠bȧ֖yiţ lĕ⁠bám֥wòţ yáֽʻar׃p"],[4,1,"וְ⁠הָיָ֣ה ׀ בְּ⁠אַחֲרִ֣ית הַ⁠יָּמִ֗ים יִ֠הְיֶה הַ֣ר בֵּית־יְהוָ֤ה נָכוֹן֙ בְּ⁠רֹ֣אשׁ הֶ⁠הָרִ֔ים וְ⁠נִשָּׂ֥א ה֖וּא מִ⁠גְּבָע֑וֹת וְ⁠נָהֲר֥וּ עָלָ֖י⁠ו עַמִּֽים׃","wĕ⁠háyá֣h ׀ bĕ̇⁠ʼaẖàri֣yţ ha⁠yá̇mi֗ym yi֠hĕyeh ha֣r bé̇yţ-yĕhwá֤h nákwòn֙ bĕ̇⁠rò֣ʼş̌ he⁠hári֔ym wĕ⁠nişá֥̇̂ʼ h֖ẇʼ mi⁠gĕ̇báʻ֑wòţ wĕ⁠náhàr֥ẇ ʻálá֖y⁠w ʻamiֽ̇ym׃"],[4,2,"וְֽ⁠הָלְכ֞וּ גּוֹיִ֣ם רַבִּ֗ים וְ⁠אָֽמְרוּ֙ לְכ֣וּ ׀ וְ⁠נַעֲלֶ֣ה אֶל־הַר־יְהוָ֗ה וְ⁠אֶל־בֵּית֙ אֱלֹהֵ֣י יַעֲקֹ֔ב וְ⁠יוֹרֵ֨⁠נוּ֙ מִ⁠דְּרָכָ֔י⁠ו וְ⁠נֵלְכָ֖ה בְּ⁠אֹֽרְחֹתָ֑י⁠ו כִּ֤י מִ⁠צִּיּוֹן֙ תֵּצֵ֣א תוֹרָ֔ה וּ⁠דְבַר־יְהוָ֖ה מִ⁠ירוּשָׁלִָֽם׃","wĕֽ⁠hálĕk֞ẇ ġwòyi֣m rabi̇֗ym wĕ⁠ʼáֽmĕrẇ֙ lĕk֣ẇ ׀ wĕ⁠naʻàle֣h ʼel-har-yĕhwá֗h wĕ⁠ʼel-bé̇yţ֙ ʼèlòhé֣y yaʻàqò֔b wĕ⁠ywòré֨⁠nẇ֙ mi⁠dĕ̇ráká֔y⁠w wĕ⁠nélĕká֖h bĕ̇⁠ʼòֽrĕẖòţá֑y⁠w ki֤̇y mi⁠ẕi̇ẏwòn֙ ţé̇ẕé֣ʼ ţwòrá֔h ẇ⁠dĕbar-yĕhwá֖h mi⁠yrẇşá̌liáֽm׃"],[4,3,"וְ⁠שָׁפַ֗ט בֵּ֚ין עַמִּ֣ים רַבִּ֔ים וְ⁠הוֹכִ֛יחַ לְ⁠גוֹיִ֥ם עֲצֻמִ֖ים עַד־רָח֑וֹק וְ⁠כִתְּת֨וּ חַרְבֹתֵי⁠הֶ֜ם לְ⁠אִתִּ֗ים וַ⁠חֲנִיתֹֽתֵי⁠הֶם֙ לְ⁠מַזְמֵר֔וֹת לֹֽא־יִשְׂא֞וּ גּ֤וֹי אֶל־גּוֹי֙ חֶ֔רֶב וְ⁠לֹא־יִלְמְד֥וּ⁠ן ע֖וֹד מִלְחָמָֽה׃","wĕ⁠şá̌pa֗t bé֚̇yn ʻami֣̇ym rabi̇֔ym wĕ⁠hwòki֛yẖa lĕ⁠gwòyi֥m ʻàẕumi֖ym ʻad-ráẖ֑wòq wĕ⁠kiţĕ̇ţ֨ẇ ẖarĕbòţéy⁠he֜m lĕ⁠ʼiţi̇֗ym wa⁠ẖàniyţòֽţéy⁠hem֙ lĕ⁠mazĕmér֔wòţ lòֽʼ-yişĕ̂ʼ֞ẇ ġ֤wòy ʼel-ġwòy֙ ẖe֔reb wĕ⁠lòʼ-yilĕmĕd֥ẇ⁠n ʻ֖wòd milĕẖámáֽh׃"],[4,4,"וְ⁠יָשְׁב֗וּ אִ֣ישׁ תַּ֧חַת גַּפְנ֛⁠וֹ וְ⁠תַ֥חַת תְּאֵנָת֖⁠וֹ וְ⁠אֵ֣ין מַחֲרִ֑יד כִּי־פִ֛י יְהוָ֥ה צְבָא֖וֹת דִּבֵּֽר׃","wĕ⁠yáşĕ̌b֗ẇ ʼi֣yş̌ ţȧ֧ẖaţ gȧpĕn֛⁠wò wĕ⁠ţa֥ẖaţ ţĕ̇ʼénáţ֖⁠wò wĕ⁠ʼé֣yn maẖàri֑yd ki̇y-pi֛y yĕhwá֥h ẕĕbáʼ֖wòţ di̇béֽ̇r׃"],[4,5,"כִּ֚י כָּל־הָ֣⁠עַמִּ֔ים יֵלְכ֕וּ אִ֖ישׁ בְּ⁠שֵׁ֣ם אֱלֹהָ֑י⁠ו וַ⁠אֲנַ֗חְנוּ נֵלֵ֛ךְ בְּ⁠שֵׁם־יְהוָ֥ה אֱלֹהֵ֖י⁠נוּ לְ⁠עוֹלָ֥ם וָ⁠עֶֽד׃פ","ki֚̇y ká̇l-há֣⁠ʻami̇֔ym yélĕk֕ẇ ʼi֖yş̌ bĕ̇⁠şé֣̌m ʼèlòhá֑y⁠w wa⁠ʼàna֗ẖĕnẇ nélé֛kĕ bĕ̇⁠şé̌m-yĕhwá֥h ʼèlòhé֖y⁠nẇ lĕ⁠ʻwòlá֥m wá⁠ʻeֽd׃p"],[4,6,"בַּ⁠יּ֨וֹם הַ⁠ה֜וּא נְאֻם־יְהוָ֗ה אֹֽסְפָה֙ הַ⁠צֹּ֣לֵעָ֔ה וְ⁠הַ⁠נִּדָּחָ֖ה אֲקַבֵּ֑צָה וַ⁠אֲשֶׁ֖ר הֲרֵעֹֽתִי׃","bȧ⁠ẏ֨wòm ha⁠h֜ẇʼ nĕʼum-yĕhwá֗h ʼòֽsĕpáh֙ ha⁠ẕò֣̇léʻá֔h wĕ⁠ha⁠ni̇dá̇ẖá֖h ʼàqabé֑̇ẕáh wa⁠ʼàşě֖r hàréʻòֽţiy׃"],[4,7,"וְ⁠שַׂמְתִּ֤י אֶת־הַ⁠צֹּֽלֵעָה֙ לִ⁠שְׁאֵרִ֔ית וְ⁠הַ⁠נַּהֲלָאָ֖ה לְ⁠ג֣וֹי עָצ֑וּם וּ⁠מָלַ֨ךְ יְהוָ֤ה עֲלֵי⁠הֶם֙ בְּ⁠הַ֣ר צִיּ֔וֹן מֵ⁠עַתָּ֖ה וְ⁠עַד־עוֹלָֽם׃פ","wĕ⁠şâmĕţi֤̇y ʼeţ-ha⁠ẕòֽ̇léʻáh֙ li⁠şĕ̌ʼéri֔yţ wĕ⁠ha⁠nȧhàláʼá֖h lĕ⁠g֣wòy ʻáẕ֑ẇm ẇ⁠mála֨kĕ yĕhwá֤h ʻàléy⁠hem֙ bĕ̇⁠ha֣r ẕiẏ֔wòn mé⁠ʻaţá֖̇h wĕ⁠ʻad-ʻwòláֽm׃p"],[4,8,"וְ⁠אַתָּ֣ה מִגְדַּל־עֵ֗דֶר עֹ֛פֶל בַּת־צִיּ֖וֹן עָדֶ֣י⁠ךָ תֵּאתֶ֑ה וּ⁠בָאָ֗ה הַ⁠מֶּמְשָׁלָה֙ הָ⁠רִ֣אשֹׁנָ֔ה מַמְלֶ֖כֶת לְ⁠בַ֥ת־יְרוּשָׁלִָֽם׃","wĕ⁠ʼaţá֣̇h migĕdȧl-ʻé֗der ʻò֛pel bȧţ-ẕiẏ֖wòn ʻáde֣y⁠ká ţé̇ʼţe֑h ẇ⁠báʼá֗h ha⁠mėmĕşá̌láh֙ há⁠ri֣ʼşò̌ná֔h mamĕle֖keţ lĕ⁠ba֥ţ-yĕrẇşá̌liáֽm׃"],[4,9,"עַתָּ֕ה לָ֥⁠מָּה תָרִ֖יעִי רֵ֑עַ הֲ⁠מֶ֣לֶךְ אֵֽין־בָּ֗⁠ךְ אִֽם־יוֹעֲצֵ⁠ךְ֙ אָבָ֔ד כִּֽי־הֶחֱזִיקֵ֥⁠ךְ חִ֖יל כַּ⁠יּוֹלֵדָֽה׃","ʻaţá̇֕h lá֥⁠má̇h ţári֖yʻiy ré֑ʻa hà⁠me֣lekĕ ʼéֽyn-bá̇֗⁠kĕ ʼiֽm-ywòʻàẕé⁠kĕ֙ ʼábá֔d kiֽ̇y-heẖèziyqé֥⁠kĕ ẖi֖yl kȧ⁠ẏwòlédáֽh׃"],[4,10,"ח֧וּלִי וָ⁠גֹ֛חִי בַּת־צִיּ֖וֹן כַּ⁠יּֽוֹלֵדָ֑ה כִּֽי־עַתָּה֩ תֵצְאִ֨י מִ⁠קִּרְיָ֜ה וְ⁠שָׁכַ֣נְתְּ בַּ⁠שָּׂדֶ֗ה וּ⁠בָ֤את עַד־בָּבֶל֙ שָׁ֣ם תִּנָּצֵ֔לִי שָׁ֚ם יִגְאָלֵ֣⁠ךְ יְהוָ֔ה מִ⁠כַּ֖ף אֹיְבָֽיִ⁠ךְ׃","ẖ֧ẇliy wá⁠gò֛ẖiy bȧţ-ẕiẏ֖wòn kȧ⁠ẏֽwòlédá֑h kiֽ̇y-ʻaţá̇h֩ ţéẕĕʼi֨y mi⁠qi̇rĕyá֜h wĕ⁠şá̌ka֣nĕţĕ̇ bȧ⁠şá̇̂de֗h ẇ⁠bá֤ʼţ ʻad-bá̇bel֙ şá֣̌m ţi̇ná̇ẕé֔liy şá֚̌m yigĕʼálé֣⁠kĕ yĕhwá֔h mi⁠kȧ֖p ʼòyĕbáֽyi⁠kĕ׃"],[4,11,"וְ⁠עַתָּ֛ה נֶאֶסְפ֥וּ עָלַ֖יִ⁠ךְ גּוֹיִ֣ם רַבִּ֑ים הָ⁠אֹמְרִ֣ים תֶּחֱנָ֔ף וְ⁠תַ֥חַז בְּ⁠צִיּ֖וֹן עֵינֵֽי⁠נוּ׃","wĕ⁠ʻaţá֛̇h neʼesĕp֥ẇ ʻála֖yi⁠kĕ ġwòyi֣m rabi֑̇ym há⁠ʼòmĕri֣ym ţėẖèná֔p wĕ⁠ţa֥ẖaz bĕ̇⁠ẕiẏ֖wòn ʻéynéֽy⁠nẇ׃"],[4,12,"וְ⁠הֵ֗מָּה לֹ֤א יָֽדְעוּ֙ מַחְשְׁב֣וֹת יְהוָ֔ה וְ⁠לֹ֥א הֵבִ֖ינוּ עֲצָת֑⁠וֹ כִּ֥י קִבְּצָ֖⁠ם כֶּ⁠עָמִ֥יר גֹּֽרְנָ⁠ה׃","wĕ⁠hé֗má̇h lò֤ʼ yáֽdĕʻẇ֙ maẖĕşĕ̌b֣wòţ yĕhwá֔h wĕ⁠lò֥ʼ hébi֖ynẇ ʻàẕáţ֑⁠wò ki֥̇y qibĕ̇ẕá֖⁠m kė⁠ʻámi֥yr gòֽ̇rĕná⁠h׃"],[4,13,"ק֧וּמִי וָ⁠ד֣וֹשִׁי בַת־צִיּ֗וֹן כִּֽי־קַרְנֵ֞⁠ךְ אָשִׂ֤ים בַּרְזֶל֙ וּ⁠פַרְסֹתַ֨יִ⁠ךְ֙ אָשִׂ֣ים נְחוּשָׁ֔ה וַ⁠הֲדִקּ֖וֹת עַמִּ֣ים רַבִּ֑ים וְ⁠הַחֲרַמְתִּ֤י לַֽ⁠יהוָה֙ בִּצְעָ֔⁠ם וְ⁠חֵילָ֖⁠ם לַ⁠אֲד֥וֹן כָּל־הָ⁠אָֽרֶץ׃","q֧ẇmiy wá⁠d֣wòşǐy baţ-ẕiẏ֗wòn kiֽ̇y-qarĕné֞⁠kĕ ʼáşî֤ym bȧrĕzel֙ ẇ⁠parĕsòţa֨yi⁠kĕ֙ ʼáşî֣ym nĕẖẇşá̌֔h wa⁠hàdiq֖̇wòţ ʻami֣̇ym rabi֑̇ym wĕ⁠haẖàramĕţi֤̇y laֽ⁠yhwáh֙ bi̇ẕĕʻá֔⁠m wĕ⁠ẖéylá֖⁠m la⁠ʼàd֥wòn ká̇l-há⁠ʼáֽreẕ׃"],[5,1,"עַתָּה֙ תִּתְגֹּדְדִ֣י בַת־גְּד֔וּד מָצ֖וֹר שָׂ֣ם עָלֵ֑י⁠נוּ בַּ⁠שֵּׁ֨בֶט֙ יַכּ֣וּ עַֽל־הַ⁠לְּחִ֔י אֵ֖ת שֹׁפֵ֥ט יִשְׂרָאֵֽל׃ס","ʻaţá̇h֙ ţi̇ţĕgò̇dĕdi֣y baţ-gĕ̇d֔ẇd máẕ֖wòr şá֣̂m ʻálé֑y⁠nẇ bȧ⁠şé̇̌֨bet֙ yak֣̇ẇ ʻaֽl-ha⁠lĕ̇ẖi֔y ʼé֖ţ şò̌pé֥t yişĕ̂ráʼéֽl׃s"],[5,2,"וְ⁠אַתָּ֞ה בֵּֽית־לֶ֣חֶם אֶפְרָ֗תָה צָעִיר֙ לִֽ⁠הְיוֹת֙ בְּ⁠אַלְפֵ֣י יְהוּדָ֔ה מִמְּ⁠ךָ֙ לִ֣⁠י יֵצֵ֔א לִֽ⁠הְי֥וֹת מוֹשֵׁ֖ל בְּ⁠יִשְׂרָאֵ֑ל וּ⁠מוֹצָאֹתָ֥י⁠ו מִ⁠קֶּ֖דֶם מִ⁠ימֵ֥י עוֹלָֽם׃","wĕ⁠ʼaţá̇֞h béֽ̇yţ-le֣ẖem ʼepĕrá֗ţáh ẕáʻiyr֙ liֽ⁠hĕywòţ֙ bĕ̇⁠ʼalĕpé֣y yĕhẇdá֔h mimĕ̇⁠ká֙ li֣⁠y yéẕé֔ʼ liֽ⁠hĕy֥wòţ mwòşé֖̌l bĕ̇⁠yişĕ̂ráʼé֑l ẇ⁠mwòẕáʼòţá֥y⁠w mi⁠qė֖dem mi⁠ymé֥y ʻwòláֽm׃"],[5,3,"לָ⁠כֵ֣ן יִתְּנֵ֔⁠ם עַד־עֵ֥ת יוֹלֵדָ֖ה יָלָ֑דָה וְ⁠יֶ֣תֶר אֶחָ֔י⁠ו יְשׁוּב֖וּ⁠ן עַל־בְּנֵ֥י יִשְׂרָאֵֽל׃","lá⁠ké֣n yiţĕ̇né֔⁠m ʻad-ʻé֥ţ ywòlédá֖h yálá֑dáh wĕ⁠ye֣ţer ʼeẖá֔y⁠w yĕş̌ẇb֖ẇ⁠n ʻal-bĕ̇né֥y yişĕ̂ráʼéֽl׃"],[5,4,"וְ⁠עָמַ֗ד וְ⁠רָעָה֙ בְּ⁠עֹ֣ז יְהוָ֔ה בִּ⁠גְא֕וֹן שֵׁ֖ם יְהוָ֣ה אֱלֹהָ֑י⁠ו וְ⁠יָשָׁ֕בוּ כִּֽי־עַתָּ֥ה יִגְדַּ֖ל עַד־אַפְסֵי־אָֽרֶץ׃","wĕ⁠ʻáma֗d wĕ⁠ráʻáh֙ bĕ̇⁠ʻò֣z yĕhwá֔h bi̇⁠gĕʼ֕wòn şé֖̌m yĕhwá֣h ʼèlòhá֑y⁠w wĕ⁠yáşá̌֕bẇ kiֽ̇y-ʻaţá֥̇h yigĕdȧ֖l ʻad-ʼapĕséy-ʼáֽreẕ׃"],[5,5,"וְ⁠הָיָ֥ה זֶ֖ה שָׁל֑וֹם אַשּׁ֣וּר ׀ כִּֽי־יָב֣וֹא בְ⁠אַרְצֵ֗⁠נוּ וְ⁠כִ֤י יִדְרֹךְ֙ בְּ⁠אַרְמְנֹתֵ֔י⁠נוּ וַ⁠הֲקֵמֹ֤נוּ עָלָי⁠ו֙ שִׁבְעָ֣ה רֹעִ֔ים וּ⁠שְׁמֹנָ֖ה נְסִיכֵ֥י אָדָֽם׃","wĕ⁠háyá֥h ze֖h şá̌l֑wòm ʼaş֣̇̌ẇr ׀ kiֽ̇y-yáb֣wòʼ bĕ⁠ʼarĕẕé֗⁠nẇ wĕ⁠ki֤y yidĕròkĕ֙ bĕ̇⁠ʼarĕmĕnòţé֔y⁠nẇ wa⁠hàqémò֤nẇ ʻáláy⁠w֙ şǐbĕʻá֣h ròʻi֔ym ẇ⁠şĕ̌mòná֖h nĕsiyké֥y ʼádáֽm׃"],[5,6,"וְ⁠רָע֞וּ אֶת־אֶ֤רֶץ אַשּׁוּר֙ בַּ⁠חֶ֔רֶב וְ⁠אֶת־אֶ֥רֶץ נִמְרֹ֖ד בִּ⁠פְתָחֶ֑י⁠הָ וְ⁠הִצִּיל֙ מֵֽ⁠אַשּׁ֔וּר כִּֽי־יָב֣וֹא בְ⁠אַרְצֵ֔⁠נוּ וְ⁠כִ֥י יִדְרֹ֖ךְ בִּ⁠גְבוּלֵֽ⁠נוּ׃ס","wĕ⁠ráʻ֞ẇ ʼeţ-ʼe֤reẕ ʼaş̇̌ẇr֙ bȧ⁠ẖe֔reb wĕ⁠ʼeţ-ʼe֥reẕ nimĕrò֖d bi̇⁠pĕţáẖe֑y⁠há wĕ⁠hiẕi̇yl֙ méֽ⁠ʼaş̇̌֔ẇr kiֽ̇y-yáb֣wòʼ bĕ⁠ʼarĕẕé֔⁠nẇ wĕ⁠ki֥y yidĕrò֖kĕ bi̇⁠gĕbẇléֽ⁠nẇ׃s"],[5,7,"וְ⁠הָיָ֣ה ׀ שְׁאֵרִ֣ית יַעֲקֹ֗ב בְּ⁠קֶ֨רֶב֙ עַמִּ֣ים רַבִּ֔ים כְּ⁠טַל֙ מֵ⁠אֵ֣ת יְהוָ֔ה כִּ⁠רְבִיבִ֖ים עֲלֵי־עֵ֑שֶׂב אֲשֶׁ֤ר לֹֽא־יְקַוֶּה֙ לְ⁠אִ֔ישׁ וְ⁠לֹ֥א יְיַחֵ֖ל לִ⁠בְנֵ֥י אָדָֽם׃","wĕ⁠háyá֣h ׀ şĕ̌ʼéri֣yţ yaʻàqò֗b bĕ̇⁠qe֨reb֙ ʻami֣̇ym rabi̇֔ym kĕ̇⁠tal֙ mé⁠ʼé֣ţ yĕhwá֔h ki̇⁠rĕbiybi֖ym ʻàléy-ʻé֑şêb ʼàşě֤r lòֽʼ-yĕqawėh֙ lĕ⁠ʼi֔yş̌ wĕ⁠lò֥ʼ yĕyaẖé֖l li⁠bĕné֥y ʼádáֽm׃"],[5,8,"וְ⁠הָיָה֩ שְׁאֵרִ֨ית יַעֲקֹ֜ב בַּ⁠גּוֹיִ֗ם בְּ⁠קֶ֨רֶב֙ עַמִּ֣ים רַבִּ֔ים כְּ⁠אַרְיֵה֙ בְּ⁠בַהֲמ֣וֹת יַ֔עַר כִּ⁠כְפִ֖יר בְּ⁠עֶדְרֵי צֹ֑אן אֲשֶׁ֧ר אִם עָבַ֛ר וְ⁠רָמַ֥ס וְ⁠טָרַ֖ף וְ⁠אֵ֥ין מַצִּֽיל׃","wĕ⁠háyáh֩ şĕ̌ʼéri֨yţ yaʻàqò֜b bȧ⁠ġwòyi֗m bĕ̇⁠qe֨reb֙ ʻami֣̇ym rabi̇֔ym kĕ̇⁠ʼarĕyéh֙ bĕ̇⁠bahàm֣wòţ ya֔ʻar ki̇⁠kĕpi֖yr bĕ̇⁠ʻedĕréy ẕò֑ʼn ʼàşě֧r ʼim ʻába֛r wĕ⁠ráma֥s wĕ⁠tára֖p wĕ⁠ʼé֥yn maẕiֽ̇yl׃"],[5,9,"תָּרֹ֥ם יָדְ⁠ךָ֖ עַל־צָרֶ֑י⁠ךָ וְ⁠כָל־אֹיְבֶ֖י⁠ךָ יִכָּרֵֽתוּ׃פ","ţá̇rò֥m yádĕ⁠ká֖ ʻal-ẕáre֑y⁠ká wĕ⁠kál-ʼòyĕbe֖y⁠ká yiká̇réֽţẇ׃p"],[5,10,"וְ⁠הָיָ֤ה בַ⁠יּוֹם־הַ⁠הוּא֙ נְאֻם־יְהוָ֔ה וְ⁠הִכְרַתִּ֥י סוּסֶ֖י⁠ךָ מִ⁠קִּרְבֶּ֑⁠ךָ וְ⁠הַאֲבַדְתִּ֖י מַרְכְּבֹתֶֽי⁠ךָ׃","wĕ⁠háyá֤h ba⁠ẏwòm-ha⁠hẇʼ֙ nĕʼum-yĕhwá֔h wĕ⁠hikĕraţi֥̇y sẇse֖y⁠ká mi⁠qi̇rĕbė֑⁠ká wĕ⁠haʼàbadĕţi֖̇y marĕkĕ̇bòţeֽy⁠ká׃"],[5,11,"וְ⁠הִכְרַתִּ֖י עָרֵ֣י אַרְצֶ֑⁠ךָ וְ⁠הָרַסְתִּ֖י כָּל־מִבְצָרֶֽי⁠ךָ׃","wĕ⁠hikĕraţi֖̇y ʻáré֣y ʼarĕẕe֑⁠ká wĕ⁠hárasĕţi֖̇y ká̇l-mibĕẕáreֽy⁠ká׃"],[5,12,"וְ⁠הִכְרַתִּ֥י כְשָׁפִ֖ים מִ⁠יָּדֶ֑⁠ךָ וּֽ⁠מְעוֹנְנִ֖ים לֹ֥א יִֽהְיוּ־לָֽ⁠ךְ׃","wĕ⁠hikĕraţi֥̇y kĕşá̌pi֖ym mi⁠yá̇de֑⁠ká ẇֽ⁠mĕʻwònĕni֖ym lò֥ʼ yiֽhĕyẇ-láֽ⁠kĕ׃"],[5,13,"וְ⁠הִכְרַתִּ֧י פְסִילֶ֛י⁠ךָ וּ⁠מַצֵּבוֹתֶ֖י⁠ךָ מִ⁠קִּרְבֶּ֑⁠ךָ וְ⁠לֹֽא־תִשְׁתַּחֲוֶ֥ה ע֖וֹד לְ⁠מַעֲשֵׂ֥ה יָדֶֽי⁠ךָ׃","wĕ⁠hikĕraţi֧̇y pĕsiyle֛y⁠ká ẇ⁠maẕé̇bwòţe֖y⁠ká mi⁠qi̇rĕbė֑⁠ká wĕ⁠lòֽʼ-ţişĕ̌ţȧẖàwe֥h ʻ֖wòd lĕ⁠maʻàşé֥̂h yádeֽy⁠ká׃"],[5,14,"וְ⁠נָתַשְׁתִּ֥י אֲשֵׁירֶ֖י⁠ךָ מִ⁠קִּרְבֶּ֑⁠ךָ וְ⁠הִשְׁמַדְתִּ֖י עָרֶֽי⁠ךָ׃","wĕ⁠náţaşĕ̌ţi֥̇y ʼàşé̌yre֖y⁠ká mi⁠qi̇rĕbė֑⁠ká wĕ⁠hişĕ̌madĕţi֖̇y ʻáreֽy⁠ká׃"],[5,15,"וְ⁠עָשִׂ֜יתִי בְּ⁠אַ֧ף וּ⁠בְ⁠חֵמָ֛ה נָקָ֖ם אֶת־הַ⁠גּוֹיִ֑ם אֲשֶׁ֖ר לֹ֥א שָׁמֵֽעוּ׃ס","wĕ⁠ʻáşî֜yţiy bĕ̇⁠ʼa֧p ẇ⁠bĕ⁠ẖémá֛h náqá֖m ʼeţ-ha⁠ġwòyi֑m ʼàşě֖r lò֥ʼ şá̌méֽʻẇ׃s"],[6,1,"שִׁמְעוּ־נָ֕א אֵ֥ת אֲשֶׁר־יְהוָ֖ה אֹמֵ֑ר ק֚וּם רִ֣יב אֶת־הֶ⁠הָרִ֔ים וְ⁠תִשְׁמַ֥עְנָה הַ⁠גְּבָע֖וֹת קוֹלֶֽ⁠ךָ׃","şǐmĕʻẇ-ná֕ʼ ʼé֥ţ ʼàşěr-yĕhwá֖h ʼòmé֑r q֚ẇm ri֣yb ʼeţ-he⁠hári֔ym wĕ⁠ţişĕ̌ma֥ʻĕnáh ha⁠gĕ̇báʻ֖wòţ qwòleֽ⁠ká׃"],[6,2,"שִׁמְע֤וּ הָרִים֙ אֶת־רִ֣יב יְהוָ֔ה וְ⁠הָ⁠אֵתָנִ֖ים מֹ֣סְדֵי אָ֑רֶץ כִּ֣י רִ֤יב לַֽ⁠יהוָה֙ עִם־עַמּ֔⁠וֹ וְ⁠עִם־יִשְׂרָאֵ֖ל יִתְוַכָּֽח׃","şǐmĕʻ֤ẇ háriym֙ ʼeţ-ri֣yb yĕhwá֔h wĕ⁠há⁠ʼéţáni֖ym mò֣sĕdéy ʼá֑reẕ ki֣̇y ri֤yb laֽ⁠yhwáh֙ ʻim-ʻaṁ֔⁠wò wĕ⁠ʻim-yişĕ̂ráʼé֖l yiţĕwakáֽ̇ẖ׃"],[6,3,"עַמִּ֛⁠י מֶה־עָשִׂ֥יתִי לְ⁠ךָ֖ וּ⁠מָ֣ה הֶלְאֵתִ֑י⁠ךָ עֲנֵ֥ה בִּֽ⁠י׃","ʻami֛̇⁠y meh-ʻáşî֥yţiy lĕ⁠ká֖ ẇ⁠má֣h helĕʼéţi֑y⁠ká ʻàné֥h biֽ̇⁠y׃"],[6,4,"כִּ֤י הֶעֱלִתִ֨י⁠ךָ֙ מֵ⁠אֶ֣רֶץ מִצְרַ֔יִם וּ⁠מִ⁠בֵּ֥ית עֲבָדִ֖ים פְּדִיתִ֑י⁠ךָ וָ⁠אֶשְׁלַ֣ח לְ⁠פָנֶ֔י⁠ךָ אֶת־מֹשֶׁ֖ה אַהֲרֹ֥ן וּ⁠מִרְיָֽם׃","ki֤̇y heʻèliţi֨y⁠ká֙ mé⁠ʼe֣reẕ miẕĕra֔yim ẇ⁠mi⁠bé֥̇yţ ʻàbádi֖ym pĕ̇diyţi֑y⁠ká wá⁠ʼeşĕ̌la֣ẖ lĕ⁠páne֔y⁠ká ʼeţ-mòşě֖h ʼahàrò֥n ẇ⁠mirĕyáֽm׃"],[6,5,"עַמִּ֗⁠י זְכָר־נָא֙ מַה־יָּעַ֗ץ בָּלָק֙ מֶ֣לֶךְ מוֹאָ֔ב וּ⁠מֶה־עָנָ֥ה אֹת֖⁠וֹ בִּלְעָ֣ם בֶּן־בְּע֑וֹר מִן־הַ⁠שִּׁטִּים֙ עַד־הַ⁠גִּלְגָּ֔ל לְמַ֕עַן דַּ֖עַת צִדְק֥וֹת יְהוָֽה׃","ʻami̇֗⁠y zĕkár-náʼ֙ mah-yá̇ʻa֗ẕ bá̇láq֙ me֣lekĕ mwòʼá֔b ẇ⁠meh-ʻáná֥h ʼòţ֖⁠wò bi̇lĕʻá֣m bėn-bĕ̇ʻ֑wòr min-ha⁠şi̇̌ti̇ym֙ ʻad-ha⁠gi̇lĕgá̇֔l lĕma֕ʻan dȧ֖ʻaţ ẕidĕq֥wòţ yĕhwáֽh׃"],[6,6,"בַּ⁠מָּה֙ אֲקַדֵּ֣ם יְהוָ֔ה אִכַּ֖ף לֵ⁠אלֹהֵ֣י מָר֑וֹם הַ⁠אֲקַדְּמֶ֣⁠נּוּ בְ⁠עוֹל֔וֹת בַּ⁠עֲגָלִ֖ים בְּנֵ֥י שָׁנָֽה׃","bȧ⁠má̇h֙ ʼàqadé֣̇m yĕhwá֔h ʼikȧ֖p lé⁠ʼlòhé֣y már֑wòm ha⁠ʼàqadĕ̇me֣⁠ṅẇ bĕ⁠ʻwòl֔wòţ bȧ⁠ʻàgáli֖ym bĕ̇né֥y şá̌náֽh׃"],[6,7,"הֲ⁠יִרְצֶ֤ה יְהוָה֙ בְּ⁠אַלְפֵ֣י אֵילִ֔ים בְּ⁠רִֽבְב֖וֹת נַֽחֲלֵי־שָׁ֑מֶן הַ⁠אֶתֵּ֤ן בְּכוֹרִ⁠י֙ פִּשְׁעִ֔⁠י פְּרִ֥י בִטְנִ֖⁠י חַטַּ֥את נַפְשִֽׁ⁠י׃","hà⁠yirĕẕe֤h yĕhwáh֙ bĕ̇⁠ʼalĕpé֣y ʼéyli֔ym bĕ̇⁠riֽbĕb֖wòţ naֽẖàléy-şá֑̌men ha⁠ʼeţé֤̇n bĕ̇kwòri⁠y֙ pi̇şĕ̌ʻi֔⁠y pĕ̇ri֥y bitĕni֖⁠y ẖatȧ֥ʼţ napĕşǐֽ⁠y׃"],[6,8,"הִגִּ֥יד לְ⁠ךָ֛ אָדָ֖ם מַה־טּ֑וֹב וּ⁠מָֽה־יְהוָ֞ה דּוֹרֵ֣שׁ מִמְּ⁠ךָ֗ כִּ֣י אִם־עֲשׂ֤וֹת מִשְׁפָּט֙ וְ⁠אַ֣הֲבַת חֶ֔סֶד וְ⁠הַצְנֵ֥עַ לֶ֖כֶת עִם־אֱלֹהֶֽי⁠ךָ׃פ","higi֥̇yd lĕ⁠ká֛ ʼádá֖m mah-ṫ֑wòb ẇ⁠máֽh-yĕhwá֞h ḋwòré֣ş̌ mimĕ̇⁠ká֗ ki֣̇y ʼim-ʻàş֤̂wòţ mişĕ̌pá̇t֙ wĕ⁠ʼa֣hàbaţ ẖe֔sed wĕ⁠haẕĕné֥ʻa le֖keţ ʻim-ʼèlòheֽy⁠ká׃p"],[6,9,"ק֤וֹל יְהוָה֙ לָ⁠עִ֣יר יִקְרָ֔א וְ⁠תוּשִׁיָּ֖ה יִרְאֶ֣ה שְׁמֶ֑⁠ךָ שִׁמְע֥וּ מַטֶּ֖ה וּ⁠מִ֥י יְעָדָֽ⁠הּ׃","q֤wòl yĕhwáh֙ lá⁠ʻi֣yr yiqĕrá֔ʼ wĕ⁠ţẇşǐyá֖̇h yirĕʼe֣h şĕ̌me֑⁠ká şǐmĕʻ֥ẇ matė֖h ẇ⁠mi֥y yĕʻádáֽ⁠ḣ׃"],[6,10,"ע֗וֹד הַ⁠אִשׁ֙ בֵּ֣ית רָשָׁ֔ע אֹצְר֖וֹת רֶ֑שַׁע וְ⁠אֵיפַ֥ת רָז֖וֹן זְעוּמָֽה׃","ʻ֗wòd ha⁠ʼiş̌֙ bé֣̇yţ ráşá̌֔ʻ ʼòẕĕr֖wòţ re֑şǎʻ wĕ⁠ʼéypa֥ţ ráz֖wòn zĕʻẇmáֽh׃"],[6,11,"הַ⁠אֶזְכֶּ֖ה בְּ⁠מֹ֣אזְנֵי רֶ֑שַׁע וּ⁠בְ⁠כִ֖יס אַבְנֵ֥י מִרְמָֽה׃","ha⁠ʼezĕkė֖h bĕ̇⁠mò֣ʼzĕnéy re֑şǎʻ ẇ⁠bĕ⁠ki֖ys ʼabĕné֥y mirĕmáֽh׃"],[6,12,"אֲשֶׁ֤ר עֲשִׁירֶ֨י⁠הָ֙ מָלְא֣וּ חָמָ֔ס וְ⁠יֹשְׁבֶ֖י⁠הָ דִּבְּרוּ־שָׁ֑קֶר וּ⁠לְשׁוֹנָ֖⁠ם רְמִיָּ֥ה בְּ⁠פִי⁠הֶֽם׃","ʼàşě֤r ʻàşǐyre֨y⁠há֙ málĕʼ֣ẇ ẖámá֔s wĕ⁠yòşĕ̌be֖y⁠há di̇bĕ̇rẇ-şá֑̌qer ẇ⁠lĕş̌wòná֖⁠m rĕmiyá֥̇h bĕ̇⁠piy⁠heֽm׃"],[6,13,"וְ⁠גַם־אֲנִ֖י הֶחֱלֵ֣יתִי הַכּוֹתֶ֑⁠ךָ הַשְׁמֵ֖ם עַל־חַטֹּאתֶֽ⁠ךָ׃","wĕ⁠gam-ʼàni֖y heẖèlé֣yţiy hak̇wòţe֑⁠ká haşĕ̌mé֖m ʻal-ẖatò̇ʼţeֽ⁠ká׃"],[6,14,"אַתָּ֤ה תֹאכַל֙ וְ⁠לֹ֣א תִשְׂבָּ֔ע וְ⁠יֶשְׁחֲ⁠ךָ֖ בְּ⁠קִרְבֶּ֑⁠ךָ וְ⁠תַסֵּג֙ וְ⁠לֹ֣א תַפְלִ֔יט וַ⁠אֲשֶׁ֥ר תְּפַלֵּ֖ט לַ⁠חֶ֥רֶב אֶתֵּֽן׃","ʼaţá֤̇h ţòʼkal֙ wĕ⁠lò֣ʼ ţişĕ̂bá̇֔ʻ wĕ⁠yeşĕ̌ẖà⁠ká֖ bĕ̇⁠qirĕbė֑⁠ká wĕ⁠ţasé̇g֙ wĕ⁠lò֣ʼ ţapĕli֔yt wa⁠ʼàşě֥r ţĕ̇palé֖̇t la⁠ẖe֥reb ʼeţéֽ̇n׃"],[6,15,"אַתָּ֥ה תִזְרַ֖ע וְ⁠לֹ֣א תִקְצ֑וֹר אַתָּ֤ה תִדְרֹֽךְ־זַ֨יִת֙ וְ⁠לֹא־תָס֣וּךְ שֶׁ֔מֶן וְ⁠תִיר֖וֹשׁ וְ⁠לֹ֥א תִשְׁתֶּה־יָּֽיִן׃","ʼaţá֥̇h ţizĕra֖ʻ wĕ⁠lò֣ʼ ţiqĕẕ֑wòr ʼaţá֤̇h ţidĕròֽkĕ-za֨yiţ֙ wĕ⁠lòʼ-ţás֣ẇkĕ şě֔men wĕ⁠ţiyr֖wòş̌ wĕ⁠lò֥ʼ ţişĕ̌ţėh-yáֽ̇yin׃"],[6,16,"וְ⁠יִשְׁתַּמֵּ֞ר חֻקּ֣וֹת עָמְרִ֗י וְ⁠כֹל֙ מַעֲשֵׂ֣ה בֵית־אַחְאָ֔ב וַ⁠תֵּלְכ֖וּ בְּ⁠מֹֽעֲצוֹתָ֑⁠ם לְמַעַן֩ תִּתִּ֨⁠י אֹתְ⁠ךָ֜ לְ⁠שַׁמָּ֗ה וְ⁠יֹשְׁבֶ֨י⁠הָ֙ לִ⁠שְׁרֵקָ֔ה וְ⁠חֶרְפַּ֥ת עַמִּ֖⁠י תִּשָּֽׂאוּ׃פ","wĕ⁠yişĕ̌ţȧmé̇֞r ẖuq֣̇wòţ ʻámĕri֗y wĕ⁠kòl֙ maʻàşé֣̂h béyţ-ʼaẖĕʼá֔b wa⁠ţé̇lĕk֖ẇ bĕ̇⁠mòֽʻàẕwòţá֑⁠m lĕmaʻan֩ ţi̇ţi̇֨⁠y ʼòţĕ⁠ká֜ lĕ⁠şǎmá̇֗h wĕ⁠yòşĕ̌be֨y⁠há֙ li⁠şĕ̌réqá֔h wĕ⁠ẖerĕpȧ֥ţ ʻami֖̇⁠y ţi̇şáֽ̇̂ʼẇ׃p"],[7,1,"אַ֣לְלַי לִ֗⁠י כִּ֤י הָיִ֨יתִי֙ כְּ⁠אָסְפֵּי־קַ֔יִץ כְּ⁠עֹלְלֹ֖ת בָּצִ֑יר אֵין־אֶשְׁכּ֣וֹל לֶ⁠אֱכ֔וֹל בִּכּוּרָ֖ה אִוְּתָ֥ה נַפְשִֽׁ⁠י׃","ʼa֣lĕlay li֗⁠y ki֤̇y háyi֨yţiy֙ kĕ̇⁠ʼásĕpé̇y-qa֔yiẕ kĕ̇⁠ʻòlĕlò֖ţ bá̇ẕi֑yr ʼéyn-ʼeşĕ̌k֣̇wòl le⁠ʼèk֔wòl bi̇k̇ẇrá֖h ʼiwĕ̇ţá֥h napĕşǐֽ⁠y׃"],[7,2,"אָבַ֤ד חָסִיד֙ מִן־הָ⁠אָ֔רֶץ וְ⁠יָשָׁ֥ר בָּ⁠אָדָ֖ם אָ֑יִן כֻּלָּ⁠ם֙ לְ⁠דָמִ֣ים יֶאֱרֹ֔בוּ אִ֥ישׁ אֶת־אָחִ֖י⁠הוּ יָצ֥וּדוּ חֵֽרֶם׃","ʼába֤d ẖásiyd֙ min-há⁠ʼá֔reẕ wĕ⁠yáşá֥̌r bá̇⁠ʼádá֖m ʼá֑yin ku̇lá̇⁠m֙ lĕ⁠dámi֣ym yeʼèrò֔bẇ ʼi֥yş̌ ʼeţ-ʼáẖi֖y⁠hẇ yáẕ֥ẇdẇ ẖéֽrem׃"],[7,3,"עַל־הָ⁠רַ֤ע כַּפַּ֨יִם֙ לְ⁠הֵיטִ֔יב הַ⁠שַּׂ֣ר שֹׁאֵ֔ל וְ⁠הַ⁠שֹּׁפֵ֖ט בַּ⁠שִׁלּ֑וּם וְ⁠הַ⁠גָּד֗וֹל דֹּבֵ֨ר הַוַּ֥ת נַפְשׁ֛⁠וֹ ה֖וּא וַֽ⁠יְעַבְּתֽוּ⁠הָ׃","ʻal-há⁠ra֤ʻ kȧpȧ֨yim֙ lĕ⁠héyti֔yb ha⁠şȧ֣̂r şò̌ʼé֔l wĕ⁠ha⁠şò̇̌pé֖t bȧ⁠şǐl֑̇ẇm wĕ⁠ha⁠gá̇d֗wòl dò̇bé֨r hawȧ֥ţ napĕş֛̌⁠wò h֖ẇʼ waֽ⁠yĕʻabĕ̇ţֽẇ⁠há׃"],[7,4,"טוֹבָ֣⁠ם כְּ⁠חֵ֔דֶק יָשָׁ֖ר מִ⁠מְּסוּכָ֑ה י֤וֹם מְצַפֶּ֨י⁠ךָ֙ פְּקֻדָּתְ⁠ךָ֣ בָ֔אָה עַתָּ֥ה תִהְיֶ֖ה מְבוּכָתָֽ⁠ם׃","twòbá֣⁠m kĕ̇⁠ẖé֔deq yáşá֖̌r mi⁠mĕ̇sẇká֑h y֤wòm mĕẕapė֨y⁠ká֙ pĕ̇qudá̇ţĕ⁠ká֣ bá֔ʼáh ʻaţá֥̇h ţihĕye֖h mĕbẇkáţáֽ⁠m׃"],[7,5,"אַל־תַּאֲמִ֣ינוּ בְ⁠רֵ֔עַ אַֽל־תִּבְטְח֖וּ בְּ⁠אַלּ֑וּף מִ⁠שֹּׁכֶ֣בֶת חֵיקֶ֔⁠ךָ שְׁמֹ֖ר פִּתְחֵי־פִֽי⁠ךָ׃","ʼal-ţȧʼàmi֣ynẇ bĕ⁠ré֔ʻa ʼaֽl-ţi̇bĕtĕẖ֖ẇ bĕ̇⁠ʼal֑̇ẇp mi⁠şò̇̌ke֣beţ ẖéyqe֔⁠ká şĕ̌mò֖r pi̇ţĕẖéy-piֽy⁠ká׃"],[7,6,"כִּֽי־בֵן֙ מְנַבֵּ֣ל אָ֔ב בַּ֚ת קָמָ֣ה בְ⁠אִמָּ֔⁠הּ כַּלָּ֖ה בַּ⁠חֲמֹתָ֑⁠הּ אֹיְבֵ֥י אִ֖ישׁ אַנְשֵׁ֥י בֵיתֽ⁠וֹ׃","kiֽ̇y-bén֙ mĕnabé֣̇l ʼá֔b bȧ֚ţ qámá֣h bĕ⁠ʼimá̇֔⁠ḣ kȧlá֖̇h bȧ⁠ẖàmòţá֑⁠ḣ ʼòyĕbé֥y ʼi֖yş̌ ʼanĕşé֥̌y béyţֽ⁠wò׃"],[7,7,"וַ⁠אֲנִי֙ בַּ⁠יהוָ֣ה אֲצַפֶּ֔ה אוֹחִ֖ילָה לֵ⁠אלֹהֵ֣י יִשְׁעִ֑⁠י יִשְׁמָעֵ֖⁠נִי אֱלֹהָֽ⁠י׃","wa⁠ʼàniy֙ bȧ⁠yhwá֣h ʼàẕapė֔h ʼwòẖi֖yláh lé⁠ʼlòhé֣y yişĕ̌ʻi֑⁠y yişĕ̌máʻé֖⁠niy ʼèlòháֽ⁠y׃"],[7,8,"אַֽל־תִּשְׂמְחִ֤י אֹיַ֨בְתִּ⁠י֙ לִ֔⁠י כִּ֥י נָפַ֖לְתִּי קָ֑מְתִּי כִּֽי־אֵשֵׁ֣ב בַּ⁠חֹ֔שֶׁךְ יְהוָ֖ה א֥וֹר לִֽ⁠י׃ס","ʼaֽl-ţi̇şĕ̂mĕẖi֤y ʼòya֨bĕţi̇⁠y֙ li֔⁠y ki֥̇y nápa֖lĕţi̇y qá֑mĕţi̇y kiֽ̇y-ʼéşé֣̌b bȧ⁠ẖò֔şěkĕ yĕhwá֖h ʼ֥wòr liֽ⁠y׃s"],[7,9,"זַ֤עַף יְהוָה֙ אֶשָּׂ֔א כִּ֥י חָטָ֖אתִי ל֑⁠וֹ עַד֩ אֲשֶׁ֨ר יָרִ֤יב רִיבִ⁠י֙ וְ⁠עָשָׂ֣ה מִשְׁפָּטִ֔⁠י יוֹצִיאֵ֣⁠נִי לָ⁠א֔וֹר אֶרְאֶ֖ה בְּ⁠צִדְקָתֽ⁠וֹ׃","za֤ʻap yĕhwáh֙ ʼeşá̇̂֔ʼ ki֥̇y ẖátá֖ʼţiy l֑⁠wò ʻad֩ ʼàşě֨r yári֤yb riybi⁠y֙ wĕ⁠ʻáşá֣̂h mişĕ̌pá̇ti֔⁠y ywòẕiyʼé֣⁠niy lá⁠ʼ֔wòr ʼerĕʼe֖h bĕ̇⁠ẕidĕqáţֽ⁠wò׃"],[7,10,"וְ⁠תֵרֶ֤א אֹיַ֨בְתִּ⁠י֙ וּ⁠תְכַסֶּ֣⁠הָ בוּשָׁ֔ה הָ⁠אֹמְרָ֣ה אֵלַ֔⁠י אַיּ֖⁠וֹ יְהוָ֣ה אֱלֹהָ֑יִ⁠ךְ עֵינַ⁠י֙ תִּרְאֶ֣ינָּה בָּ֔⁠הּ עַתָּ֛ה תִּֽהְיֶ֥ה לְ⁠מִרְמָ֖ס כְּ⁠טִ֥יט חוּצֽוֹת׃","wĕ⁠ţére֤ʼ ʼòya֨bĕţi̇⁠y֙ ẇ⁠ţĕkasė֣⁠há bẇşá̌֔h há⁠ʼòmĕrá֣h ʼéla֔⁠y ʼaẏ֖⁠wò yĕhwá֣h ʼèlòhá֑yi⁠kĕ ʻéyna⁠y֙ ţi̇rĕʼe֣yná̇h bá̇֔⁠ḣ ʻaţá֛̇h ţiֽ̇hĕye֥h lĕ⁠mirĕmá֖s kĕ̇⁠ti֥yt ẖẇẕֽwòţ׃"],[7,11,"י֖וֹם לִ⁠בְנ֣וֹת גְּדֵרָ֑יִ⁠ךְ י֥וֹם הַ⁠ה֖וּא יִרְחַק־חֹֽק׃","y֖wòm li⁠bĕn֣wòţ gĕ̇dérá֑yi⁠kĕ y֥wòm ha⁠h֖ẇʼ yirĕẖaq-ẖòֽq׃"],[7,12,"י֥וֹם הוּא֙ וְ⁠עָדֶ֣י⁠ךָ יָב֔וֹא לְ⁠מִנִּ֥י אַשּׁ֖וּר וְ⁠עָרֵ֣י מָצ֑וֹר וּ⁠לְ⁠מִנִּ֤י מָצוֹר֙ וְ⁠עַד־נָהָ֔ר וְ⁠יָ֥ם מִ⁠יָּ֖ם וְ⁠הַ֥ר הָ⁠הָֽר׃","y֥wòm hẇʼ֙ wĕ⁠ʻáde֣y⁠ká yáb֔wòʼ lĕ⁠mini֥̇y ʼaş֖̇̌ẇr wĕ⁠ʻáré֣y máẕ֑wòr ẇ⁠lĕ⁠mini֤̇y máẕwòr֙ wĕ⁠ʻad-náhá֔r wĕ⁠yá֥m mi⁠yá֖̇m wĕ⁠ha֥r há⁠háֽr׃"],[7,13,"וְ⁠הָיְתָ֥ה הָ⁠אָ֛רֶץ לִ⁠שְׁמָמָ֖ה עַל־יֹֽשְׁבֶ֑י⁠הָ מִ⁠פְּרִ֖י מַֽעַלְלֵי⁠הֶֽם׃ס","wĕ⁠háyĕţá֥h há⁠ʼá֛reẕ li⁠şĕ̌mámá֖h ʻal-yòֽşĕ̌be֑y⁠há mi⁠pĕ̇ri֖y maֽʻalĕléy⁠heֽm׃s"],[7,14,"רְעֵ֧ה עַמְּ⁠ךָ֣ בְ⁠שִׁבְטֶ֗⁠ךָ צֹ֚אן נַֽחֲלָתֶ֔⁠ךָ שֹׁכְנִ֣י לְ⁠בָדָ֔ד יַ֖עַר בְּ⁠ת֣וֹךְ כַּרְמֶ֑ל יִרְע֥וּ בָשָׁ֛ן וְ⁠גִלְעָ֖ד כִּ⁠ימֵ֥י עוֹלָֽם׃","rĕʻé֧h ʻamĕ̇⁠ká֣ bĕ⁠şǐbĕte֗⁠ká ẕò֚ʼn naֽẖàláţe֔⁠ká şò̌kĕni֣y lĕ⁠bádá֔d ya֖ʻar bĕ̇⁠ţ֣wòkĕ kȧrĕme֑l yirĕʻ֥ẇ báşá֛̌n wĕ⁠gilĕʻá֖d ki̇⁠ymé֥y ʻwòláֽm׃"],[7,15,"כִּ⁠ימֵ֥י צֵאתְ⁠ךָ֖ מֵ⁠אֶ֣רֶץ מִצְרָ֑יִם אַרְאֶ֖⁠נּוּ נִפְלָאֽוֹת׃","ki̇⁠ymé֥y ẕéʼţĕ⁠ká֖ mé⁠ʼe֣reẕ miẕĕrá֑yim ʼarĕʼe֖⁠ṅẇ nipĕláʼֽwòţ׃"],[7,16,"יִרְא֤וּ גוֹיִם֙ וְ⁠יֵבֹ֔שׁוּ מִ⁠כֹּ֖ל גְּבֽוּרָתָ֑⁠ם יָשִׂ֤ימוּ יָד֙ עַל־פֶּ֔ה אָזְנֵי⁠הֶ֖ם תֶּחֱרַֽשְׁנָה׃","yirĕʼ֤ẇ gwòyim֙ wĕ⁠yébò֔ş̌ẇ mi⁠kò֖̇l gĕ̇bֽẇráţá֑⁠m yáşî֤ymẇ yád֙ ʻal-pė֔h ʼázĕnéy⁠he֖m ţėẖèraֽşĕ̌náh׃"],[7,17,"יְלַחֲכ֤וּ עָפָר֙ כַּ⁠נָּחָ֔שׁ כְּ⁠זֹחֲלֵ֣י אֶ֔רֶץ יִרְגְּז֖וּ מִ⁠מִּסְגְּרֹֽתֵי⁠הֶ֑ם אֶל־יְהוָ֤ה אֱלֹהֵ֨י⁠נוּ֙ יִפְחָ֔דוּ וְ⁠יִֽרְא֖וּ מִמֶּֽ⁠ךָּ׃","yĕlaẖàk֤ẇ ʻápár֙ kȧ⁠ná̇ẖá֔ş̌ kĕ̇⁠zòẖàlé֣y ʼe֔reẕ yirĕgĕ̇z֖ẇ mi⁠mi̇sĕgĕ̇ròֽţéy⁠he֑m ʼel-yĕhwá֤h ʼèlòhé֨y⁠nẇ֙ yipĕẖá֔dẇ wĕ⁠yiֽrĕʼ֖ẇ mimėֽ⁠ká̇׃"],[7,18,"מִי־אֵ֣ל כָּמ֗וֹ⁠ךָ נֹשֵׂ֤א עָוֺן֙ וְ⁠עֹבֵ֣ר עַל־פֶּ֔שַׁע לִ⁠שְׁאֵרִ֖ית נַחֲלָת֑⁠וֹ לֹא־הֶחֱזִ֤יק לָ⁠עַד֙ אַפּ֔⁠וֹ כִּֽי־חָפֵ֥ץ חֶ֖סֶד הֽוּא׃","miy-ʼé֣l ká̇m֗wò⁠ká nòşé֤̂ʼ ʻáwֺn֙ wĕ⁠ʻòbé֣r ʻal-pė֔şǎʻ li⁠şĕ̌ʼéri֖yţ naẖàláţ֑⁠wò lòʼ-heẖèzi֤yq lá⁠ʻad֙ ʼaṗ֔⁠wò kiֽ̇y-ẖápé֥ẕ ẖe֖sed hֽẇʼ׃"],[7,19,"יָשׁ֣וּב יְרַֽחֲמֵ֔⁠נוּ יִכְבֹּ֖שׁ עֲוֺֽנֹתֵ֑י⁠נוּ וְ⁠תַשְׁלִ֛יךְ בִּ⁠מְצֻל֥וֹת יָ֖ם כָּל־חַטֹּאותָֽ⁠ם׃","yáş֣̌ẇb yĕraֽẖàmé֔⁠nẇ yikĕbò֖̇ş̌ ʻàwֺֽnòţé֑y⁠nẇ wĕ⁠ţaşĕ̌li֛ykĕ bi̇⁠mĕẕul֥wòţ yá֖m ká̇l-ẖatò̇ʼwţáֽ⁠m׃"],[7,20,"תִּתֵּ֤ן אֱמֶת֙ לְ⁠יַֽעֲקֹ֔ב חֶ֖סֶד לְ⁠אַבְרָהָ֑ם אֲשֶׁר־נִשְׁבַּ֥עְתָּ לַ⁠אֲבֹתֵ֖י⁠נוּ מִ֥⁠ימֵי קֶֽדֶם׃","ţi̇ţé֤̇n ʼèmeţ֙ lĕ⁠yaֽʻàqò֔b ẖe֖sed lĕ⁠ʼabĕráhá֑m ʼàşěr-nişĕ̌bȧ֥ʻĕţá̇ la⁠ʼàbòţé֖y⁠nẇ mi֥⁠yméy qeֽdem׃"]],"fra-lsg1910":[[1,1,"La parole de l'Éternel fut adressée à Michée, de Moréscheth, au temps de Jotham, d'Achaz, d'Ézéchias, rois de Juda, prophétie sur Samarie et Jérusalem.","La parole de l'Éternel fut adressée à Michée, de Moréscheth, au temps de Jotham, d'Achaz, d'Ézéchias, rois de Juda, prophétie sur Samarie et Jérusalem."],[1,2,"Écoutez, vous tous, peuples! Sois attentive, terre, et ce qui est en toi! Que le Seigneur, l'Éternel, soit témoin contre vous, Le Seigneur qui est dans le palais de sa sainteté!","Écoutez, vous tous, peuples! Sois attentive, terre, et ce qui est en toi! Que le Seigneur, l'Éternel, soit témoin contre vous, Le Seigneur qui est dans le palais de sa sainteté!"],[1,3,"Car voici, l'Éternel sort de sa demeure, Il descend, il marche sur les hauteurs de la terre.","Car voici, l'Éternel sort de sa demeure, Il descend, il marche sur les hauteurs de la terre."],[1,4,"Sous lui les montagnes se fondent, Les vallées s'entr'ouvrent, Comme la cire devant le feu, Comme l'eau qui coule sur une pente.","Sous lui les montagnes se fondent, Les vallées s'entr'ouvrent, Comme la cire devant le feu, Comme l'eau qui coule sur une pente."],[1,5,"Et tout cela à cause du crime de Jacob, À cause des péchés de la maison d'Israël! Quel est le crime de Jacob? n'est-ce pas Samarie? Quels sont les hauts lieux de Juda? n'est-ce pas Jérusalem?...","Et tout cela à cause du crime de Jacob, À cause des péchés de la maison d'Israël! Quel est le crime de Jacob? n'est-ce pas Samarie? Quels sont les hauts lieux de Juda? n'est-ce pas Jérusalem?..."],[1,6,"Je ferai de Samarie un monceau de pierres dans les champs, Un lieu pour planter de la vigne; Je précipiterai ses pierres dans la vallée, Je mettrai à nu ses fondements.","Je ferai de Samarie un monceau de pierres dans les champs, Un lieu pour planter de la vigne; Je précipiterai ses pierres dans la vallée, Je mettrai à nu ses fondements."],[1,7,"Toutes ses images taillées seront brisées, Tous ses salaires impurs seront brûlés au feu, Et je ravagerai toutes ses idoles: Recueillies avec le salaire de la prostitution, Elles deviendront un salaire de prostitutions...","Toutes ses images taillées seront brisées, Tous ses salaires impurs seront brûlés au feu, Et je ravagerai toutes ses idoles: Recueillies avec le salaire de la prostitution, Elles deviendront un salaire de prostitutions..."],[1,8,"C'est pourquoi je pleurerai, je me lamenterai, Je marcherai déchaussé et nu, Je pousserai des cris comme le chacal, Et des gémissements comme l'autruche.","C'est pourquoi je pleurerai, je me lamenterai, Je marcherai déchaussé et nu, Je pousserai des cris comme le chacal, Et des gémissements comme l'autruche."],[1,9,"Car sa plaie est douloureuse; Elle s'étend jusqu'à Juda, Elle pénètre jusqu'à la porte de mon peuple, Jusqu'à Jérusalem.","Car sa plaie est douloureuse; Elle s'étend jusqu'à Juda, Elle pénètre jusqu'à la porte de mon peuple, Jusqu'à Jérusalem."],[1,10,"Ne l'annoncez point dans Gath, Ne pleurez point dans Acco! Je me roule dans la poussière à Beth Leaphra.","Ne l'annoncez point dans Gath, Ne pleurez point dans Acco! Je me roule dans la poussière à Beth Leaphra."],[1,11,"Passe, habitante de Schaphir, dans la nudité et la honte! L'habitante de Tsaanan n'ose sortir, Le deuil de Beth-Haëtsel vous prive de son abri.","Passe, habitante de Schaphir, dans la nudité et la honte! L'habitante de Tsaanan n'ose sortir, Le deuil de Beth-Haëtsel vous prive de son abri."],[1,12,"L'habitante de Maroth tremble pour son salut, Car le malheur est descendu de la part de l'Éternel Jusqu'à la porte de Jérusalem.","L'habitante de Maroth tremble pour son salut, Car le malheur est descendu de la part de l'Éternel Jusqu'à la porte de Jérusalem."],[1,13,"Attelle les coursiers à ton char, Habitante de Lakisch! Tu as été pour la fille de Sion une première cause de péché, Car en toi se sont trouvés les crimes d'Israël.","Attelle les coursiers à ton char, Habitante de Lakisch! Tu as été pour la fille de Sion une première cause de péché, Car en toi se sont trouvés les crimes d'Israël."],[1,14,"C'est pourquoi tu renonceras à Moréschet-Gath; Les maisons d'Aczib seront une source trompeuse Pour les rois d'Israël.","C'est pourquoi tu renonceras à Moréschet-Gath; Les maisons d'Aczib seront une source trompeuse Pour les rois d'Israël."],[1,15,"Je t'amènerai un nouveau maître, habitante de Maréscha; La gloire d'Israël s'en ira jusqu'à Adullam.","Je t'amènerai un nouveau maître, habitante de Maréscha; La gloire d'Israël s'en ira jusqu'à Adullam."],[1,16,"Rase-toi, coupe ta chevelure, À cause de tes enfants chéris! Rends-toi chauve comme l'aigle, Car ils s'en vont en captivité loin de toi!","Rase-toi, coupe ta chevelure, À cause de tes enfants chéris! Rends-toi chauve comme l'aigle, Car ils s'en vont en captivité loin de toi!"],[2,1,"Malheur à ceux qui méditent l'iniquité et qui forgent le mal Sur leur couche! Au point du jour ils l'exécutent, Quand ils ont le pouvoir en main.","Malheur à ceux qui méditent l'iniquité et qui forgent le mal Sur leur couche! Au point du jour ils l'exécutent, Quand ils ont le pouvoir en main."],[2,2,"Ils convoitent des champs, et ils s'en emparent, Des maisons, et ils les enlèvent; Ils portent leur violence sur l'homme et sur sa maison, Sur l'homme et sur son héritage.","Ils convoitent des champs, et ils s'en emparent, Des maisons, et ils les enlèvent; Ils portent leur violence sur l'homme et sur sa maison, Sur l'homme et sur son héritage."],[2,3,"C'est pourquoi ainsi parle l'Éternel: Voici, je médite contre cette race un malheur; Vous n'en préserverez pas vos cous, Et vous ne marcherez pas la tête levée, Car ces temps seront mauvais.","C'est pourquoi ainsi parle l'Éternel: Voici, je médite contre cette race un malheur; Vous n'en préserverez pas vos cous, Et vous ne marcherez pas la tête levée, Car ces temps seront mauvais."],[2,4,"En ce jour-là, on fera de vous un sujet de sarcasme, On poussera des cris lamentables, On dira: Nous sommes entièrement dévastés! Il donne à d'autres la part de mon peuple! Eh quoi! il me l'enlève! Il distribue nos champs à l'ennemi!...","En ce jour-là, on fera de vous un sujet de sarcasme, On poussera des cris lamentables, On dira: Nous sommes entièrement dévastés! Il donne à d'autres la part de mon peuple! Eh quoi! il me l'enlève! Il distribue nos champs à l'ennemi!..."],[2,5,"C'est pourquoi tu n'auras personne Qui étende le cordeau sur un lot, Dans l'assemblée de l'Éternel. -","C'est pourquoi tu n'auras personne Qui étende le cordeau sur un lot, Dans l'assemblée de l'Éternel. -"],[2,6,"Ne prophétisez pas! disent-ils. Qu'on ne prophétise pas de telles choses! Les invectives n'ont point de fin! -","Ne prophétisez pas! disent-ils. Qu'on ne prophétise pas de telles choses! Les invectives n'ont point de fin! -"],[2,7,"Oses-tu parler ainsi, maison de Jacob? L'Éternel est-il prompt à s'irriter? Est-ce là sa manière d'agir? Mes paroles ne sont-elles pas favorables À celui qui marche avec droiture?","Oses-tu parler ainsi, maison de Jacob? L'Éternel est-il prompt à s'irriter? Est-ce là sa manière d'agir? Mes paroles ne sont-elles pas favorables À celui qui marche avec droiture?"],[2,8,"Depuis longtemps on traite mon peuple en ennemi; Vous enlevez le manteau de dessus les vêtements De ceux qui passent avec sécurité En revenant de la guerre.","Depuis longtemps on traite mon peuple en ennemi; Vous enlevez le manteau de dessus les vêtements De ceux qui passent avec sécurité En revenant de la guerre."],[2,9,"Vous chassez de leurs maisons chéries les femmes de mon peuple, Vous ôtez pour toujours ma parure à leurs enfants.","Vous chassez de leurs maisons chéries les femmes de mon peuple, Vous ôtez pour toujours ma parure à leurs enfants."],[2,10,"Levez-vous, marchez! car ce n'est point ici un lieu de repos; À cause de la souillure, il y aura des douleurs, des douleurs violentes.","Levez-vous, marchez! car ce n'est point ici un lieu de repos; À cause de la souillure, il y aura des douleurs, des douleurs violentes."],[2,11,"Si un homme court après le vent et débite des mensonges: Je vais te prophétiser sur le vin, sur les boissons fortes! Ce sera pour ce peuple un prophète.","Si un homme court après le vent et débite des mensonges: Je vais te prophétiser sur le vin, sur les boissons fortes! Ce sera pour ce peuple un prophète."],[2,12,"Je te rassemblerai tout entier, ô Jacob! Je rassemblerai les restes d'Israël, Je les réunirai comme les brebis d'une bergerie, Comme le troupeau dans son pâturage; Il y aura un grand bruit d'hommes.","Je te rassemblerai tout entier, ô Jacob! Je rassemblerai les restes d'Israël, Je les réunirai comme les brebis d'une bergerie, Comme le troupeau dans son pâturage; Il y aura un grand bruit d'hommes."],[2,13,"Celui qui fera la brèche montera devant eux; Ils feront la brèche, franchiront la porte et en sortiront; Leur roi marchera devant eux, Et l'Éternel sera à leur tête.","Celui qui fera la brèche montera devant eux; Ils feront la brèche, franchiront la porte et en sortiront; Leur roi marchera devant eux, Et l'Éternel sera à leur tête."],[3,1,"Je dis: Écoutez, chefs de Jacob, Et princes de la maison d'Israël! N'est-ce pas à vous à connaître la justice?","Je dis: Écoutez, chefs de Jacob, Et princes de la maison d'Israël! N'est-ce pas à vous à connaître la justice?"],[3,2,"Vous haïssez le bien et vous aimez le mal; Vous leur arrachez la peau et la chair de dessus les os.","Vous haïssez le bien et vous aimez le mal; Vous leur arrachez la peau et la chair de dessus les os."],[3,3,"Ils dévorent la chair de mon peuple, Lui arrachent la peau, Et lui brisent les os; Ils le mettent en pièces comme ce qu'on cuit dans un pot, Comme de la viande dans une chaudière.","Ils dévorent la chair de mon peuple, Lui arrachent la peau, Et lui brisent les os; Ils le mettent en pièces comme ce qu'on cuit dans un pot, Comme de la viande dans une chaudière."],[3,4,"Alors ils crieront vers l'Éternel, Mais il ne leur répondra pas; Il leur cachera sa face en ce temps-là, Parce qu'ils ont fait de mauvaises actions.","Alors ils crieront vers l'Éternel, Mais il ne leur répondra pas; Il leur cachera sa face en ce temps-là, Parce qu'ils ont fait de mauvaises actions."],[3,5,"Ainsi parle l'Éternel sur les prophètes qui égarent mon peuple, Qui annoncent la paix si leurs dents ont quelque chose à mordre, Et qui publient la guerre si on ne leur met rien dans la bouche:","Ainsi parle l'Éternel sur les prophètes qui égarent mon peuple, Qui annoncent la paix si leurs dents ont quelque chose à mordre, Et qui publient la guerre si on ne leur met rien dans la bouche:"],[3,6,"À cause de cela, vous aurez la nuit..., et plus de visions! Vous aurez les ténèbres..., et plus d'oracles! Le soleil se couchera sur ces prophètes, Le jour s'obscurcira sur eux.","À cause de cela, vous aurez la nuit..., et plus de visions! Vous aurez les ténèbres..., et plus d'oracles! Le soleil se couchera sur ces prophètes, Le jour s'obscurcira sur eux."],[3,7,"Les voyants seront confus, les devins rougiront, Tous se couvriront la barbe; Car Dieu ne répondra pas.","Les voyants seront confus, les devins rougiront, Tous se couvriront la barbe; Car Dieu ne répondra pas."],[3,8,"Mais moi, je suis rempli de force, de l'esprit de l'Éternel, Je suis rempli de justice et de vigueur, Pour faire connaître à Jacob son crime, Et à Israël son péché.","Mais moi, je suis rempli de force, de l'esprit de l'Éternel, Je suis rempli de justice et de vigueur, Pour faire connaître à Jacob son crime, Et à Israël son péché."],[3,9,"Écoutez donc ceci, chefs de la maison de Jacob, Et princes de la maison d'Israël, Vous qui avez en horreur la justice, Et qui pervertissez tout ce qui est droit,","Écoutez donc ceci, chefs de la maison de Jacob, Et princes de la maison d'Israël, Vous qui avez en horreur la justice, Et qui pervertissez tout ce qui est droit,"],[3,10,"Vous qui bâtissez Sion avec le sang, Et Jérusalem avec l'iniquité!","Vous qui bâtissez Sion avec le sang, Et Jérusalem avec l'iniquité!"],[3,11,"Ses chefs jugent pour des présents, Ses sacrificateurs enseignent pour un salaire, Et ses prophètes prédisent pour de l'argent; Et ils osent s'appuyer sur l'Éternel, ils disent: L'Éternel n'est-il pas au milieu de nous? Le malheur ne nous atteindra pas.","Ses chefs jugent pour des présents, Ses sacrificateurs enseignent pour un salaire, Et ses prophètes prédisent pour de l'argent; Et ils osent s'appuyer sur l'Éternel, ils disent: L'Éternel n'est-il pas au milieu de nous? Le malheur ne nous atteindra pas."],[3,12,"C'est pourquoi, à cause de vous, Sion sera labourée comme un champ, Jérusalem deviendra un monceau de pierres, Et la montagne du temple une sommité couverte de bois.","C'est pourquoi, à cause de vous, Sion sera labourée comme un champ, Jérusalem deviendra un monceau de pierres, Et la montagne du temple une sommité couverte de bois."],[4,1,"Il arrivera, dans la suite des temps, Que la montagne de la maison de l'Éternel Sera fondée sur le sommet des montagnes, Qu'elle s'élèvera par-dessus les collines, Et que les peuples y afflueront.","Il arrivera, dans la suite des temps, Que la montagne de la maison de l'Éternel Sera fondée sur le sommet des montagnes, Qu'elle s'élèvera par-dessus les collines, Et que les peuples y afflueront."],[4,2,"Des nations s'y rendront en foule, et diront: Venez, et montons à la montagne de l'Éternel, À la maison du Dieu de Jacob, Afin qu'il nous enseigne ses voies, Et que nous marchions dans ses sentiers. Car de Sion sortira la loi, Et de Jérusalem la parole de l'Éternel.","Des nations s'y rendront en foule, et diront: Venez, et montons à la montagne de l'Éternel, À la maison du Dieu de Jacob, Afin qu'il nous enseigne ses voies, Et que nous marchions dans ses sentiers. Car de Sion sortira la loi, Et de Jérusalem la parole de l'Éternel."],[4,3,"Il sera le juge d'un grand nombre de peuples, L'arbitre de nations puissantes, lointaines. De leurs glaives ils forgeront des hoyaux, Et de leurs lances des serpes; Une nation ne tirera plus l'épée contre une autre, Et l'on n'apprendra plus la guerre.","Il sera le juge d'un grand nombre de peuples, L'arbitre de nations puissantes, lointaines. De leurs glaives ils forgeront des hoyaux, Et de leurs lances des serpes; Une nation ne tirera plus l'épée contre une autre, Et l'on n'apprendra plus la guerre."],[4,4,"Ils habiteront chacun sous sa vigne et sous son figuier, Et il n'y aura personne pour les troubler; Car la bouche de l'Éternel des armées a parlé.","Ils habiteront chacun sous sa vigne et sous son figuier, Et il n'y aura personne pour les troubler; Car la bouche de l'Éternel des armées a parlé."],[4,5,"Tandis que tous les peuples marchent, chacun au nom de son dieu, Nous marcherons, nous, au nom de l'Éternel, notre Dieu, À toujours et à perpétuité.","Tandis que tous les peuples marchent, chacun au nom de son dieu, Nous marcherons, nous, au nom de l'Éternel, notre Dieu, À toujours et à perpétuité."],[4,6,"En ce jour-là, dit l'Éternel, je recueillerai les boiteux, Je rassemblerai ceux qui étaient chassés, Ceux que j'avais maltraités.","En ce jour-là, dit l'Éternel, je recueillerai les boiteux, Je rassemblerai ceux qui étaient chassés, Ceux que j'avais maltraités."],[4,7,"Des boiteux je ferai un reste, De ceux qui étaient chassés une nation puissante; Et l'Éternel régnera sur eux, à la montagne de Sion, Dès lors et pour toujours.","Des boiteux je ferai un reste, De ceux qui étaient chassés une nation puissante; Et l'Éternel régnera sur eux, à la montagne de Sion, Dès lors et pour toujours."],[4,8,"Et toi, tour du troupeau, colline de la fille de Sion, À toi viendra, à toi arrivera l'ancienne domination, Le royaume de la fille de Jérusalem.","Et toi, tour du troupeau, colline de la fille de Sion, À toi viendra, à toi arrivera l'ancienne domination, Le royaume de la fille de Jérusalem."],[4,9,"Pourquoi maintenant pousses-tu des cris? N'as-tu point de roi, plus de conseiller, Pour que la douleur te saisisse comme une femme qui accouche?","Pourquoi maintenant pousses-tu des cris? N'as-tu point de roi, plus de conseiller, Pour que la douleur te saisisse comme une femme qui accouche?"],[4,10,"Fille de Sion, souffre et gémis comme une femme qui accouche! Car maintenant tu sortiras de la ville et tu habiteras dans les champs, Et tu iras jusqu'à Babylone; Là tu seras délivrée, C'est là que l'Éternel te rachètera de la main de tes ennemis.","Fille de Sion, souffre et gémis comme une femme qui accouche! Car maintenant tu sortiras de la ville et tu habiteras dans les champs, Et tu iras jusqu'à Babylone; Là tu seras délivrée, C'est là que l'Éternel te rachètera de la main de tes ennemis."],[4,11,"Maintenant plusieurs nations se sont rassemblées contre toi: Qu'elle soit profanée, disent-elles, Et que nos yeux se rassasient dans Sion!","Maintenant plusieurs nations se sont rassemblées contre toi: Qu'elle soit profanée, disent-elles, Et que nos yeux se rassasient dans Sion!"],[4,12,"Mais elles ne connaissent pas les pensées de l'Éternel, Elles ne comprennent pas ses desseins, Elles ignorent qu'il les a rassemblées comme des gerbes dans l'aire.","Mais elles ne connaissent pas les pensées de l'Éternel, Elles ne comprennent pas ses desseins, Elles ignorent qu'il les a rassemblées comme des gerbes dans l'aire."],[4,13,"Fille de Sion, lève-toi et foule! Je te ferai une corne de fer et des ongles d'airain, Et tu broieras des peuples nombreux; Tu consacreras leurs biens à l'Éternel, Leurs richesses au Seigneur de toute la terre.","Fille de Sion, lève-toi et foule! Je te ferai une corne de fer et des ongles d'airain, Et tu broieras des peuples nombreux; Tu consacreras leurs biens à l'Éternel, Leurs richesses au Seigneur de toute la terre."],[5,1,"Maintenant, fille de troupes, rassemble tes troupes! On nous assiège; Avec la verge on frappe sur la joue le juge d'Israël.","Maintenant, fille de troupes, rassemble tes troupes! On nous assiège; Avec la verge on frappe sur la joue le juge d'Israël."],[5,2,"Et toi, Bethléhem Éphrata, Petite entre les milliers de Juda, De toi sortira pour moi Celui qui dominera sur Israël, Et dont l'origine remonte aux temps anciens, Aux jours de l'éternité.","Et toi, Bethléhem Éphrata, Petite entre les milliers de Juda, De toi sortira pour moi Celui qui dominera sur Israël, Et dont l'origine remonte aux temps anciens, Aux jours de l'éternité."],[5,3,"C'est pourquoi il les livrera Jusqu'au temps où enfantera celle qui doit enfanter, Et le reste de ses frères Reviendra auprès des enfants d'Israël.","C'est pourquoi il les livrera Jusqu'au temps où enfantera celle qui doit enfanter, Et le reste de ses frères Reviendra auprès des enfants d'Israël."],[5,4,"Il se présentera, et il gouvernera avec la force de l'Éternel, Avec la majesté du nom de l'Éternel, son Dieu: Et ils auront une demeure assurée, Car il sera glorifié jusqu'aux extrémités de la terre.","Il se présentera, et il gouvernera avec la force de l'Éternel, Avec la majesté du nom de l'Éternel, son Dieu: Et ils auront une demeure assurée, Car il sera glorifié jusqu'aux extrémités de la terre."],[5,5,"C'est lui qui ramènera la paix. Lorsque l'Assyrien viendra dans notre pays, Et qu'il pénétrera dans nos palais, Nous ferons lever contre lui sept pasteurs Et huit princes du peuple.","C'est lui qui ramènera la paix. Lorsque l'Assyrien viendra dans notre pays, Et qu'il pénétrera dans nos palais, Nous ferons lever contre lui sept pasteurs Et huit princes du peuple."],[5,6,"Ils feront avec l'épée leur pâture du pays d'Assyrie Et du pays de Nimrod au dedans de ses portes. Il nous délivrera ainsi de l'Assyrien, Lorsqu'il viendra dans notre pays, Et qu'il pénétrera sur notre territoire.","Ils feront avec l'épée leur pâture du pays d'Assyrie Et du pays de Nimrod au dedans de ses portes. Il nous délivrera ainsi de l'Assyrien, Lorsqu'il viendra dans notre pays, Et qu'il pénétrera sur notre territoire."],[5,7,"Le reste de Jacob sera au milieu des peuples nombreux Comme une rosée qui vient de l'Éternel, Comme des gouttes d'eau sur l'herbe: Elles ne comptent pas sur l'homme, Elles ne dépendent pas des enfants des hommes.","Le reste de Jacob sera au milieu des peuples nombreux Comme une rosée qui vient de l'Éternel, Comme des gouttes d'eau sur l'herbe: Elles ne comptent pas sur l'homme, Elles ne dépendent pas des enfants des hommes."],[5,8,"Le reste de Jacob sera parmi les nations, Au milieu des peuples nombreux, Comme un lion parmi les bêtes de la forêt, Comme un lionceau parmi les troupeaux de brebis: Lorsqu'il passe, il foule et déchire, Et personne ne délivre.","Le reste de Jacob sera parmi les nations, Au milieu des peuples nombreux, Comme un lion parmi les bêtes de la forêt, Comme un lionceau parmi les troupeaux de brebis: Lorsqu'il passe, il foule et déchire, Et personne ne délivre."],[5,9,"Que ta main se lève sur tes adversaires, Et que tous tes ennemis soient exterminés!","Que ta main se lève sur tes adversaires, Et que tous tes ennemis soient exterminés!"],[5,10,"En ce jour-là, dit l'Éternel, J'exterminerai du milieu de toi tes chevaux, Et je détruirai tes chars;","En ce jour-là, dit l'Éternel, J'exterminerai du milieu de toi tes chevaux, Et je détruirai tes chars;"],[5,11,"J'exterminerai les villes de ton pays, Et je renverserai toutes tes forteresses;","J'exterminerai les villes de ton pays, Et je renverserai toutes tes forteresses;"],[5,12,"J'exterminerai de ta main les enchantements, Et tu n'auras plus de magiciens;","J'exterminerai de ta main les enchantements, Et tu n'auras plus de magiciens;"],[5,13,"J'exterminerai du milieu de toi tes idoles et tes statues, Et tu ne te prosterneras plus devant l'ouvrage de tes mains;","J'exterminerai du milieu de toi tes idoles et tes statues, Et tu ne te prosterneras plus devant l'ouvrage de tes mains;"],[5,14,"J'exterminerai du milieu de toi tes idoles d'Astarté, Et je détruirai tes villes.","J'exterminerai du milieu de toi tes idoles d'Astarté, Et je détruirai tes villes."],[5,15,"J'exercerai ma vengeance avec colère, avec fureur, sur les nations Qui n'ont pas écouté.","J'exercerai ma vengeance avec colère, avec fureur, sur les nations Qui n'ont pas écouté."],[6,1,"Écoutez donc ce que dit l'Éternel: Lève-toi, plaide devant les montagnes, Et que les collines entendent ta voix!...","Écoutez donc ce que dit l'Éternel: Lève-toi, plaide devant les montagnes, Et que les collines entendent ta voix!..."],[6,2,"Écoutez, montagnes, le procès de l'Éternel, Et vous, solides fondements de la terre! Car l'Éternel a un procès avec son peuple, Il veut plaider avec Israël. -","Écoutez, montagnes, le procès de l'Éternel, Et vous, solides fondements de la terre! Car l'Éternel a un procès avec son peuple, Il veut plaider avec Israël. -"],[6,3,"Mon peuple, que t'ai-je fait? En quoi t'ai-je fatigué? Réponds-moi!","Mon peuple, que t'ai-je fait? En quoi t'ai-je fatigué? Réponds-moi!"],[6,4,"Car je t'ai fait monter du pays d'Égypte, Je t'ai délivré de la maison de servitude, Et j'ai envoyé devant toi Moïse, Aaron et Marie.","Car je t'ai fait monter du pays d'Égypte, Je t'ai délivré de la maison de servitude, Et j'ai envoyé devant toi Moïse, Aaron et Marie."],[6,5,"Mon peuple, rappelle-toi ce que projetait Balak, roi de Moab, Et ce que lui répondit Balaam, fils de Beor, De Sittim à Guilgal, Afin que tu reconnaisses les bienfaits de l'Éternel.","Mon peuple, rappelle-toi ce que projetait Balak, roi de Moab, Et ce que lui répondit Balaam, fils de Beor, De Sittim à Guilgal, Afin que tu reconnaisses les bienfaits de l'Éternel."],[6,6,"Avec quoi me présenterai-je devant l'Éternel, Pour m'humilier devant le Dieu Très-Haut? Me présenterai-je avec des holocaustes, Avec des veaux d'un an?","Avec quoi me présenterai-je devant l'Éternel, Pour m'humilier devant le Dieu Très-Haut? Me présenterai-je avec des holocaustes, Avec des veaux d'un an?"],[6,7,"L'Éternel agréera-t-il des milliers de béliers, Des myriades de torrents d'huile? Donnerai-je pour mes transgressions mon premier-né, Pour le péché de mon âme le fruit de mes entrailles? -","L'Éternel agréera-t-il des milliers de béliers, Des myriades de torrents d'huile? Donnerai-je pour mes transgressions mon premier-né, Pour le péché de mon âme le fruit de mes entrailles? -"],[6,8,"On t'a fait connaître, ô homme, ce qui est bien; Et ce que l'Éternel demande de toi, C'est que tu pratiques la justice, Que tu aimes la miséricorde, Et que tu marches humblement avec ton Dieu.","On t'a fait connaître, ô homme, ce qui est bien; Et ce que l'Éternel demande de toi, C'est que tu pratiques la justice, Que tu aimes la miséricorde, Et que tu marches humblement avec ton Dieu."],[6,9,"La voix de l'Éternel crie à la ville, Et celui qui est sage craindra ton nom. Entendez la verge et celui qui l'envoie!","La voix de l'Éternel crie à la ville, Et celui qui est sage craindra ton nom. Entendez la verge et celui qui l'envoie!"],[6,10,"Y a-t-il encore dans la maison du méchant Des trésors iniques, Et un épha trop petit, objet de malédiction?","Y a-t-il encore dans la maison du méchant Des trésors iniques, Et un épha trop petit, objet de malédiction?"],[6,11,"Est-on pur avec des balances fausses, Et avec de faux poids dans le sac?","Est-on pur avec des balances fausses, Et avec de faux poids dans le sac?"],[6,12,"Ses riches sont pleins de violence, Ses habitants profèrent le mensonge, Et leur langue n'est que tromperie dans leur bouche.","Ses riches sont pleins de violence, Ses habitants profèrent le mensonge, Et leur langue n'est que tromperie dans leur bouche."],[6,13,"C'est pourquoi je te frapperai par la souffrance, Je te ravagerai à cause de tes péchés.","C'est pourquoi je te frapperai par la souffrance, Je te ravagerai à cause de tes péchés."],[6,14,"Tu mangeras sans te rassasier, Et la faim sera au dedans de toi; Tu mettras en réserve et tu ne sauveras pas, Et ce que tu sauveras, je le livrerai à l'épée.","Tu mangeras sans te rassasier, Et la faim sera au dedans de toi; Tu mettras en réserve et tu ne sauveras pas, Et ce que tu sauveras, je le livrerai à l'épée."],[6,15,"Tu sèmeras, et tu ne moissonneras pas, Tu presseras l'olive, et tu ne feras pas d'onctions avec l'huile, Tu presseras le moût, et tu ne boiras pas le vin.","Tu sèmeras, et tu ne moissonneras pas, Tu presseras l'olive, et tu ne feras pas d'onctions avec l'huile, Tu presseras le moût, et tu ne boiras pas le vin."],[6,16,"On observe les coutumes d'Omri Et toute la manière d'agir de la maison d'Achab, Et vous marchez d'après leurs conseils; C'est pourquoi je te livrerai à la destruction, Je ferai de tes habitants un sujet de raillerie, Et vous porterez l'opprobre de mon peuple.","On observe les coutumes d'Omri Et toute la manière d'agir de la maison d'Achab, Et vous marchez d'après leurs conseils; C'est pourquoi je te livrerai à la destruction, Je ferai de tes habitants un sujet de raillerie, Et vous porterez l'opprobre de mon peuple."],[7,1,"Malheur à moi! car je suis comme à la récolte des fruits, Comme au grappillage après la vendange: Il n'y a point de grappes à manger, Point de ces primeurs que mon âme désire.","Malheur à moi! car je suis comme à la récolte des fruits, Comme au grappillage après la vendange: Il n'y a point de grappes à manger, Point de ces primeurs que mon âme désire."],[7,2,"L'homme de bien a disparu du pays, Et il n'y a plus de juste parmi les hommes; Ils sont tous en embuscade pour verser le sang, Chacun tend un piège à son frère.","L'homme de bien a disparu du pays, Et il n'y a plus de juste parmi les hommes; Ils sont tous en embuscade pour verser le sang, Chacun tend un piège à son frère."],[7,3,"Leurs mains sont habiles à faire le mal: Le prince a des exigences, Le juge réclame un salaire, Le grand manifeste son avidité, Et ils font ainsi cause commune.","Leurs mains sont habiles à faire le mal: Le prince a des exigences, Le juge réclame un salaire, Le grand manifeste son avidité, Et ils font ainsi cause commune."],[7,4,"Le meilleur d'entre eux est comme une ronce, Le plus droit pire qu'un buisson d'épines. Le jour annoncé par tes prophètes, ton châtiment approche. C'est alors qu'ils seront dans la confusion.","Le meilleur d'entre eux est comme une ronce, Le plus droit pire qu'un buisson d'épines. Le jour annoncé par tes prophètes, ton châtiment approche. C'est alors qu'ils seront dans la confusion."],[7,5,"Ne crois pas à un ami, Ne te fie pas à un intime; Devant celle qui repose sur ton sein Garde les portes de ta bouche.","Ne crois pas à un ami, Ne te fie pas à un intime; Devant celle qui repose sur ton sein Garde les portes de ta bouche."],[7,6,"Car le fils outrage le père, La fille se soulève contre sa mère, La belle-fille contre sa belle-mère; Chacun a pour ennemis les gens de sa maison. -","Car le fils outrage le père, La fille se soulève contre sa mère, La belle-fille contre sa belle-mère; Chacun a pour ennemis les gens de sa maison. -"],[7,7,"Pour moi, je regarderai vers l'Éternel, Je mettrai mon espérance dans le Dieu de mon salut; Mon Dieu m'exaucera.","Pour moi, je regarderai vers l'Éternel, Je mettrai mon espérance dans le Dieu de mon salut; Mon Dieu m'exaucera."],[7,8,"Ne te réjouis pas à mon sujet, mon ennemie! Car si je suis tombée, je me relèverai; Si je suis assise dans les ténèbres, L'Éternel sera ma lumière.","Ne te réjouis pas à mon sujet, mon ennemie! Car si je suis tombée, je me relèverai; Si je suis assise dans les ténèbres, L'Éternel sera ma lumière."],[7,9,"Je supporterai la colère de l'Éternel, Puisque j'ai péché contre lui, Jusqu'à ce qu'il défende ma cause et me fasse droit; Il me conduira à la lumière, Et je contemplerai sa justice.","Je supporterai la colère de l'Éternel, Puisque j'ai péché contre lui, Jusqu'à ce qu'il défende ma cause et me fasse droit; Il me conduira à la lumière, Et je contemplerai sa justice."],[7,10,"Mon ennemie le verra et sera couverte de honte, Elle qui me disait: Où est l'Éternel, ton Dieu? Mes yeux se réjouiront à sa vue; Alors elle sera foulée aux pieds comme la boue des rues. -","Mon ennemie le verra et sera couverte de honte, Elle qui me disait: Où est l'Éternel, ton Dieu? Mes yeux se réjouiront à sa vue; Alors elle sera foulée aux pieds comme la boue des rues. -"],[7,11,"Le jour où l'on rebâtira tes murs, Ce jour-là tes limites seront reculées.","Le jour où l'on rebâtira tes murs, Ce jour-là tes limites seront reculées."],[7,12,"En ce jour, on viendra vers toi De l'Assyrie et des villes d'Égypte, De l'Égypte jusqu'au fleuve, D'une mer à l'autre, et d'une montagne à l'autre.","En ce jour, on viendra vers toi De l'Assyrie et des villes d'Égypte, De l'Égypte jusqu'au fleuve, D'une mer à l'autre, et d'une montagne à l'autre."],[7,13,"Le pays sera dévasté à cause de ses habitants, À cause du fruit de leurs oeuvres.","Le pays sera dévasté à cause de ses habitants, À cause du fruit de leurs oeuvres."],[7,14,"Pais ton peuple avec ta houlette, le troupeau de ton héritage, Qui habite solitaire dans la forêt au milieu du Carmel! Qu'ils paissent sur le Basan et en Galaad, Comme au jour d'autrefois. -","Pais ton peuple avec ta houlette, le troupeau de ton héritage, Qui habite solitaire dans la forêt au milieu du Carmel! Qu'ils paissent sur le Basan et en Galaad, Comme au jour d'autrefois. -"],[7,15,"Comme au jour où tu sortis du pays d'Égypte, Je te ferai voir des prodiges. -","Comme au jour où tu sortis du pays d'Égypte, Je te ferai voir des prodiges. -"],[7,16,"Les nations le verront, et seront confuses, Avec toute leur puissance; Elles mettront la main sur la bouche, Leurs oreilles seront assourdies.","Les nations le verront, et seront confuses, Avec toute leur puissance; Elles mettront la main sur la bouche, Leurs oreilles seront assourdies."],[7,17,"Elles lécheront la poussière, comme le serpent, Comme les reptiles de la terre; Elles seront saisies de frayeur hors de leurs forteresses; Elles trembleront devant l'Éternel, notre Dieu, Elles te craindront.","Elles lécheront la poussière, comme le serpent, Comme les reptiles de la terre; Elles seront saisies de frayeur hors de leurs forteresses; Elles trembleront devant l'Éternel, notre Dieu, Elles te craindront."],[7,18,"Quel Dieu est semblable à toi, Qui pardonnes l'iniquité, qui oublies les péchés Du reste de ton héritage? Il ne garde pas sa colère à toujours, Car il prend plaisir à la miséricorde.","Quel Dieu est semblable à toi, Qui pardonnes l'iniquité, qui oublies les péchés Du reste de ton héritage? Il ne garde pas sa colère à toujours, Car il prend plaisir à la miséricorde."],[7,19,"Il aura encore compassion de nous, Il mettra sous ses pieds nos iniquités; Tu jetteras au fond de la mer tous leurs péchés.","Il aura encore compassion de nous, Il mettra sous ses pieds nos iniquités; Tu jetteras au fond de la mer tous leurs péchés."],[7,20,"Tu témoigneras de la fidélité à Jacob, De la bonté à Abraham, Comme tu l'as juré à nos pères aux jours d'autrefois.","Tu témoigneras de la fidélité à Jacob, De la bonté à Abraham, Comme tu l'as juré à nos pères aux jours d'autrefois."]],"spa-rv1909":[[1,1,"PALABRAde JehováquefuéáMiqueasde Morasti en díasde Jotham, Achâz, y Ezechîas, reyesde Judá: lo queviósobreSamariay Jerusalem.","PALABRAde JehováquefuéáMiqueasde Morasti en díasde Jotham, Achâz, y Ezechîas, reyesde Judá: lo queviósobreSamariay Jerusalem."],[1,2,"Oid, pueblostodos: está atenta, tierra, y todo lo que en ella hay: y el SeñorJehová, el Señordesde su santotemploseatestigocontra vosotros.","Oid, pueblostodos: está atenta, tierra, y todo lo que en ella hay: y el SeñorJehová, el Señordesde su santotemploseatestigocontra vosotros."],[1,3,"Porquehe aquí, Jehovásalede su lugar, y descenderá, y hollarásobre las alturas de la tierra.","Porquehe aquí, Jehovásalede su lugar, y descenderá, y hollarásobre las alturas de la tierra."],[1,4,"Y debajode él se derretiránlos montes, y los vallesse hendiráncomo la ceradelantedel fuego, como las aguasque correnpor un precipicio.","Y debajode él se derretiránlos montes, y los vallesse hendiráncomo la ceradelantedel fuego, como las aguasque correnpor un precipicio."],[1,5,"Todoestopor la rebeliónde Jacob, y por los pecadosde la casade Israel. ¿Cuáles la rebeliónde Jacob? ¿noes Samaria? ¿Y cuálesson los excelsos de Judá? ¿noes Jerusalem?","Todoestopor la rebeliónde Jacob, y por los pecadosde la casade Israel. ¿Cuáles la rebeliónde Jacob? ¿noes Samaria? ¿Y cuálesson los excelsos de Judá? ¿noes Jerusalem?"],[1,6,"Pondrépues á Samariaen majanos de heredad, en tierrade viñas; y derramarésus piedraspor el valle, y descubrirésus fundamentos.","Pondrépues á Samariaen majanos de heredad, en tierrade viñas; y derramarésus piedraspor el valle, y descubrirésus fundamentos."],[1,7,"Y todassus estatuasserán despedazadas, y todossus donesserán quemadosen fuego, y asolarétodossus ídolos; porquede donesde rameraslos juntó, y ádonesde ramerasvolverán.","Y todassus estatuasserán despedazadas, y todossus donesserán quemadosen fuego, y asolarétodossus ídolos; porquede donesde rameraslos juntó, y ádonesde ramerasvolverán."],[1,8,"Portanto lamentaréy aullaré, y andarédespojado y desnudo; harégemido como de chacales, y lamentocomo de avestruces.","Portanto lamentaréy aullaré, y andarédespojado y desnudo; harégemido como de chacales, y lamentocomo de avestruces."],[1,9,"Porquesu llagaes dolorosa, que llegóhastaJudá; llegóhastala puertade mi pueblo, hastaJerusalem.","Porquesu llagaes dolorosa, que llegóhastaJudá; llegóhastala puertade mi pueblo, hastaJerusalem."],[1,10,"Nolo digáisen Gath, nilloréismucho: revuélcateen el polvode Beth-le-aphrah.","Nolo digáisen Gath, nilloréismucho: revuélcateen el polvode Beth-le-aphrah."],[1,11,"Pásatedesnudacon vergüenza, oh moradorade Saphir: la moradorade Saanánnosalióal llantode Beth-esel: tomaráde vosotrossu tardanza.","Pásatedesnudacon vergüenza, oh moradorade Saphir: la moradorade Saanánnosalióal llantode Beth-esel: tomaráde vosotrossu tardanza."],[1,12,"Porquela moradorade Marothtuvo dolorpor el bien; por cuanto el maldescendió de Jehováhasta la puertade Jerusalem.","Porquela moradorade Marothtuvo dolorpor el bien; por cuanto el maldescendió de Jehováhasta la puertade Jerusalem."],[1,13,"Unceal carrodromedarios, oh moradorade Lachîs, que fuiste principiode pecadoá la hijade Sión; porqueen ti se inventaron las rebelionesde Israel.","Unceal carrodromedarios, oh moradorade Lachîs, que fuiste principiode pecadoá la hijade Sión; porqueen ti se inventaron las rebelionesde Israel."],[1,14,"Por tanto, tú darásdonesá Moreseth-gath: las casasde Achzibserán en mentiraá los reyesde Israel.","Por tanto, tú darásdonesá Moreseth-gath: las casasde Achzibserán en mentiraá los reyesde Israel."],[1,15,"Aunte traeréheredero, oh moradorade Maresah: la gloriade Israelvendrá hastaAdullam.","Aunte traeréheredero, oh moradorade Maresah: la gloriade Israelvendrá hastaAdullam."],[1,16,"Mésate y trasquílateporlos hijosde tus delicias: ensancha tu calva como águila; porquefueron trasportadosdeti.","Mésate y trasquílateporlos hijosde tus delicias: ensancha tu calva como águila; porquefueron trasportadosdeti."],[2,1,"¡AYde los que piensaniniquidad, y de los que fabricanel malensus camas! Cuando vienela mañanalo ponen en obra, porquetienen en su manoel poder.","¡AYde los que piensaniniquidad, y de los que fabricanel malensus camas! Cuando vienela mañanalo ponen en obra, porquetienen en su manoel poder."],[2,2,"Y codiciaron las heredades, y robáronlas: y casas, y las tomaron: oprimieronal hombrey á su casa, al hombrey á su heredad.","Y codiciaron las heredades, y robáronlas: y casas, y las tomaron: oprimieronal hombrey á su casa, al hombrey á su heredad."],[2,3,"Por tanto, asíha dichoJehová: He aquí, yo piensosobre esta familia un mal, del cualnosacaréisvuestros cuellos, niandaréiserguidos; porqueel tiemposerá malo.","Por tanto, asíha dichoJehová: He aquí, yo piensosobre esta familia un mal, del cualnosacaréisvuestros cuellos, niandaréiserguidos; porqueel tiemposerá malo."],[2,4,"En aquel tiempose levantarásobrevosotros refrán, y se endecharáendechade lamentación, diciendo: Del todofuimos destruídos; ha cambiadola parte de mi pueblo. ¡Cómonos quitónuestroscampos! dió, repartiólosá otros.","En aquel tiempose levantarásobrevosotros refrán, y se endecharáendechade lamentación, diciendo: Del todofuimos destruídos; ha cambiadola parte de mi pueblo. ¡Cómonos quitónuestroscampos! dió, repartiólosá otros."],[2,5,"Por tanto, notendrás quien eche cordel para suerteen la congregaciónde Jehová.","Por tanto, notendrás quien eche cordel para suerteen la congregaciónde Jehová."],[2,6,"Noprofeticéis, dicená los que profetizan; noles profeticenque los ha de comprender vergüenza.","Noprofeticéis, dicená los que profetizan; noles profeticenque los ha de comprender vergüenza."],[2,7,"La que te dicescasade Jacob, ¿hase acortadoel espíritude Jehová? ¿sonéstas sus obras? ¿Mis palabrasnohacen bienal que caminaderechamente?","La que te dicescasade Jacob, ¿hase acortadoel espíritude Jehová? ¿sonéstas sus obras? ¿Mis palabrasnohacen bienal que caminaderechamente?"],[2,8,"El que ayerera mi pueblo, se ha levantadocomo enemigo: tras las vestiduras quitasteislas capasatrevidamenteá los que pasaban, comolos que vuelven de la guerra.","El que ayerera mi pueblo, se ha levantadocomo enemigo: tras las vestiduras quitasteislas capasatrevidamenteá los que pasaban, comolos que vuelven de la guerra."],[2,9,"A las mujeresde mi puebloechasteisfuera de las casasde sus delicias: ásus niñosquitasteismi perpetuaalabanza.","A las mujeresde mi puebloechasteisfuera de las casasde sus delicias: ásus niñosquitasteismi perpetuaalabanza."],[2,10,"Levantaos, y andad, que noes éstala holganza; porqueestácontaminada, corrompióse, y de grandecorrupción.","Levantaos, y andad, que noes éstala holganza; porqueestácontaminada, corrompióse, y de grandecorrupción."],[2,11,"Sihubierealgunoque andecon el viento, y finjamentirasdiciendo: Yote profetizaré de vinoy de sidra; este tal seráprofetaá este pueblo.","Sihubierealgunoque andecon el viento, y finjamentirasdiciendo: Yote profetizaré de vinoy de sidra; este tal seráprofetaá este pueblo."],[2,12,"De ciertote reunirétodo, oh Jacob: recogeréciertamenteel restode Israel: pondrélojuntocomo ovejasde Bosra, como rebañoen mitadde su majada: harán estruendopor la multitud delos hombres.","De ciertote reunirétodo, oh Jacob: recogeréciertamenteel restode Israel: pondrélojuntocomo ovejasde Bosra, como rebañoen mitadde su majada: harán estruendopor la multitud delos hombres."],[2,13,"Subirárompedordelantede ellos; romperány pasaránla puerta, y saldránpor ella: y su reypasarádelantede ellos, y á la cabezade ellos Jehová.","Subirárompedordelantede ellos; romperány pasaránla puerta, y saldránpor ella: y su reypasarádelantede ellos, y á la cabezade ellos Jehová."],[3,1,"Y DIJE: Oidahora, príncipesde Jacob, y cabezasde la casade Israel: ¿Nopertenecíaá vosotros saber el derecho?","Y DIJE: Oidahora, príncipesde Jacob, y cabezasde la casade Israel: ¿Nopertenecíaá vosotros saber el derecho?"],[3,2,"Que aborrecenlo buenoy amanlo malo, que lesquitansu piely su carnede sobrelos huesos;","Que aborrecenlo buenoy amanlo malo, que lesquitansu piely su carnede sobrelos huesos;"],[3,3,"Quecomenasimismo la carnede mi pueblo, y les desuellan su pielde sobreellos, y les quebrantan sus huesosy los rompen, como para el caldero, y como carnesen olla.","Quecomenasimismo la carnede mi pueblo, y les desuellan su pielde sobreellos, y les quebrantan sus huesosy los rompen, como para el caldero, y como carnesen olla."],[3,4,"EntoncesclamaránáJehováy noles responderá; antes esconderáde ellos surostroen aquel tiempo, por cuantohicieronmalvadas obras.","EntoncesclamaránáJehováy noles responderá; antes esconderáde ellos surostroen aquel tiempo, por cuantohicieronmalvadas obras."],[3,5,"Asíha dichoJehováacerca delos profetasque hacen errará mi pueblo, que muerden con sus dientes, y claman, Paz, y al quenoles diereque coman, aplazancontraél batalla:","Asíha dichoJehováacerca delos profetasque hacen errará mi pueblo, que muerden con sus dientes, y claman, Paz, y al quenoles diereque coman, aplazancontraél batalla:"],[3,6,"Por tanto, de la profecíase os hará noche, y oscuridaddel adivinar; y sobrelos profetasse pondráel sol, y el díase entenebrecerásobreellos.","Por tanto, de la profecíase os hará noche, y oscuridaddel adivinar; y sobrelos profetasse pondráel sol, y el díase entenebrecerásobreellos."],[3,7,"Y serán avergonzadoslos profetas, y confundiránselos adivinos; y ellos todoscubriránsu labio, porquenohay respuestade Dios.","Y serán avergonzadoslos profetas, y confundiránselos adivinos; y ellos todoscubriránsu labio, porquenohay respuestade Dios."],[3,8,"Yoempero estoy llenode fuerzadel espíritude Jehová, y de juicio, y de fortaleza, para denunciará Jacobsu rebelión, y á Israelsu pecado.","Yoempero estoy llenode fuerzadel espíritude Jehová, y de juicio, y de fortaleza, para denunciará Jacobsu rebelión, y á Israelsu pecado."],[3,9,"Oidahoraesto, cabezasde la casade Jacob, y capitanesde la casade Israel, que abomináisel juicio, y pervertístodoel derecho;","Oidahoraesto, cabezasde la casade Jacob, y capitanesde la casade Israel, que abomináisel juicio, y pervertístodoel derecho;"],[3,10,"Que edificáisá Sióncon sangre, y á Jerusalemcon injusticia;","Que edificáisá Sióncon sangre, y á Jerusalemcon injusticia;"],[3,11,"Sus cabezasjuzganpor cohecho, y sus sacerdotesenseñanpor precio, y sus profetasadivinanpor dinero; y apóyanseenJehovádiciendo: ¿Noestá Jehováentre nosotros? Novendrámalsobrenosotros.","Sus cabezasjuzganpor cohecho, y sus sacerdotesenseñanpor precio, y sus profetasadivinanpor dinero; y apóyanseenJehovádiciendo: ¿Noestá Jehováentre nosotros? Novendrámalsobrenosotros."],[3,12,"Por tanto, á causa de vosotros será Siónaradacomo campo, y Jerusalemserá majanos, y el montede la casacomo cumbresde breñal.","Por tanto, á causa de vosotros será Siónaradacomo campo, y Jerusalemserá majanos, y el montede la casacomo cumbresde breñal."],[4,1,"Y ACONTECERÁen los postrerostiempos, que el montede la casade Jehováseráconstituídopor cabecerade montes, y más altoque los collados, y correránáélpueblos.","Y ACONTECERÁen los postrerostiempos, que el montede la casade Jehováseráconstituídopor cabecerade montes, y más altoque los collados, y correránáélpueblos."],[4,2,"Y vendránmuchasgentes, y dirán: Venid, y subamosalmontede Jehová, y ála casadel Diosde Jacob; y enseñaránosen sus caminos, y andaremospor sus veredas: porquede Siónsaldrála ley, y de Jerusalemla palabrade Jehová.","Y vendránmuchasgentes, y dirán: Venid, y subamosalmontede Jehová, y ála casadel Diosde Jacob; y enseñaránosen sus caminos, y andaremospor sus veredas: porquede Siónsaldrála ley, y de Jerusalemla palabrade Jehová."],[4,3,"Y juzgaráentremuchospueblos, y corregiráfuertes genteshastamuy lejos: y martillaránsus espadaspara azadones, y sus lanzaspara hoces: noalzaráespadagentecontragente, nimásse ensayaránpara la guerra.","Y juzgaráentremuchospueblos, y corregiráfuertes genteshastamuy lejos: y martillaránsus espadaspara azadones, y sus lanzaspara hoces: noalzaráespadagentecontragente, nimásse ensayaránpara la guerra."],[4,4,"Y cada unose sentarádebajode su vidy debajode su higuera, y nohabrá quien amedrente: porquela bocade Jehováde los ejércitoslo ha hablado.","Y cada unose sentarádebajode su vidy debajode su higuera, y nohabrá quien amedrente: porquela bocade Jehováde los ejércitoslo ha hablado."],[4,5,"Bien que todoslos pueblosanduvieren cada unoen el nombrede sus dioses, nosotroscon todo andaremosen el nombrede JehovánuestroDiospara siemprey eternalmente.","Bien que todoslos pueblosanduvieren cada unoen el nombrede sus dioses, nosotroscon todo andaremosen el nombrede JehovánuestroDiospara siemprey eternalmente."],[4,6,"En aquel día, diceJehová, juntaréla coja, y recogeréla amontada, y á la que afligí;","En aquel día, diceJehová, juntaréla coja, y recogeréla amontada, y á la que afligí;"],[4,7,"Y pondréá la cojapara sucesión, y á la descarriadapara naciónrobusta: y Jehováreinarásobreellos en el montede Sióndesde ahoraparasiempre.","Y pondréá la cojapara sucesión, y á la descarriadapara naciónrobusta: y Jehováreinarásobreellos en el montede Sióndesde ahoraparasiempre."],[4,8,"Y tú, oh torredel rebaño, la fortalezade la hijade Siónvendráhastati: y el señoríoprimero, el reinovendráá la hijade Jerusalem.","Y tú, oh torredel rebaño, la fortalezade la hijade Siónvendráhastati: y el señoríoprimero, el reinovendráá la hijade Jerusalem."],[4,9,"Ahora¿por quégritastanto? ¿Nohay reyen ti? ¿Pereciótu consejero, quete ha tomadodolorcomo de mujer de parto?","Ahora¿por quégritastanto? ¿Nohay reyen ti? ¿Pereciótu consejero, quete ha tomadodolorcomo de mujer de parto?"],[4,10,"Duéletey gime, hijade Sión, como mujer de parto; porqueahorasaldrásde la ciudad, y morarásen el campo, y llegaráshastaBabilonia: allíserás librada, allíte redimiráJehováde la manode tus enemigos.","Duéletey gime, hijade Sión, como mujer de parto; porqueahorasaldrásde la ciudad, y morarásen el campo, y llegaráshastaBabilonia: allíserás librada, allíte redimiráJehováde la manode tus enemigos."],[4,11,"Ahoraempero se han juntadomuchasgentescontrati, y dicen: Sea profanada, y veannuestrosojossu deseosobre Sión.","Ahoraempero se han juntadomuchasgentescontrati, y dicen: Sea profanada, y veannuestrosojossu deseosobre Sión."],[4,12,"Mas ellosnoconocieronlos pensamientosde Jehová, nientendieronsu consejo: porlo cual losjuntócomo gavillasen la era.","Mas ellosnoconocieronlos pensamientosde Jehová, nientendieronsu consejo: porlo cual losjuntócomo gavillasen la era."],[4,13,"Levántatey trilla, hija de Sión, porquetu cuernotornaréde hierro, y tus uñas de metal, y desmenuzarás muchospueblos; y consagrarásá Jehovásus robos, y sus riquezasal Señorde todala tierra.","Levántatey trilla, hija de Sión, porquetu cuernotornaréde hierro, y tus uñas de metal, y desmenuzarás muchospueblos; y consagrarásá Jehovásus robos, y sus riquezasal Señorde todala tierra."],[5,1,"REÚNETEahoraenbandas, oh hijade bandas: noshan sitiado: con varaheriránsobre la quijadaal juezde Israel.","REÚNETEahoraenbandas, oh hijade bandas: noshan sitiado: con varaheriránsobre la quijadaal juezde Israel."],[5,2,"Mas tú, Beth-lehemEphrata, pequeñapara seren los millaresde Judá, detime saldráel que será Señoren Israel; y sus salidas son desdeel principio, desdelos díasdel siglo.","Mas tú, Beth-lehemEphrata, pequeñapara seren los millaresde Judá, detime saldráel que será Señoren Israel; y sus salidas son desdeel principio, desdelos díasdel siglo."],[5,3,"Empero los dejaráhastael tiempoque para la que ha de parir; y el restode sus hermanosse tornarácon los hijosde Israel.","Empero los dejaráhastael tiempoque para la que ha de parir; y el restode sus hermanosse tornarácon los hijosde Israel."],[5,4,"Y estará, y apacentarácon fortalezade Jehová, con grandezadel nombrede Jehovásu Dios: y asentarán; porqueahoraserá engrandecidohastalos finesde la tierra.","Y estará, y apacentarácon fortalezade Jehová, con grandezadel nombrede Jehovásu Dios: y asentarán; porqueahoraserá engrandecidohastalos finesde la tierra."],[5,5,"Y ésteseránuestrapaz. CuandoAssurviniereá nuestratierra, y cuandopisare nuestrospalacios, entonces levantaremoscontraél sietepastores, y ochohombresprincipales;","Y ésteseránuestrapaz. CuandoAssurviniereá nuestratierra, y cuandopisare nuestrospalacios, entonces levantaremoscontraél sietepastores, y ochohombresprincipales;"],[5,6,"Y comeránla tierrade Assurá cuchillo, y la tierrade Nimrodcon sus espadas: y nos librarádel Asirio, cuandovinierecontra nuestratierray hollarenuestrostérminos.","Y comeránla tierrade Assurá cuchillo, y la tierrade Nimrodcon sus espadas: y nos librarádel Asirio, cuandovinierecontra nuestratierray hollarenuestrostérminos."],[5,7,"Y seráel residuode Jacoben mediode muchospueblos, como el rocíode Jehová, como las lluviassobrela hierba, las cualesnoesperanvarón, niaguardaná hijosde hombres.","Y seráel residuode Jacoben mediode muchospueblos, como el rocíode Jehová, como las lluviassobrela hierba, las cualesnoesperanvarón, niaguardaná hijosde hombres."],[5,8,"Asimismo seráel resto de Jacobentre las gentes, en mediode muchospueblos, como el leónentre las bestiasde la montaña, como el cachorrodel leónentre las manadasde las ovejas, el cualsipasare, y hollare, y arrebatare, nohay quien escape.","Asimismo seráel resto de Jacobentre las gentes, en mediode muchospueblos, como el leónentre las bestiasde la montaña, como el cachorrodel leónentre las manadasde las ovejas, el cualsipasare, y hollare, y arrebatare, nohay quien escape."],[5,9,"Tu manose alzarásobretus enemigos, y todostus adversariosserán talados.","Tu manose alzarásobretus enemigos, y todostus adversariosserán talados."],[5,10,"Y aconteceráen aquel día, diceJehová, que haré matartus caballosde en mediode ti, y haré destruirtus carros.","Y aconteceráen aquel día, diceJehová, que haré matartus caballosde en mediode ti, y haré destruirtus carros."],[5,11,"Haré también destruirlas ciudadesde tu tierra, y arruinarétodastus fortalezas.","Haré también destruirlas ciudadesde tu tierra, y arruinarétodastus fortalezas."],[5,12,"Asimismo destruiréde tu manolas hechicerías, y nose hallaránen ti agoreros.","Asimismo destruiréde tu manolas hechicerías, y nose hallaránen ti agoreros."],[5,13,"Y haré destruirtus esculturasy tus imágenesde en mediode ti, y nuncamáste inclinarásá la obrade tus manos;","Y haré destruirtus esculturasy tus imágenesde en mediode ti, y nuncamáste inclinarásá la obrade tus manos;"],[5,14,"Y arrancarétus bosquesde en mediode ti, y destruirétus ciudades.","Y arrancarétus bosquesde en mediode ti, y destruirétus ciudades."],[5,15,"Y con iray con furorharévenganzaen las gentesquenoescucharon.","Y con iray con furorharévenganzaen las gentesquenoescucharon."],[6,1,"OIDahoralo quediceJehová: Levántate, pleitea con los montes, y oiganlos colladostu voz.","OIDahoralo quediceJehová: Levántate, pleitea con los montes, y oiganlos colladostu voz."],[6,2,"Oid, montes, y fuertesfundamentos de la tierra, el pleitode Jehová: porquetiene Jehovápleitoconsu pueblo, y altercaráconIsrael.","Oid, montes, y fuertesfundamentos de la tierra, el pleitode Jehová: porquetiene Jehovápleitoconsu pueblo, y altercaráconIsrael."],[6,3,"Pueblomío, ¿quéte he hecho, ó en quéte he molestado? Respondecontra mí.","Pueblomío, ¿quéte he hecho, ó en quéte he molestado? Respondecontra mí."],[6,4,"Porqueyo te hice subirde la tierrade Egipto, y de la casade siervos te redimí; y enviédelantede ti á Moisés, y á Aarón, y á María.","Porqueyo te hice subirde la tierrade Egipto, y de la casade siervos te redimí; y enviédelantede ti á Moisés, y á Aarón, y á María."],[6,5,"Pueblomío, acuérdateahoraquéaconsejóBalacreyde Moab, y quéle respondióBalaam, hijode Beor, desdeSittimhastaGilgal, para que conozcaslas justiciasde Jehová.","Pueblomío, acuérdateahoraquéaconsejóBalacreyde Moab, y quéle respondióBalaam, hijode Beor, desdeSittimhastaGilgal, para que conozcaslas justiciasde Jehová."],[6,6,"¿Con quéprevendré á Jehová, y adoraréal altoDios? ¿vendréante él con holocaustos, con becerrosde un año?","¿Con quéprevendré á Jehová, y adoraréal altoDios? ¿vendréante él con holocaustos, con becerrosde un año?"],[6,7,"¿AgradaráseJehováde millaresde carneros, ó de diezmilarroyosde aceite? ¿darémi primogénitopor mi rebelión, el frutode mi vientre por el pecadode mi alma?","¿AgradaráseJehováde millaresde carneros, ó de diezmilarroyosde aceite? ¿darémi primogénitopor mi rebelión, el frutode mi vientre por el pecadode mi alma?"],[6,8,"Oh hombre, él te ha declaradoquésea lo bueno, y quépida deti Jehová: solamente hacerjuicio, y amarmisericordia, y humillartepara andar con tu Dios.","Oh hombre, él te ha declaradoquésea lo bueno, y quépida deti Jehová: solamente hacerjuicio, y amarmisericordia, y humillartepara andar con tu Dios."],[6,9,"La vozde Jehováclamaá la ciudad, y el sabiomiraráá tu nombre. Oidla vara, y á quien laestablece.","La vozde Jehováclamaá la ciudad, y el sabiomiraráá tu nombre. Oidla vara, y á quien laestablece."],[6,10,"¿Hay aúnen casadel impíotesorosde impiedad, y medidaescasaque es detestable?","¿Hay aúnen casadel impíotesorosde impiedad, y medidaescasaque es detestable?"],[6,11,"¿Seré limpiocon pesofalso, y con bolsade engañosaspesas?","¿Seré limpiocon pesofalso, y con bolsade engañosaspesas?"],[6,12,"Con lo cual sus ricos se hinchieronde rapiña, y sus moradoreshablaronmentira, y su lenguaengañosaen su boca.","Con lo cual sus ricos se hinchieronde rapiña, y sus moradoreshablaronmentira, y su lenguaengañosaen su boca."],[6,13,"Por eso yotambiénte enflaqueceré hiriéndote, asolándoteportus pecados.","Por eso yotambiénte enflaqueceré hiriéndote, asolándoteportus pecados."],[6,14,"Tú comerás, y note hartarás; y tuabatimientoserá en mediode ti: tú cogerás, mas nosalvarás; y lo quesalvares, lo entregaréyo á la espada.","Tú comerás, y note hartarás; y tuabatimientoserá en mediode ti: tú cogerás, mas nosalvarás; y lo quesalvares, lo entregaréyo á la espada."],[6,15,"Tú sembrarás, mas nosegarás: pisarásaceitunas, mas note ungirás con el aceite; y mosto, mas nobeberásel vino.","Tú sembrarás, mas nosegarás: pisarásaceitunas, mas note ungirás con el aceite; y mosto, mas nobeberásel vino."],[6,16,"Porque los mandamientosde Omrise han guardado, y todaobrade la casade Achâb; y en los consejosde ellos anduvisteis, para que yo te diese en asolamiento, y tus moradorespara ser silbados. Llevaréispor tanto el oprobiode mi pueblo.","Porque los mandamientosde Omrise han guardado, y todaobrade la casade Achâb; y en los consejosde ellos anduvisteis, para que yo te diese en asolamiento, y tus moradorespara ser silbados. Llevaréispor tanto el oprobiode mi pueblo."],[7,1,"¡AYde mí! que he venido á ser como cuando han cogido los frutosdel verano, como cuando han rebuscado después de la vendimia, quenoquedaracimopara comer; mi almadeseóprimeros frutos.","¡AYde mí! que he venido á ser como cuando han cogido los frutosdel verano, como cuando han rebuscado después de la vendimia, quenoquedaracimopara comer; mi almadeseóprimeros frutos."],[7,2,"Faltóel misericordiosodela tierra, y ningunohay rectoentre los hombres: todosacechaná la sangre; cada cualarma redá su hermano.","Faltóel misericordiosodela tierra, y ningunohay rectoentre los hombres: todosacechaná la sangre; cada cualarma redá su hermano."],[7,3,"Paracompletar la maldadcon sus manos, el príncipedemanda, y el juezjuzgapor recompensa; y el grandehablael antojode sualma, y loconfirman.","Paracompletar la maldadcon sus manos, el príncipedemanda, y el juezjuzgapor recompensa; y el grandehablael antojode sualma, y loconfirman."],[7,4,"El mejorde ellos es como el cambrón; el más recto, comozarzal: el díade tus atalayas, tu visitación, viene; ahora serásu confusión.","El mejorde ellos es como el cambrón; el más recto, comozarzal: el díade tus atalayas, tu visitación, viene; ahora serásu confusión."],[7,5,"Nocreáisen amigo, niconfiéisen príncipe: de la que duermeá tu lado, guarda, noabrastu boca.","Nocreáisen amigo, niconfiéisen príncipe: de la que duermeá tu lado, guarda, noabrastu boca."],[7,6,"Porqueel hijodeshonraal padre, la hijase levantacontra la madre, la nueracontra su suegra: y los enemigosdel hombreson losde su casa.","Porqueel hijodeshonraal padre, la hijase levantacontra la madre, la nueracontra su suegra: y los enemigosdel hombreson losde su casa."],[7,7,"Yoempero á Jehováesperaré, esperaréal Diosde misalud: el Diosmíomeoirá.","Yoempero á Jehováesperaré, esperaréal Diosde misalud: el Diosmíomeoirá."],[7,8,"Tú, enemiga mía, no tehuelgues de mí: porqueaunque caí, he de levantarme; aunquemoreen tinieblas, Jehováserá mi luz.","Tú, enemiga mía, no tehuelgues de mí: porqueaunque caí, he de levantarme; aunquemoreen tinieblas, Jehováserá mi luz."],[7,9,"La irade Jehovásoportaré, porquepequécontra él, hastaquejuzguemi causay hagami juicio; él me sacaráá luz; verésu justicia.","La irade Jehovásoportaré, porquepequécontra él, hastaquejuzguemi causay hagami juicio; él me sacaráá luz; verésu justicia."],[7,10,"Y mi enemigaverá, y la cubrirávergüenza: la que medecía: ¿Dóndeestá Jehovátu Dios? Mis ojosla verán; ahoraseráholladacomo lodode las calles.","Y mi enemigaverá, y la cubrirávergüenza: la que medecía: ¿Dóndeestá Jehovátu Dios? Mis ojosla verán; ahoraseráholladacomo lodode las calles."],[7,11,"El díaen que se edificarántus muros, aquel díaserá alejadoel mandamiento.","El díaen que se edificarántus muros, aquel díaserá alejadoel mandamiento."],[7,12,"En esedíavendránhastati desdeAsiriay las ciudadesfuertes, y desdelas ciudades fuerteshastael Río, y demará mar, y demonteá monte.","En esedíavendránhastati desdeAsiriay las ciudadesfuertes, y desdelas ciudades fuerteshastael Río, y demará mar, y demonteá monte."],[7,13,"Y la tierracon sus moradoresseráasoladapor el frutode sus obras.","Y la tierracon sus moradoresseráasoladapor el frutode sus obras."],[7,14,"Apacientatu pueblocon tu cayado, el rebañode tu heredad, que morasoloen la montaña, en medio del Carmelo: pazcanen Basány Galaad, como en el tiempopasado.","Apacientatu pueblocon tu cayado, el rebañode tu heredad, que morasoloen la montaña, en medio del Carmelo: pazcanen Basány Galaad, como en el tiempopasado."],[7,15,"Yo les mostrarémaravillascomo el díaque salistede Egipto.","Yo les mostrarémaravillascomo el díaque salistede Egipto."],[7,16,"Las gentesverán, y se avergonzaránde todas sus valentías; pondránla manosobresu boca, ensordeceránsus oídos.","Las gentesverán, y se avergonzaránde todas sus valentías; pondránla manosobresu boca, ensordeceránsus oídos."],[7,17,"Lameránel polvocomo la culebra; como las serpientesde la tierra, temblaránensus encierros: despavorirsehan deJehovánuestroDios, y temerándeti.","Lameránel polvocomo la culebra; como las serpientesde la tierra, temblaránensus encierros: despavorirsehan deJehovánuestroDios, y temerándeti."],[7,18,"¿QuéDioscomo tú, que perdonas la maldad, y olvidasel pecadodel restode suheredad? Noretuvopara siempresuenojo, porquees amadorde misericordia.","¿QuéDioscomo tú, que perdonas la maldad, y olvidasel pecadodel restode suheredad? Noretuvopara siempresuenojo, porquees amadorde misericordia."],[7,19,"El tornará, él tendrá misericordiade nosotros; él sujetaránuestrasiniquidades, y echaráen los profundos de la martodosnuestros pecados.","El tornará, él tendrá misericordiade nosotros; él sujetaránuestrasiniquidades, y echaráen los profundos de la martodosnuestros pecados."],[7,20,"Otorgarás á Jacobla verdad, y á Abrahamla misericordia, quetú jurasteá nuestrospadresdesde tiemposantiguos.","Otorgarás á Jacobla verdad, y á Abrahamla misericordia, quetú jurasteá nuestrospadresdesde tiemposantiguos."]],"rus-synodal":[[1,1,"Слово Господне, которое было к Михею Морасфитину во дни Иоафама, Ахаза и Езекии, царей Иудейских, и которое открыто ему о Самарии и Иерусалиме.","Slovo Gospodne, kotoroe bylo k Miheû Morasfitinu vo dni Ioafama, Ahaza i Ezekii, carej Iudejskih, i kotoroe otkryto emu o Samarii i Ierusalime."],[1,2,"Слушайте, все народы, внимай, земля и все, что наполняет ее! Да будет Господь Бог свидетелем против вас, Господь из святого храма Своего!","Slušajte, vse narody, vnimaj, zemlâ i vse, čto napolnâet ee! Da budet Gospodʹ Bog svidetelem protiv vas, Gospodʹ iz svâtogo hrama Svoego!"],[1,3,"Ибо вот, Господь исходит от места Своего, низойдет и наступит на высоты земли, –","Ibo vot, Gospodʹ ishodit ot mesta Svoego, nizojdet i nastupit na vysoty zemli, –"],[1,4,"и горы растают под Ним, долины распадутся, как воск от огня, как воды, льющиеся с крутизны.","i gory rastaût pod Nim, doliny raspadutsâ, kak vosk ot ognâ, kak vody, lʹûŝiesâ s krutizny."],[1,5,"Все это – за нечестие Иакова, за грех дома Израилева. От кого нечестие Иакова? не от Самарии ли? Кто устроил высоты в Иудее? не Иерусалим ли?","Vse éto – za nečestie Iakova, za greh doma Izraileva. Ot kogo nečestie Iakova? ne ot Samarii li? Kto ustroil vysoty v Iudee? ne Ierusalim li?"],[1,6,"За то сделаю Самарию грудою развалин в поле, местом для разведения винограда; низрину в долину камни ее и обнажу основания ее.","Za to sdelaû Samariû grudoû razvalin v pole, mestom dlâ razvedeniâ vinograda; nizrinu v dolinu kamni ee i obnažu osnovaniâ ee."],[1,7,"Все истуканы ее будут разбиты и все любодейные дары ее сожжены будут огнем, и всех идолов ее предам разрушению, ибо из любодейных даров она устраивала их, на любодейные дары они и будут обращены.","Vse istukany ee budut razbity i vse lûbodejnye dary ee sožženy budut ognem, i vseh idolov ee predam razrušeniû, ibo iz lûbodejnyh darov ona ustraivala ih, na lûbodejnye dary oni i budut obraŝeny."],[1,8,"Об этом буду я плакать и рыдать, буду ходить, как ограбленный и обнаженный, выть, как шакалы, и плакать, как страусы,","Ob étom budu â plakatʹ i rydatʹ, budu hoditʹ, kak ograblennyj i obnažennyj, vytʹ, kak šakaly, i plakatʹ, kak strausy,"],[1,9,"потому что болезненно поражение ее, дошло до Иуды, достигло даже до ворот народа моего, до Иерусалима.","potomu čto boleznenno poraženie ee, došlo do Iudy, dostiglo daže do vorot naroda moego, do Ierusalima."],[1,10,"Не объявляйте об этом в Гефе, не плачьте там громко; но в селении Офра покрой себя пеплом.","Ne obʺâvlâjte ob étom v Gefe, ne plačʹte tam gromko; no v selenii Ofra pokroj sebâ peplom."],[1,11,"Переселяйтесь, жительницы Шафира, срамно обнаженные; не убежит и живущая в Цаане; плач в селении Ецель не даст вам остановиться в нем.","Pereselâjtesʹ, žitelʹnicy Šafira, sramno obnažennye; ne ubežit i živuŝaâ v Caane; plač v selenii Ecelʹ ne dast vam ostanovitʹsâ v nem."],[1,12,"Горюет о своем добре жительница Марофы, ибо сошло бедствие от Господа к воротам Иерусалима.","Gorûet o svoem dobre žitelʹnica Marofy, ibo sošlo bedstvie ot Gospoda k vorotam Ierusalima."],[1,13,"Запрягай в колесницу быстрых, жительница Лахиса; ты – начало греха дщери Сионовой, ибо у тебя появились преступления Израиля.","Zaprâgaj v kolesnicu bystryh, žitelʹnica Lahisa; ty – načalo greha dŝeri Sionovoj, ibo u tebâ poâvilisʹ prestupleniâ Izrailâ."],[1,14,"Посему ты посылать будешь дары в Морешеф-Геф; но селения Ахзива будут обманом для царей Израилевых.","Posemu ty posylatʹ budešʹ dary v Morešef-Gef; no seleniâ Ahziva budut obmanom dlâ carej Izrailevyh."],[1,15,"Еще наследника приведу к тебе, жительница Мореша; он пройдет до Одоллама, славы Израиля.","Eŝe naslednika privedu k tebe, žitelʹnica Moreša; on projdet do Odollama, slavy Izrailâ."],[1,16,"Сними с себя волосы, остригись, скорбя о нежно любимых сынах твоих; расширь из-за них лысину, как у линяющего орла, ибо они переселены будут от тебя.","Snimi s sebâ volosy, ostrigisʹ, skorbâ o nežno lûbimyh synah tvoih; rasširʹ iz-za nih lysinu, kak u linâûŝego orla, ibo oni pereseleny budut ot tebâ."],[2,1,"Горе замышляющим беззаконие и на ложах своих придумывающим злодеяния, которые совершают утром на рассвете, потому что есть в руке их сила!","Gore zamyšlâûŝim bezzakonie i na ložah svoih pridumyvaûŝim zlodeâniâ, kotorye soveršaût utrom na rassvete, potomu čto estʹ v ruke ih sila!"],[2,2,"Пожелают полей и берут их силою, домов – и отнимают их; обирают человека и его дом, мужа и его наследие.","Poželaût polej i berut ih siloû, domov – i otnimaût ih; obiraût čeloveka i ego dom, muža i ego nasledie."],[2,3,"Посему так говорит Господь: вот, Я помышляю навести на этот род такое бедствие, которого вы не свергнете с шеи вашей, и не будете ходить выпрямившись; ибо это время злое.","Posemu tak govorit Gospodʹ: vot, Â pomyšlâû navesti na étot rod takoe bedstvie, kotorogo vy ne svergnete s šei vašej, i ne budete hoditʹ vyprâmivšisʹ; ibo éto vremâ zloe."],[2,4,"В тот день произнесут о вас притчу и будут плакать горьким плачем и говорить: «мы совершенно разорены! удел народа моего отдан другим; как возвратится ко мне! поля наши уже разделены иноплеменникам».","V tot denʹ proiznesut o vas pritču i budut plakatʹ gorʹkim plačem i govoritʹ: «my soveršenno razoreny! udel naroda moego otdan drugim; kak vozvratitsâ ko mne! polâ naši uže razdeleny inoplemennikam»."],[2,5,"Посему не будет у тебя никого, кто бросил бы жребий для измерения в собрании пред Господом.","Posemu ne budet u tebâ nikogo, kto brosil by žrebij dlâ izmereniâ v sobranii pred Gospodom."],[2,6,"Не пророчествуйте, пророки; не пророчествуйте им, чтобы не постигло вас бесчестие.","Ne proročestvujte, proroki; ne proročestvujte im, čtoby ne postiglo vas besčestie."],[2,7,"О, называющийся домом Иакова! разве умалился Дух Господень? таковы ли действия Его? не благотворны ли слова Мои для того, кто поступает справедливо?","O, nazyvaûŝijsâ domom Iakova! razve umalilsâ Duh Gospodenʹ? takovy li dejstviâ Ego? ne blagotvorny li slova Moi dlâ togo, kto postupaet spravedlivo?"],[2,8,"Народ же, который был прежде Моим, восстал как враг, и вы отнимаете как верхнюю, так и нижнюю одежду у проходящих мирно, отвращающихся войны.","Narod že, kotoryj byl prežde Moim, vosstal kak vrag, i vy otnimaete kak verhnûû, tak i nižnûû odeždu u prohodâŝih mirno, otvraŝaûŝihsâ vojny."],[2,9,"Жен народа Моего вы изгоняете из приятных домов их; у детей их вы навсегда отнимаете украшение Мое.","Žen naroda Moego vy izgonâete iz priâtnyh domov ih; u detej ih vy navsegda otnimaete ukrašenie Moe."],[2,10,"Встаньте и уходите, ибо страна сия не есть место покоя; за нечистоту она будет разорена, и притом жестоким разорением.","Vstanʹte i uhodite, ibo strana siâ ne estʹ mesto pokoâ; za nečistotu ona budet razorena, i pritom žestokim razoreniem."],[2,11,"Если бы какой-либо ветреник выдумал ложь и сказал: «я буду проповедовать тебе о вине и сикере», то он и был бы угодным проповедником для этого народа.","Esli by kakoj-libo vetrenik vydumal ložʹ i skazal: «â budu propovedovatʹ tebe o vine i sikere», to on i byl by ugodnym propovednikom dlâ étogo naroda."],[2,12,"Непременно соберу всего тебя, Иаков, непременно соединю остатки Израиля, совокуплю их воедино, как овец в Восоре, как стадо в овечьем загоне; зашумят они от многолюдства.","Nepremenno soberu vsego tebâ, Iakov, nepremenno soedinû ostatki Izrailâ, sovokuplû ih voedino, kak ovec v Vosore, kak stado v ovečʹem zagone; zašumât oni ot mnogolûdstva."],[2,13,"Перед ними пойдет стенорушитель; они сокрушат преграды, войдут сквозь ворота и выйдут ими; и царь их пойдет перед ними, а во главе их – Господь.","Pered nimi pojdet stenorušitelʹ; oni sokrušat pregrady, vojdut skvozʹ vorota i vyjdut imi; i carʹ ih pojdet pered nimi, a vo glave ih – Gospodʹ."],[3,1,"И сказал я: слушайте, главы Иакова и князья дома Израилева: не вам ли должно знать правду?","I skazal â: slušajte, glavy Iakova i knâzʹâ doma Izraileva: ne vam li dolžno znatʹ pravdu?"],[3,2,"А вы ненавидите доброе и любите злое; сдираете с них кожу их и плоть с костей их,","A vy nenavidite dobroe i lûbite zloe; sdiraete s nih kožu ih i plotʹ s kostej ih,"],[3,3,"едите плоть народа Моего и сдираете с них кожу их, а кости их ломаете и дробите как бы в горшок, и плоть – как бы в котел.","edite plotʹ naroda Moego i sdiraete s nih kožu ih, a kosti ih lomaete i drobite kak by v goršok, i plotʹ – kak by v kotel."],[3,4,"И будут они взывать к Господу, но Он не услышит их и сокроет лицо Свое от них на то время, как они злодействуют.","I budut oni vzyvatʹ k Gospodu, no On ne uslyšit ih i sokroet lico Svoe ot nih na to vremâ, kak oni zlodejstvuût."],[3,5,"Так говорит Господь на пророков, вводящих в заблуждение народ Мой, которые грызут зубами своими – и проповедуют мир, а кто ничего не кладет им в рот, против того объявляют войну.","Tak govorit Gospodʹ na prorokov, vvodâŝih v zabluždenie narod Moj, kotorye gryzut zubami svoimi – i propoveduût mir, a kto ničego ne kladet im v rot, protiv togo obʺâvlâût vojnu."],[3,6,"Посему ночь будет вам вместо видения и тьма – вместо предвещаний; зайдет солнце над пророками, и потемнеет день над ними.","Posemu nočʹ budet vam vmesto videniâ i tʹma – vmesto predveŝanij; zajdet solnce nad prorokami, i potemneet denʹ nad nimi."],[3,7,"И устыдятся прозорливцы, и посрамлены будут гадатели, и закроют уста свои все они, потому что не будет ответа от Бога.","I ustydâtsâ prozorlivcy, i posramleny budut gadateli, i zakroût usta svoi vse oni, potomu čto ne budet otveta ot Boga."],[3,8,"А я исполнен силы Духа Господня, правоты и твердости, чтобы высказать Иакову преступление его и Израилю грех его.","A â ispolnen sily Duha Gospodnâ, pravoty i tverdosti, čtoby vyskazatʹ Iakovu prestuplenie ego i Izrailû greh ego."],[3,9,"Слушайте же это, главы дома Иаковлева и князья дома Израилева, гнушающиеся правосудием и искривляющие все прямое,","Slušajte že éto, glavy doma Iakovleva i knâzʹâ doma Izraileva, gnušaûŝiesâ pravosudiem i iskrivlâûŝie vse prâmoe,"],[3,10,"созидающие Сион кровью и Иерусалим – неправдою!","sozidaûŝie Sion krovʹû i Ierusalim – nepravdoû!"],[3,11,"Главы его судят за подарки и священники его учат за плату, и пророки его предвещают за деньги, а между тем опираются на Господа, говоря: «не среди ли нас Господь? не постигнет нас беда!»","Glavy ego sudât za podarki i svâŝenniki ego učat za platu, i proroki ego predveŝaût za denʹgi, a meždu tem opiraûtsâ na Gospoda, govorâ: «ne sredi li nas Gospodʹ? ne postignet nas beda!»"],[3,12,"Посему за вас Сион распахан будет как поле, и Иерусалим сделается грудою развалин, и гора дома сего будет лесистым холмом.","Posemu za vas Sion raspahan budet kak pole, i Ierusalim sdelaetsâ grudoû razvalin, i gora doma sego budet lesistym holmom."],[4,1,"И будет в последние дни: гора дома Господня поставлена будет во главу гор и возвысится над холмами, и потекут к ней народы.","I budet v poslednie dni: gora doma Gospodnâ postavlena budet vo glavu gor i vozvysitsâ nad holmami, i potekut k nej narody."],[4,2,"И пойдут многие народы и скажут: придите, и взойдем на гору Господню и в дом Бога Иаковлева, и Он научит нас путям Своим, и будем ходить по стезям Его, ибо от Сиона выйдет закон и слово Господне – из Иерусалима.","I pojdut mnogie narody i skažut: pridite, i vzojdem na goru Gospodnû i v dom Boga Iakovleva, i On naučit nas putâm Svoim, i budem hoditʹ po stezâm Ego, ibo ot Siona vyjdet zakon i slovo Gospodne – iz Ierusalima."],[4,3,"И будет Он судить многие народы и обличит многие племена в отдаленных странах; и перекуют они мечи свои на орала и копья свои – на серпы; не поднимет народ на народ меча, и не будут более учиться воевать.","I budet On suditʹ mnogie narody i obličit mnogie plemena v otdalennyh stranah; i perekuût oni meči svoi na orala i kopʹâ svoi – na serpy; ne podnimet narod na narod meča, i ne budut bolee učitʹsâ voevatʹ."],[4,4,"Но каждый будет сидеть под своею виноградною лозою и под своею смоковницею, и никто не будет устрашать их, ибо уста Господа Саваофа изрекли это.","No každyj budet sidetʹ pod svoeû vinogradnoû lozoû i pod svoeû smokovniceû, i nikto ne budet ustrašatʹ ih, ibo usta Gospoda Savaofa izrekli éto."],[4,5,"Ибо все народы ходят, каждый во имя своего бога; а мы будем ходить во имя Господа Бога нашего во веки веков.","Ibo vse narody hodât, každyj vo imâ svoego boga; a my budem hoditʹ vo imâ Gospoda Boga našego vo veki vekov."],[4,6,"В тот день, говорит Господь, соберу хромлющее и совокуплю разогнанное и тех, на кого Я навел бедствие.","V tot denʹ, govorit Gospodʹ, soberu hromlûŝee i sovokuplû razognannoe i teh, na kogo Â navel bedstvie."],[4,7,"И сделаю хромлющее остатком и далеко рассеянное сильным народом, и Господь будет царствовать над ними на горе Сионе отныне и до века.","I sdelaû hromlûŝee ostatkom i daleko rasseânnoe silʹnym narodom, i Gospodʹ budet carstvovatʹ nad nimi na gore Sione otnyne i do veka."],[4,8,"А ты, башня стада, холм дщери Сиона! к тебе придет и возвратится прежнее владычество, царство – к дщерям Иерусалима.","A ty, bašnâ stada, holm dŝeri Siona! k tebe pridet i vozvratitsâ prežnee vladyčestvo, carstvo – k dŝerâm Ierusalima."],[4,9,"Для чего же ты ныне так громко вопиешь? Разве нет у тебя царя? Или не стало у тебя советника, что тебя схватили муки, как рождающую?","Dlâ čego že ty nyne tak gromko vopiešʹ? Razve net u tebâ carâ? Ili ne stalo u tebâ sovetnika, čto tebâ shvatili muki, kak roždaûŝuû?"],[4,10,"Страдай и мучься болями, дщерь Сиона, как рождающая, ибо ныне ты выйдешь из города и будешь жить в поле, и дойдешь до Вавилона: там будешь спасена, там искупит тебя Господь от руки врагов твоих.","Stradaj i mučʹsâ bolâmi, dŝerʹ Siona, kak roždaûŝaâ, ibo nyne ty vyjdešʹ iz goroda i budešʹ žitʹ v pole, i dojdešʹ do Vavilona: tam budešʹ spasena, tam iskupit tebâ Gospodʹ ot ruki vragov tvoih."],[4,11,"А теперь собрались против тебя многие народы и говорят: «да будет она осквернена, и да наглядится око наше на Сион!»","A teperʹ sobralisʹ protiv tebâ mnogie narody i govorât: «da budet ona oskvernena, i da naglâditsâ oko naše na Sion!»"],[4,12,"Но они не знают мыслей Господних и не разумеют совета Его, что Он собрал их как снопы на гумно.","No oni ne znaût myslej Gospodnih i ne razumeût soveta Ego, čto On sobral ih kak snopy na gumno."],[4,13,"Встань и молоти, дщерь Сиона, ибо Я сделаю рог твой железным и копыта твои сделаю медными, и сокрушишь многие народы, и посвятишь Господу стяжания их и богатства их Владыке всей земли.","Vstanʹ i moloti, dŝerʹ Siona, ibo Â sdelaû rog tvoj železnym i kopyta tvoi sdelaû mednymi, i sokrušišʹ mnogie narody, i posvâtišʹ Gospodu stâžaniâ ih i bogatstva ih Vladyke vsej zemli."],[5,1,"Теперь ополчись, дщерь полчищ; обложили нас осадою, тростью будут бить по ланите судью Израилева.","Teperʹ opolčisʹ, dŝerʹ polčiŝ; obložili nas osadoû, trostʹû budut bitʹ po lanite sudʹû Izraileva."],[5,2,"И ты, Вифлеем-Ефрафа, мал ли ты между тысячами Иудиными? из тебя произойдет Мне Тот, Который должен быть Владыкою в Израиле и Которого происхождение из начала, от дней вечных.","I ty, Vifleem-Efrafa, mal li ty meždu tysâčami Iudinymi? iz tebâ proizojdet Mne Tot, Kotoryj dolžen bytʹ Vladykoû v Izraile i Kotorogo proishoždenie iz načala, ot dnej večnyh."],[5,3,"Посему Он оставит их до времени, доколе не родит имеющая родить; тогда возвратятся к сынам Израиля и оставшиеся братья их.","Posemu On ostavit ih do vremeni, dokole ne rodit imeûŝaâ roditʹ; togda vozvratâtsâ k synam Izrailâ i ostavšiesâ bratʹâ ih."],[5,4,"И станет Он, и будет пасти в силе Господней, в величии имени Господа Бога Своего, и они будут жить безопасно, ибо тогда Он будет великим до краев земли.","I stanet On, i budet pasti v sile Gospodnej, v veličii imeni Gospoda Boga Svoego, i oni budut žitʹ bezopasno, ibo togda On budet velikim do kraev zemli."],[5,5,"И будет Он – мир. Когда Ассур придет в нашу землю и вступит в наши чертоги, мы выставим против него семь пастырей и восемь князей.","I budet On – mir. Kogda Assur pridet v našu zemlû i vstupit v naši čertogi, my vystavim protiv nego semʹ pastyrej i vosemʹ knâzej."],[5,6,"И будут они пасти землю Ассура мечом и землю Немврода в самых воротах ее, и Он-то избавит от Ассура, когда тот придет в землю нашу и когда вступит в пределы наши.","I budut oni pasti zemlû Assura mečom i zemlû Nemvroda v samyh vorotah ee, i On-to izbavit ot Assura, kogda tot pridet v zemlû našu i kogda vstupit v predely naši."],[5,7,"И будет остаток Иакова среди многих народов как роса от Господа, как ливень на траве, и он не будет зависеть от человека и полагаться на сынов Адамовых.","I budet ostatok Iakova sredi mnogih narodov kak rosa ot Gospoda, kak livenʹ na trave, i on ne budet zavisetʹ ot čeloveka i polagatʹsâ na synov Adamovyh."],[5,8,"И будет остаток Иакова между народами, среди многих племен, как лев среди зверей лесных, как скимен среди стада овец, который, когда выступит, то попирает и терзает, и никто не спасет от него.","I budet ostatok Iakova meždu narodami, sredi mnogih plemen, kak lev sredi zverej lesnyh, kak skimen sredi stada ovec, kotoryj, kogda vystupit, to popiraet i terzaet, i nikto ne spaset ot nego."],[5,9,"Поднимется рука твоя над врагами твоими, и все неприятели твои будут истреблены.","Podnimetsâ ruka tvoâ nad vragami tvoimi, i vse nepriâteli tvoi budut istrebleny."],[5,10,"И будет в тот день, говорит Господь: истреблю коней твоих из среды твоей и уничтожу колесницы твои,","I budet v tot denʹ, govorit Gospodʹ: istreblû konej tvoih iz sredy tvoej i uničtožu kolesnicy tvoi,"],[5,11,"истреблю города в земле твоей и разрушу все укрепления твои,","istreblû goroda v zemle tvoej i razrušu vse ukrepleniâ tvoi,"],[5,12,"исторгну чародеяния из руки твоей, и гадающих по облакам не будет у тебя;","istorgnu čarodeâniâ iz ruki tvoej, i gadaûŝih po oblakam ne budet u tebâ;"],[5,13,"истреблю истуканов твоих и кумиров из среды твоей, и не будешь более поклоняться изделиям рук твоих.","istreblû istukanov tvoih i kumirov iz sredy tvoej, i ne budešʹ bolee poklonâtʹsâ izdeliâm ruk tvoih."],[5,14,"Искореню из среды твоей священные рощи твои и разорю города твои.","Iskorenû iz sredy tvoej svâŝennye roŝi tvoi i razorû goroda tvoi."],[5,15,"И совершу в гневе и негодовании мщение над народами, которые будут непослушны.","I soveršu v gneve i negodovanii mŝenie nad narodami, kotorye budut neposlušny."],[6,1,"Слушайте, что говорит Господь: встань, судись перед горами, и холмы да слышат голос твой!","Slušajte, čto govorit Gospodʹ: vstanʹ, sudisʹ pered gorami, i holmy da slyšat golos tvoj!"],[6,2,"Слушайте, горы, суд Господень, и вы, твердые основы земли: ибо у Господа суд с народом Своим, и с Израилем Он состязуется.","Slušajte, gory, sud Gospodenʹ, i vy, tverdye osnovy zemli: ibo u Gospoda sud s narodom Svoim, i s Izrailem On sostâzuetsâ."],[6,3,"Народ Мой! что сделал Я тебе и чем отягощал тебя? отвечай Мне.","Narod Moj! čto sdelal Â tebe i čem otâgoŝal tebâ? otvečaj Mne."],[6,4,"Я вывел тебя из земли Египетской и искупил тебя из дома рабства, и послал перед тобою Моисея, Аарона и Мариам.","Â vyvel tebâ iz zemli Egipetskoj i iskupil tebâ iz doma rabstva, i poslal pered toboû Moiseâ, Aarona i Mariam."],[6,5,"Народ Мой! вспомни, что замышлял Валак, царь Моавитский, и что отвечал ему Валаам, сын Веоров, и что происходило от Ситтима до Галгал, чтобы познать тебе праведные действия Господни.","Narod Moj! vspomni, čto zamyšlâl Valak, carʹ Moavitskij, i čto otvečal emu Valaam, syn Veorov, i čto proishodilo ot Sittima do Galgal, čtoby poznatʹ tebe pravednye dejstviâ Gospodni."],[6,6,"«С чем предстать мне пред Господом, преклониться пред Богом небесным? Предстать ли пред Ним со всесожжениями, с тельцами однолетними?","«S čem predstatʹ mne pred Gospodom, preklonitʹsâ pred Bogom nebesnym? Predstatʹ li pred Nim so vsesožženiâmi, s telʹcami odnoletnimi?"],[6,7,"Но можно ли угодить Господу тысячами овнов или неисчетными потоками елея? Разве дам Ему первенца моего за преступление мое и плод чрева моего – за грех души моей?»","No možno li ugoditʹ Gospodu tysâčami ovnov ili neisčetnymi potokami eleâ? Razve dam Emu pervenca moego za prestuplenie moe i plod čreva moego – za greh duši moej?»"],[6,8,"О, человек! сказано тебе, что – добро и чего требует от тебя Господь: действовать справедливо, любить дела милосердия и смиренномудренно ходить пред Богом твоим.","O, čelovek! skazano tebe, čto – dobro i čego trebuet ot tebâ Gospodʹ: dejstvovatʹ spravedlivo, lûbitʹ dela miloserdiâ i smirennomudrenno hoditʹ pred Bogom tvoim."],[6,9,"Глас Господа взывает к городу, и мудрость благоговеет пред именем Твоим: слушайте жезл и Того, Кто поставил его.","Glas Gospoda vzyvaet k gorodu, i mudrostʹ blagogoveet pred imenem Tvoim: slušajte žezl i Togo, Kto postavil ego."],[6,10,"Не находятся ли и теперь в доме нечестивого сокровища нечестия и уменьшенная мера, отвратительная?","Ne nahodâtsâ li i teperʹ v dome nečestivogo sokroviŝa nečestiâ i umenʹšennaâ mera, otvratitelʹnaâ?"],[6,11,"Могу ли я быть чистым с весами неверными и с обманчивыми гирями в суме?","Mogu li â bytʹ čistym s vesami nevernymi i s obmančivymi girâmi v sume?"],[6,12,"Так как богачи его исполнены неправды, и жители его говорят ложь, и язык их есть обман в устах их,","Tak kak bogači ego ispolneny nepravdy, i žiteli ego govorât ložʹ, i âzyk ih estʹ obman v ustah ih,"],[6,13,"то и Я неисцельно поражу тебя опустошением за грехи твои.","to i Â neiscelʹno poražu tebâ opustošeniem za grehi tvoi."],[6,14,"Ты будешь есть и не будешь сыт; пустота будет внутри тебя; будешь хранить, но не убережешь, а что сбережешь, то предам мечу.","Ty budešʹ estʹ i ne budešʹ syt; pustota budet vnutri tebâ; budešʹ hranitʹ, no ne uberežešʹ, a čto sberežešʹ, to predam meču."],[6,15,"Будешь сеять, а жать не будешь; будешь давить оливки и не будешь умащаться елеем; выжмешь виноградный сок, а вина пить не будешь.","Budešʹ seâtʹ, a žatʹ ne budešʹ; budešʹ davitʹ olivki i ne budešʹ umaŝatʹsâ eleem; vyžmešʹ vinogradnyj sok, a vina pitʹ ne budešʹ."],[6,16,"Сохранились у вас обычаи Амврия и все дела дома Ахавова, и вы поступаете по советам их; и предам Я тебя опустошению и жителей твоих посмеянию, и вы понесете поругание народа Моего.","Sohranilisʹ u vas obyčai Amvriâ i vse dela doma Ahavova, i vy postupaete po sovetam ih; i predam Â tebâ opustošeniû i žitelej tvoih posmeâniû, i vy ponesete poruganie naroda Moego."],[7,1,"Горе мне! ибо со мною теперь – как по собрании летних плодов, как по уборке винограда: ни одной ягоды для еды, ни спелого плода, которого желает душа моя.","Gore mne! ibo so mnoû teperʹ – kak po sobranii letnih plodov, kak po uborke vinograda: ni odnoj âgody dlâ edy, ni spelogo ploda, kotorogo želaet duša moâ."],[7,2,"Не стало милосердых на земле, нет правдивых между людьми; все строят ковы, чтобы проливать кровь; каждый ставит брату своему сеть.","Ne stalo miloserdyh na zemle, net pravdivyh meždu lûdʹmi; vse stroât kovy, čtoby prolivatʹ krovʹ; každyj stavit bratu svoemu setʹ."],[7,3,"Руки их обращены к тому, чтобы уметь делать зло; начальник требует подарков, и судья судит за взятки, а вельможи высказывают злые хотения души своей и извращают дело.","Ruki ih obraŝeny k tomu, čtoby umetʹ delatʹ zlo; načalʹnik trebuet podarkov, i sudʹâ sudit za vzâtki, a velʹmoži vyskazyvaût zlye hoteniâ duši svoej i izvraŝaût delo."],[7,4,"Лучший из них – как терн, и справедливый – хуже колючей изгороди, день провозвестников Твоих, посещение Твое наступает; ныне постигнет их смятение.","Lučšij iz nih – kak tern, i spravedlivyj – huže kolûčej izgorodi, denʹ provozvestnikov Tvoih, poseŝenie Tvoe nastupaet; nyne postignet ih smâtenie."],[7,5,"Не верьте другу, не полагайтесь на приятеля; от лежащей на лоне твоем стереги двери уст твоих.","Ne verʹte drugu, ne polagajtesʹ na priâtelâ; ot ležaŝej na lone tvoem steregi dveri ust tvoih."],[7,6,"Ибо сын позорит отца, дочь восстает против матери, невестка – против свекрови своей; враги человеку – домашние его.","Ibo syn pozorit otca, dočʹ vosstaet protiv materi, nevestka – protiv svekrovi svoej; vragi čeloveku – domašnie ego."],[7,7,"А я буду взирать на Господа, уповать на Бога спасения моего: Бог мой услышит меня.","A â budu vziratʹ na Gospoda, upovatʹ na Boga spaseniâ moego: Bog moj uslyšit menâ."],[7,8,"Не радуйся ради меня, неприятельница моя! хотя я упал, но встану; хотя я во мраке, но Господь – свет для меня.","Ne radujsâ radi menâ, nepriâtelʹnica moâ! hotâ â upal, no vstanu; hotâ â vo mrake, no Gospodʹ – svet dlâ menâ."],[7,9,"Гнев Господень я буду нести, потому что согрешил пред Ним, доколе Он не решит дела моего и не совершит суда надо мною; тогда Он выведет меня на свет, и я увижу правду Его.","Gnev Gospodenʹ â budu nesti, potomu čto sogrešil pred Nim, dokole On ne rešit dela moego i ne soveršit suda nado mnoû; togda On vyvedet menâ na svet, i â uvižu pravdu Ego."],[7,10,"И увидит это неприятельница моя, и стыд покроет ее, говорившую мне: «где Господь Бог твой?» Насмотрятся на нее глаза мои, как она будет попираема подобно грязи на улицах.","I uvidit éto nepriâtelʹnica moâ, i styd pokroet ee, govorivšuû mne: «gde Gospodʹ Bog tvoj?» Nasmotrâtsâ na nee glaza moi, kak ona budet popiraema podobno grâzi na ulicah."],[7,11,"В день сооружения стен твоих, в этот день отдалится определение.","V denʹ sooruženiâ sten tvoih, v étot denʹ otdalitsâ opredelenie."],[7,12,"В тот день придут к тебе из Ассирии и городов Египетских, и от Египта до реки Евфрата, и от моря до моря, и от горы до горы.","V tot denʹ pridut k tebe iz Assirii i gorodov Egipetskih, i ot Egipta do reki Evfrata, i ot morâ do morâ, i ot gory do gory."],[7,13,"А земля та будет пустынею за вину жителей ее, за плоды деяний их.","A zemlâ ta budet pustyneû za vinu žitelej ee, za plody deânij ih."],[7,14,"Паси народ Твой жезлом Твоим, овец наследия Твоего, обитающих уединенно в лесу среди Кармила; да пасутся они на Васане и Галааде, как во дни древние!","Pasi narod Tvoj žezlom Tvoim, ovec naslediâ Tvoego, obitaûŝih uedinenno v lesu sredi Karmila; da pasutsâ oni na Vasane i Galaade, kak vo dni drevnie!"],[7,15,"Как во дни исхода твоего из земли Египетской, явлю ему дивные дела.","Kak vo dni ishoda tvoego iz zemli Egipetskoj, âvlû emu divnye dela."],[7,16,"Увидят это народы и устыдятся при всем могуществе своем; положат руку на уста, уши их сделаются глухими;","Uvidât éto narody i ustydâtsâ pri vsem moguŝestve svoem; položat ruku na usta, uši ih sdelaûtsâ gluhimi;"],[7,17,"будут лизать прах как змея, как черви земные выползут они из укреплений своих; устрашатся Господа Бога нашего и убоятся Тебя.","budut lizatʹ prah kak zmeâ, kak červi zemnye vypolzut oni iz ukreplenij svoih; ustrašatsâ Gospoda Boga našego i uboâtsâ Tebâ."],[7,18,"Кто Бог, как Ты, прощающий беззаконие и не вменяющий преступления остатку наследия Твоего? не вечно гневается Он, потому что любит миловать.","Kto Bog, kak Ty, proŝaûŝij bezzakonie i ne vmenâûŝij prestupleniâ ostatku naslediâ Tvoego? ne večno gnevaetsâ On, potomu čto lûbit milovatʹ."],[7,19,"Он опять умилосердится над нами, изгладит беззакония наши. Ты ввергнешь в пучину морскую все грехи наши.","On opâtʹ umiloserditsâ nad nami, izgladit bezzakoniâ naši. Ty vvergnešʹ v pučinu morskuû vse grehi naši."],[7,20,"Ты явишь верность Иакову, милость Аврааму, которую с клятвою обещал отцам нашим от дней первых.","Ty âvišʹ vernostʹ Iakovu, milostʹ Avraamu, kotoruû s klâtvoû obeŝal otcam našim ot dnej pervyh."]],"cmn-cuv-hant":[[1,1,"當 猶大王 約坦、 亞哈斯、 希西家在位的時候， 摩利沙人 彌迦得耶和華的默示，論 撒馬利亞和 耶路撒冷。","dāng yóu dà wáng yuē tǎn, yà hā sī, xī xī jiā zài wèi de shí hòu， mó lì shā rén mí jiā dé yé hé huá de mò shì， lùn sā mǎ lì yà hé yé lù sā lěng."],[1,2,"萬民哪，你們都要聽！ 地和其上所有的，也都要側耳而聽！ 主耶和華從他的聖殿 要見證你們的不是。","wàn mín nǎ， nǐ men dōu yào tīng！ de hé qí shàng suǒ yǒu de， yě dōu yào cè ěr ér tīng！ zhǔ yé hé huá cóng tā de shèng diàn yào jiàn zhèng nǐ men de bù shì."],[1,3,"看哪，耶和華出了他的居所， 降臨步行地的高處。","kàn nǎ， yé hé huá chū le tā de jū suǒ， jiàng lín bù xíng de de gāo chù."],[1,4,"眾山在他以下必消化， 諸谷必崩裂， 如蠟化在火中， 如水沖下山坡。","zhòng shān zài tā yǐ xià bì xiāo huà， zhū gǔ bì bēng liè， rú là huà zài huǒ zhōng， rú shuǐ chōng xià shān pō."],[1,5,"這都因 雅各的罪過， 以色列家的罪惡。 雅各的罪過在哪裏呢？ 豈不是在 撒馬利亞嗎？ 猶大的邱壇在哪裏呢？ 豈不是在 耶路撒冷嗎？","zhè dōu yīn yǎ gè de zuì guò， yǐ sè liè jiā de zuì è. yǎ gè de zuì guò zài nǎ lǐ ne？ qǐ bù shì zài sā mǎ lì yà ma？ yóu dà de qiū tán zài nǎ lǐ ne？ qǐ bù shì zài yé lù sā lěng ma？"],[1,6,"所以我必使 撒馬利亞變為田野的亂堆， 又作為種葡萄之處； 也必將她的石頭倒在谷中， 露出根基來。","suǒ yǐ wǒ bì shǐ sā mǎ lì yà biàn wèi tián yě de luàn duī， yòu zuò wèi zhǒng pú táo zhī chù； yě bì jiāng tā de shí tóu dào zài gǔ zhōng， lù chū gēn jī lái."],[1,7,"她一切雕刻的偶像必被打碎； 她所得的財物必被火燒； 所有的偶像我必毀滅； 因為是從妓女雇價所聚來的， 後必歸為妓女的雇價。","tā yī qiè diāo kè de ǒu xiàng bì bèi dǎ suì； tā suǒ dé de cái wù bì bèi huǒ shāo； suǒ yǒu de ǒu xiàng wǒ bì huǐ miè； yīn wèi shì cóng jì nǚ gù jià suǒ jù lái de， hòu bì guī wèi jì nǚ de gù jià."],[1,8,"先知說：因此我必大聲哀號， 赤腳露體而行； 又要呼號如野狗， 哀鳴如鴕鳥。","xiān zhī shuō： yīn cǐ wǒ bì dà shēng āi hào， chì jiǎo lù tǐ ér xíng； yòu yào hū hào rú yě gǒu， āi míng rú tuó niǎo."],[1,9,"因為 撒馬利亞的傷痕無法醫治， 延及 猶大和 耶路撒冷我民的城門。","yīn wèi sā mǎ lì yà de shāng hén wú fǎ yī zhì， yán jí yóu dà hé yé lù sā lěng wǒ mín de chéng mén."],[1,10,"不要在 迦特報告這事， 總不要哭泣； 我在 伯‧亞弗拉滾於灰塵之中。","bù yào zài jiā tè bào gào zhè shì， zǒng bù yào kū qì； wǒ zài bó‧yà fú lā gǔn yú huī chén zhī zhōng."],[1,11,"沙斐的居民哪，你們要赤身蒙羞過去。 撒南的居民不敢出來。 伯‧以薛人的哀哭使你們無處可站。","shā fěi de jū mín nǎ， nǐ men yào chì shēn méng xiū guò qù. sā nán de jū mín bù gǎn chū lái. bó‧yǐ xuē rén de āi kū shǐ nǐ men wú chù kě zhàn."],[1,12,"瑪律的居民心甚憂急，切望得好處， 因為災禍從耶和華那裏臨到 耶路撒冷的城門。","mǎ lǜ de jū mín xīn shèn yōu jí， qiè wàng dé hǎo chù， yīn wèi zāi huò cóng yé hé huá nà lǐ lín dào yé lù sā lěng de chéng mén."],[1,13,"拉吉的居民哪，要用快馬套車； 錫安民的罪由你而起； 以色列人的罪過在你那裏顯出。","lā jí de jū mín nǎ， yào yòng kuài mǎ tào chē； xī ān mín de zuì yóu nǐ ér qǐ； yǐ sè liè rén de zuì guò zài nǐ nà lǐ xiǎn chū."],[1,14,"猶大啊，你要將禮物送給 摩利設‧迦特。 亞革悉的眾族必用詭詐待 以色列諸王。","yóu dà a， nǐ yào jiāng lǐ wù sòng gěi mó lì shè‧jiā tè. yà gé xī de zhòng zú bì yòng guǐ zhà dài yǐ sè liè zhū wáng."],[1,15,"瑪利沙的居民哪， 我必使那奪取你的來到你這裏； 以色列的尊貴人必到 亞杜蘭。","mǎ lì shā de jū mín nǎ， wǒ bì shǐ nà duó qǔ nǐ de lái dào nǐ zhè lǐ； yǐ sè liè de zūn guì rén bì dào yà dù lán."],[1,16,"猶大啊，要為你所喜愛的兒女剪除你的頭髮， 使頭光禿，要大大地光禿，如同禿鷹， 因為他們都被擄去離開你。","yóu dà a， yào wèi nǐ suǒ xǐ ài de ér nǚ jiǎn chú nǐ de tóu fà， shǐ tóu guāng tū， yào dà dà de guāng tū， rú tóng tū yīng， yīn wèi tā men dōu bèi lǔ qù lí kāi nǐ."],[2,1,"禍哉，那些在床上圖謀罪孽、造作奸惡的！ 天一發亮，因手有能力就行出來了。","huò zāi， nà xiē zài chuáng shàng tú móu zuì niè, zào zuò jiān è de！ tiān yī fā liàng， yīn shǒu yǒu néng lì jiù xíng chū lái le."],[2,2,"他們貪圖田地就佔據， 貪圖房屋便奪取； 他們欺壓人，霸佔房屋和產業。","tā men tān tú tián de jiù zhàn jù， tān tú fáng wū biàn duó qǔ； tā men qī yā rén， bà zhàn fáng wū hé chǎn yè."],[2,3,"所以耶和華如此說： 我籌劃災禍降與這族； 這禍在你們的頸項上不能解脫； 你們也不能昂首而行， 因為這時勢是惡的。","suǒ yǐ yé hé huá rú cǐ shuō： wǒ chóu huà zāi huò jiàng yǔ zhè zú； zhè huò zài nǐ men de jǐng xiàng shàng bù néng jiě tuō； nǐ men yě bù néng áng shǒu ér xíng， yīn wèi zhè shí shì shì è de."],[2,4,"到那日，必有人向你們提起悲慘的哀歌， 譏刺說：我們全然敗落了！ 耶和華將我們的分轉歸別人， 何竟使這分離開我們？ 他將我們的田地分給悖逆的人。","dào nà rì， bì yǒu rén xiàng nǐ men tí qǐ bēi cǎn de āi gē， jī cì shuō： wǒ men quán rán bài luò le！ yé hé huá jiāng wǒ men de fēn zhuǎn guī bié rén， hé jìng shǐ zhè fēn lí kāi wǒ men？ tā jiāng wǒ men de tián de fēn gěi bèi nì de rén."],[2,5,"所以在耶和華的會中， 你必沒有人拈鬮拉準繩。","suǒ yǐ zài yé hé huá de huì zhōng， nǐ bì méi yǒu rén niān jiū lā zhǔn shéng."],[2,6,"他們說：你們不可說預言； 不可向這些人說預言， 不住地羞辱 我們。","tā men shuō： nǐ men bù kě shuō yù yán； bù kě xiàng zhè xiē rén shuō yù yán， bù zhù de xiū rǔ wǒ men."],[2,7,"雅各家啊，豈可說耶和華的心不忍耐嗎？ 這些事是他所行的嗎？ 我－ 耶和華的言語豈不是與行動正直的人有益嗎？","yǎ gè jiā a， qǐ kě shuō yé hé huá de xīn bù rěn nài ma？ zhè xiē shì shì tā suǒ xíng de ma？ wǒ－ yé hé huá de yán yǔ qǐ bù shì yǔ xíng dòng zhèng zhí de rén yǒu yì ma？"],[2,8,"然而，近來我的民興起如仇敵， 從那些安然經過不願打仗之人身上剝去外衣。","rán ér， jìn lái wǒ de mín xìng qǐ rú chóu dí， cóng nà xiē ān rán jīng guò bù yuàn dǎ zhàng zhī rén shēn shàng bō qù wài yī."],[2,9,"你們將我民中的婦人從安樂家中趕出， 又將我的榮耀從她們的小孩子盡行奪去。","nǐ men jiāng wǒ mín zhōng de fù rén cóng ān lè jiā zhōng gǎn chū， yòu jiāng wǒ de róng yào cóng tā men de xiǎo hái zǐ jǐn xíng duó qù."],[2,10,"你們起來去吧！ 這不是你們安息之所； 因為污穢使人毀滅， 而且大大毀滅。","nǐ men qǐ lái qù ba！ zhè bù shì nǐ men ān xī zhī suǒ； yīn wèi wū huì shǐ rén huǐ miè， ér qiě dà dà huǐ miè."],[2,11,"若有人心存虛假，用謊言 說： 我要向你們預言得清酒和濃酒。 那人就必作這民的先知。","ruò yǒu rén xīn cún xū jiǎ， yòng huǎng yán shuō： wǒ yào xiàng nǐ men yù yán dé qīng jiǔ hé nóng jiǔ. nà rén jiù bì zuò zhè mín de xiān zhī."],[2,12,"雅各家啊，我必要聚集你們， 必要招聚 以色列剩下的人， 安置在一處，如 波斯拉的羊， 又如草場上的羊群； 因為人數 眾多就必大大喧嘩。","yǎ gè jiā a， wǒ bì yào jù jí nǐ men， bì yào zhāo jù yǐ sè liè shèng xià de rén， ān zhì zài yī chù， rú bō sī lā de yáng， yòu rú cǎo chǎng shàng de yáng qún； yīn wèi rén shù zhòng duō jiù bì dà dà xuān huā."],[2,13,"開路的在他們前面上去； 他們直闖過城門，從城門出去。 他們的王在前面行； 耶和華引導他們。","kāi lù de zài tā men qián miàn shàng qù； tā men zhí chuǎng guò chéng mén， cóng chéng mén chū qù. tā men de wáng zài qián miàn xíng； yé hé huá yǐn dǎo tā men."],[3,1,"我說： 雅各的首領， 以色列家的官長啊，你們要聽！ 你們不當知道公平嗎？","wǒ shuō： yǎ gè de shǒu lǐng， yǐ sè liè jiā de guān zhǎng a， nǐ men yào tīng！ nǐ men bù dāng zhī dào gōng píng ma？"],[3,2,"你們惡善好惡， 從人身上剝皮， 從人骨頭上剔肉，","nǐ men è shàn hǎo è， cóng rén shēn shàng bō pí， cóng rén gǔ tóu shàng tī ròu，"],[3,3,"吃我民的肉， 剝他們的皮， 打折他們的骨頭， 分成塊子像要下鍋， 又像釜中的肉。","chī wǒ mín de ròu， bō tā men de pí， dǎ zhé tā men de gǔ tóu， fēn chéng kuài zǐ xiàng yào xià guō， yòu xiàng fǔ zhōng de ròu."],[3,4,"到了 遭災的時候， 這些人必哀求耶和華， 他卻不應允他們。 那時他必照他們所行的惡事向他們掩面。","dào le zāo zāi de shí hòu， zhè xiē rén bì āi qiú yé hé huá， tā què bù yīng yǔn tā men. nà shí tā bì zhào tā men suǒ xíng de è shì xiàng tā men yǎn miàn."],[3,5,"論到使我民走差路的先知－ 他們牙齒有所嚼的， 他們就呼喊說：平安了！ 凡不供給他們吃的， 他們就預備攻擊他－ 耶和華如此說：","lùn dào shǐ wǒ mín zǒu chà lù de xiān zhī－ tā men yá chǐ yǒu suǒ jué de， tā men jiù hū hǎn shuō： píng ān le！ fán bù gōng gěi tā men chī de， tā men jiù yù bèi gōng jī tā－ yé hé huá rú cǐ shuō："],[3,6,"你們必遭遇黑夜，以致不見異象； 又必遭遇幽暗，以致不能占卜。 日頭必向你們沉落， 白晝變為黑暗。","nǐ men bì zāo yù hēi yè， yǐ zhì bù jiàn yì xiàng； yòu bì zāo yù yōu àn， yǐ zhì bù néng zhàn bo. rì tóu bì xiàng nǐ men chén luò， bái zhòu biàn wèi hēi àn."],[3,7,"先見必抱愧， 占卜的必蒙羞， 都必摀着嘴唇， 因為神不應允他們。","xiān jiàn bì bào kuì， zhàn bo de bì méng xiū， dōu bì wǔ zhe zuǐ chún， yīn wèi shén bù yīng yǔn tā men."],[3,8,"至於我，我藉耶和華的靈， 滿有力量、公平、才能， 可以向 雅各說明他的過犯， 向 以色列指出他的罪惡。","zhì yú wǒ， wǒ jí yé hé huá de líng， mǎn yǒu lì liàng, gōng píng, cái néng， kě yǐ xiàng yǎ gè shuō míng tā de guò fàn， xiàng yǐ sè liè zhǐ chū tā de zuì è."],[3,9,"雅各家的首領、 以色列家的官長啊， 當聽我的話！ 你們厭惡公平， 在一切事上屈枉正直；","yǎ gè jiā de shǒu lǐng, yǐ sè liè jiā de guān zhǎng a， dāng tīng wǒ de huà！ nǐ men yàn è gōng píng， zài yī qiè shì shàng qū wǎng zhèng zhí；"],[3,10,"以人血建立 錫安， 以罪孽建造 耶路撒冷。","yǐ rén xuè jiàn lì xī ān， yǐ zuì niè jiàn zào yé lù sā lěng."],[3,11,"首領為賄賂行審判； 祭司為雇價施訓誨； 先知為銀錢行占卜。 他們卻倚賴耶和華，說： 耶和華不是在我們中間嗎？ 災禍必不臨到我們。","shǒu lǐng wèi huì lù xíng shěn pàn； jì sī wèi gù jià shī xùn huì； xiān zhī wèi yín qián xíng zhàn bo. tā men què yǐ lài yé hé huá， shuō： yé hé huá bù shì zài wǒ men zhōng jiān ma？ zāi huò bì bù lín dào wǒ men."],[3,12,"所以因你們的緣故， 錫安必被耕種像一塊田， 耶路撒冷必變為亂堆； 這殿的山必像叢林的高處。","suǒ yǐ yīn nǐ men de yuán gù， xī ān bì bèi gēng zhǒng xiàng yī kuài tián， yé lù sā lěng bì biàn wèi luàn duī； zhè diàn de shān bì xiàng cóng lín de gāo chù."],[4,1,"末後的日子， 耶和華殿的山必堅立， 超乎諸山，高舉過於萬嶺； 萬民都要流歸這山。","mò hòu de rì zǐ， yé hé huá diàn de shān bì jiān lì， chāo hū zhū shān， gāo jǔ guò yú wàn lǐng； wàn mín dōu yào liú guī zhè shān."],[4,2,"必有許多國的民前往，說： 來吧，我們登耶和華的山， 奔 雅各神的殿。 主必將他的道教訓我們； 我們也要行他的路。 因為訓誨必出於 錫安； 耶和華的言語必出於 耶路撒冷。","bì yǒu xǔ duō guó de mín qián wǎng， shuō： lái ba， wǒ men dēng yé hé huá de shān， bēn yǎ gè shén de diàn. zhǔ bì jiāng tā de dào jiào xùn wǒ men； wǒ men yě yào xíng tā de lù. yīn wèi xùn huì bì chū yú xī ān； yé hé huá de yán yǔ bì chū yú yé lù sā lěng."],[4,3,"他必在多國的民中施行審判， 為遠方強盛的國斷定是非。 他們要將刀打成誆頭， 把槍打成鐮刀。 這國不舉刀攻擊那國； 他們也不再學習戰事。","tā bì zài duō guó de mín zhōng shī xíng shěn pàn， wèi yuǎn fāng qiáng shèng de guó duàn dìng shì fēi. tā men yào jiāng dāo dǎ chéng kuāng tóu， bǎ qiāng dǎ chéng lián dāo. zhè guó bù jǔ dāo gōng jī nà guó； tā men yě bù zài xué xí zhàn shì."],[4,4,"人人都要坐在自己葡萄樹下 和無花果樹下，無人驚嚇。 這是萬軍之耶和華親口說的。","rén rén dōu yào zuò zài zì jǐ pú táo shù xià hé wú huā guǒ shù xià， wú rén jīng xià. zhè shì wàn jūn zhī yé hé huá qīn kǒu shuō de."],[4,5,"萬民各奉己神的名而行； 我們卻永永遠遠奉耶和華－我們神的名而行。","wàn mín gè fèng jǐ shén de míng ér xíng； wǒ men què yǒng yǒng yuǎn yuǎn fèng yé hé huá－wǒ men shén de míng ér xíng."],[4,6,"耶和華說：到那日， 我必聚集瘸腿的， 招聚被趕出的和我所懲治的。","yé hé huá shuō： dào nà rì， wǒ bì jù jí qué tuǐ de， zhāo jù bèi gǎn chū de hé wǒ suǒ chéng zhì de."],[4,7,"我必使瘸腿的為餘剩之民， 使趕到遠方的為強盛之民。 耶和華要在 錫安山作王治理他們， 從今直到永遠。","wǒ bì shǐ qué tuǐ de wèi yú shèng zhī mín， shǐ gǎn dào yuǎn fāng de wèi qiáng shèng zhī mín. yé hé huá yào zài xī ān shān zuò wáng zhì lǐ tā men， cóng jīn zhí dào yǒng yuǎn."],[4,8,"你這羊群的高臺、 錫安城的山哪， 從前的權柄－ 就是 耶路撒冷民的國權－ 必歸與你。","nǐ zhè yáng qún de gāo tái, xī ān chéng de shān nǎ， cóng qián de quán bǐng－ jiù shì yé lù sā lěng mín de guó quán－ bì guī yǔ nǐ."],[4,9,"現在你為何大聲哭號呢？ 疼痛抓住你彷彿產難的婦人， 是因你中間沒有君王嗎？ 你的謀士滅亡了嗎？","xiàn zài nǐ wèi hé dà shēng kū hào ne？ téng tòng zhuā zhù nǐ páng fú chǎn nán de fù rén， shì yīn nǐ zhōng jiān méi yǒu jūn wáng ma？ nǐ de móu shì miè wáng le ma？"],[4,10,"錫安的民哪， 你要疼痛劬勞，彷彿產難的婦人； 因為你必從城裏出來， 住在田野，到 巴比倫去。 在那裏要蒙解救； 在那裏耶和華必救贖你脫離仇敵的手。","xī ān de mín nǎ， nǐ yào téng tòng qú láo， páng fú chǎn nán de fù rén； yīn wèi nǐ bì cóng chéng lǐ chū lái， zhù zài tián yě， dào bā bǐ lún qù. zài nà lǐ yào méng jiě jiù； zài nà lǐ yé hé huá bì jiù shú nǐ tuō lí chóu dí de shǒu."],[4,11,"現在有許多國的民聚集攻擊你，說： 願 錫安被玷污！ 願我們親眼見她 遭報！","xiàn zài yǒu xǔ duō guó de mín jù jí gōng jī nǐ， shuō： yuàn xī ān bèi diàn wū！ yuàn wǒ men qīn yǎn jiàn tā zāo bào！"],[4,12,"他們卻不知道耶和華的意念， 也不明白他的籌劃。 他聚集他們，好像把禾捆聚到禾場一樣。","tā men què bù zhī dào yé hé huá de yì niàn， yě bù míng bái tā de chóu huà. tā jù jí tā men， hǎo xiàng bǎ hé kǔn jù dào hé chǎng yī yàng."],[4,13,"錫安的民哪，起來踹穀吧！ 我必使你的角成為鐵， 使你的蹄成為銅。 你必打碎多國的民， 將他們的財獻與耶和華， 將他們的貨獻與普天下的主。","xī ān de mín nǎ， qǐ lái chuài gǔ ba！ wǒ bì shǐ nǐ de jiǎo chéng wèi tiě， shǐ nǐ de tí chéng wèi tóng. nǐ bì dǎ suì duō guó de mín， jiāng tā men de cái xiàn yǔ yé hé huá， jiāng tā men de huò xiàn yǔ pǔ tiān xià de zhǔ."],[5,1,"成群的民哪，現在你要聚集成隊； 因為仇敵圍攻我們， 要用杖擊打 以色列審判者的臉。","chéng qún de mín nǎ， xiàn zài nǐ yào jù jí chéng duì； yīn wèi chóu dí wéi gōng wǒ men， yào yòng zhàng jī dǎ yǐ sè liè shěn pàn zhě de liǎn."],[5,2,"伯利恆的 以法他啊， 你在 猶大諸城中為小， 將來必有一位從你那裏出來， 在 以色列中為我作掌權的； 他的根源從亙古，從太初就有。","bó lì héng de yǐ fǎ tā a， nǐ zài yóu dà zhū chéng zhōng wèi xiǎo， jiāng lái bì yǒu yī wèi cóng nǐ nà lǐ chū lái， zài yǐ sè liè zhōng wèi wǒ zuò zhǎng quán de； tā de gēn yuán cóng gèn gǔ， cóng tài chū jiù yǒu."],[5,3,"耶和華必將 以色列人交付 敵人， 直等那生產的婦人生下子來。 那時掌權者其餘的弟兄 必歸到 以色列人那裏。","yé hé huá bì jiāng yǐ sè liè rén jiāo fù dí rén， zhí děng nà shēng chǎn de fù rén shēng xià zǐ lái. nà shí zhǎng quán zhě qí yú de dì xiōng bì guī dào yǐ sè liè rén nà lǐ."],[5,4,"他必起來，倚靠耶和華的大能， 並耶和華－他神之名的威嚴， 牧養 他的羊群。 他們要 安然居住； 因為他必日見尊大，直到地極。","tā bì qǐ lái， yǐ kào yé hé huá de dà néng， bìng yé hé huá－tā shén zhī míng de wēi yán， mù yǎng tā de yáng qún. tā men yào ān rán jū zhù； yīn wèi tā bì rì jiàn zūn dà， zhí dào de jí."],[5,5,"這位必作 我們的平安。 當 亞述人進入我們的地境， 踐踏宮殿的時候， 我們就立起七個牧者， 八個首領攻擊他。","zhè wèi bì zuò wǒ men de píng ān. dāng yà shù rén jìn rù wǒ men de de jìng， jiàn tà gōng diàn de shí hòu， wǒ men jiù lì qǐ qī gè mù zhě， bā gè shǒu lǐng gōng jī tā."],[5,6,"他們必用刀劍毀壞 亞述地 和 寧錄地的關口。 亞述人進入我們的地境踐踏的時候， 他必拯救我們。","tā men bì yòng dāo jiàn huǐ huài yà shù de hé níng lù de de guān kǒu. yà shù rén jìn rù wǒ men de de jìng jiàn tà de shí hòu， tā bì zhěng jiù wǒ men."],[5,7,"雅各餘剩的人必在多國的民中， 如從耶和華那裏降下的露水， 又如甘霖降在草上； 不仗賴人 力，也不等候世人 之功。","yǎ gè yú shèng de rén bì zài duō guó de mín zhōng， rú cóng yé hé huá nà lǐ jiàng xià de lù shuǐ， yòu rú gān lín jiàng zài cǎo shàng； bù zhàng lài rén lì， yě bù děng hòu shì rén zhī gōng."],[5,8,"雅各餘剩的人必在多國多民中， 如林間百獸中的獅子， 又如少壯獅子在羊群中。 他若經過就必踐踏撕裂， 無人搭救。","yǎ gè yú shèng de rén bì zài duō guó duō mín zhōng， rú lín jiān bǎi shòu zhōng de shī zǐ， yòu rú shǎo zhuàng shī zǐ zài yáng qún zhōng. tā ruò jīng guò jiù bì jiàn tà sī liè， wú rén dā jiù."],[5,9,"願你的手舉起，高過敵人！ 願你的仇敵都被剪除！","yuàn nǐ de shǒu jǔ qǐ， gāo guò dí rén！ yuàn nǐ de chóu dí dōu bèi jiǎn chú！"],[5,10,"耶和華說：到那日， 我必從你中間剪除馬匹， 毀壞車輛，","yé hé huá shuō： dào nà rì， wǒ bì cóng nǐ zhōng jiān jiǎn chú mǎ pǐ， huǐ huài chē liàng，"],[5,11,"也必從你國中除滅城邑， 拆毀一切的保障，","yě bì cóng nǐ guó zhōng chú miè chéng yì， chāi huǐ yī qiè de bǎo zhàng，"],[5,12,"又必除掉你手中的邪術； 你那裏也不再有占卜的。","yòu bì chú diào nǐ shǒu zhōng de xié shù； nǐ nà lǐ yě bù zài yǒu zhàn bo de."],[5,13,"我必從你中間除滅雕刻的偶像和柱像， 你就不再跪拜自己手所造的。","wǒ bì cóng nǐ zhōng jiān chú miè diāo kè de ǒu xiàng hé zhù xiàng， nǐ jiù bù zài guì bài zì jǐ shǒu suǒ zào de."],[5,14,"我必從你中間拔出木偶， 又毀滅你的城邑。","wǒ bì cóng nǐ zhōng jiān bá chū mù ǒu， yòu huǐ miè nǐ de chéng yì."],[5,15,"我也必在怒氣和忿怒中向那不聽從的列國施報。","wǒ yě bì zài nù qì hé fèn nù zhōng xiàng nà bù tīng cóng de liè guó shī bào."],[6,1,"以色列人哪，當聽耶和華的話！ 要起來向山嶺爭辯， 使岡陵聽你的話。","yǐ sè liè rén nǎ， dāng tīng yé hé huá de huà！ yào qǐ lái xiàng shān lǐng zhēng biàn， shǐ gāng líng tīng nǐ de huà."],[6,2,"山嶺和地永久的根基啊， 要聽耶和華爭辯的話！ 因為耶和華要與他的百姓爭辯， 與 以色列爭論。","shān lǐng hé de yǒng jiǔ de gēn jī a， yào tīng yé hé huá zhēng biàn de huà！ yīn wèi yé hé huá yào yǔ tā de bǎi xìng zhēng biàn， yǔ yǐ sè liè zhēng lùn."],[6,3,"我的百姓啊，我向你做了甚麼呢？ 我在甚麼事上使你厭煩？ 你可以對我證明。","wǒ de bǎi xìng a， wǒ xiàng nǐ zuò le shèn me ne？ wǒ zài shèn me shì shàng shǐ nǐ yàn fán？ nǐ kě yǐ duì wǒ zhèng míng."],[6,4,"我曾將你從 埃及地領出來， 從作奴僕之家救贖你； 我也差遣 摩西、 亞倫，和 米利暗在你前面行。","wǒ céng jiāng nǐ cóng āi jí de lǐng chū lái， cóng zuò nú pú zhī jiā jiù shú nǐ； wǒ yě chà qiǎn mó xī, yà lún， hé mǐ lì àn zài nǐ qián miàn xíng."],[6,5,"我的百姓啊，你們當追念 摩押王 巴勒所設的謀 和 比珥的兒子 巴蘭回答他的話， 並你們從 什亭到 吉甲 所遇見的事， 好使你們知道耶和華公義的作為。","wǒ de bǎi xìng a， nǐ men dāng zhuī niàn mó yā wáng bā lēi suǒ shè de móu hé bǐ ěr de ér zǐ bā lán huí dá tā de huà， bìng nǐ men cóng shén tíng dào jí jiǎ suǒ yù jiàn de shì， hǎo shǐ nǐ men zhī dào yé hé huá gōng yì de zuò wèi."],[6,6,"我朝見耶和華， 在至高神面前跪拜，當獻上甚麼呢？ 豈可獻一歲的牛犢為燔祭嗎？","wǒ cháo jiàn yé hé huá， zài zhì gāo shén miàn qián guì bài， dāng xiàn shàng shèn me ne？ qǐ kě xiàn yī suì de niú dú wèi fán jì ma？"],[6,7,"耶和華豈喜悅千千的公羊， 或是萬萬的油河嗎？ 我豈可為自己的罪過獻我的長子嗎？ 為心中的罪惡獻我身所生的嗎？","yé hé huá qǐ xǐ yuè qiān qiān de gōng yáng， huò shì wàn wàn de yóu hé ma？ wǒ qǐ kě wèi zì jǐ de zuì guò xiàn wǒ de zhǎng zǐ ma？ wèi xīn zhōng de zuì è xiàn wǒ shēn suǒ shēng de ma？"],[6,8,"世人哪，耶和華已指示你何為善。 他向你所要的是甚麼呢？ 只要你行公義，好憐憫， 存謙卑的心，與你的神同行。","shì rén nǎ， yé hé huá yǐ zhǐ shì nǐ hé wèi shàn. tā xiàng nǐ suǒ yào de shì shèn me ne？ zhǐ yào nǐ xíng gōng yì， hǎo lián mǐn， cún qiān bēi de xīn， yǔ nǐ de shén tóng xíng."],[6,9,"耶和華向這城呼叫， 智慧人必敬畏他的名。 你們當聽是誰派定刑杖的懲罰。","yé hé huá xiàng zhè chéng hū jiào， zhì huì rén bì jìng wèi tā de míng. nǐ men dāng tīng shì shuí pài dìng xíng zhàng de chéng fá."],[6,10,"惡人家中不仍有非義之財 和可惡的小升斗嗎？","è rén jiā zhōng bù réng yǒu fēi yì zhī cái hé kě è de xiǎo shēng dòu ma？"],[6,11,"我若用不公道的天平和囊中詭詐的法碼， 豈可算為清潔呢？","wǒ ruò yòng bù gōng dào de tiān píng hé náng zhōng guǐ zhà de fǎ mǎ， qǐ kě suàn wèi qīng jié ne？"],[6,12,"城裏的富戶滿行強暴； 其中的居民也說謊言， 口中的舌頭是詭詐的。","chéng lǐ de fù hù mǎn xíng qiáng bào； qí zhōng de jū mín yě shuō huǎng yán， kǒu zhōng de shé tóu shì guǐ zhà de."],[6,13,"因此，我擊打你， 使你的傷痕甚重， 使你因你的罪惡荒涼。","yīn cǐ， wǒ jī dǎ nǐ， shǐ nǐ de shāng hén shèn zhòng， shǐ nǐ yīn nǐ de zuì è huāng liáng."],[6,14,"你要吃，卻吃不飽； 你的虛弱必顯在你中間。 你必挪去，卻不得救護； 所救護的，我必交給刀劍。","nǐ yào chī， què chī bù bǎo； nǐ de xū ruò bì xiǎn zài nǐ zhōng jiān. nǐ bì nuó qù， què bù dé jiù hù； suǒ jiù hù de， wǒ bì jiāo gěi dāo jiàn."],[6,15,"你必撒種，卻不得收割； 踹橄欖，卻不得油抹身； 踹葡萄，卻不得酒喝。","nǐ bì sā zhǒng， què bù dé shōu gē； chuài gǎn lǎn， què bù dé yóu mǒ shēn； chuài pú táo， què bù dé jiǔ hē."],[6,16,"因為你守 暗利的惡規， 行 亞哈家一切所行的， 順從他們的計謀； 因此，我必使你荒涼， 使你的居民令人嗤笑， 你們也必擔當我民的羞辱。","yīn wèi nǐ shǒu àn lì de è guī， xíng yà hā jiā yī qiè suǒ xíng de， shùn cóng tā men de jì móu； yīn cǐ， wǒ bì shǐ nǐ huāng liáng， shǐ nǐ de jū mín lìng rén chī xiào， nǐ men yě bì dān dāng wǒ mín de xiū rǔ."],[7,1,"哀哉！我好像夏天的果子已被收盡， 又像摘了葡萄所剩下的， 沒有一掛可吃的； 我心羨慕初熟的無花果。","āi zāi！ wǒ hǎo xiàng xià tiān de guǒ zǐ yǐ bèi shōu jǐn， yòu xiàng zhāi le pú táo suǒ shèng xià de， méi yǒu yī guà kě chī de； wǒ xīn xiàn mù chū shú de wú huā guǒ."],[7,2,"地上虔誠人滅盡； 世間沒有正直人； 各人埋伏，要殺人流血， 都用網羅獵取弟兄。","de shàng qián chéng rén miè jǐn； shì jiān méi yǒu zhèng zhí rén； gè rén mái fú， yào shā rén liú xuè， dōu yòng wǎng luó liè qǔ dì xiōng."],[7,3,"他們雙手作惡； 君王徇情面，審判官要賄賂； 位分大的吐出惡意， 都彼此結聯行惡。","tā men shuāng shǒu zuò è； jūn wáng xùn qíng miàn， shěn pàn guān yào huì lù； wèi fēn dà de tǔ chū è yì， dōu bǐ cǐ jié lián xíng è."],[7,4,"他們最好的，不過是蒺藜； 最正直的，不過是荊棘籬笆。 你守望者 說，降罰的日子已經來到。 他們必擾亂不安。","tā men zuì hǎo de， bù guò shì jí lí； zuì zhèng zhí de， bù guò shì jīng jí lí bā. nǐ shǒu wàng zhě shuō， jiàng fá de rì zǐ yǐ jīng lái dào. tā men bì rǎo luàn bù ān."],[7,5,"不要倚賴鄰舍； 不要信靠密友。 要守住你的口； 不要向你懷中的妻提說。","bù yào yǐ lài lín shě； bù yào xìn kào mì yǒu. yào shǒu zhù nǐ de kǒu； bù yào xiàng nǐ huái zhōng de qī tí shuō."],[7,6,"因為，兒子藐視父親； 女兒抗拒母親； 媳婦抗拒婆婆； 人的仇敵就是自己家裏的人。","yīn wèi， ér zǐ miǎo shì fù qīn； nǚ ér kàng jù mǔ qīn； xí fù kàng jù pó pó； rén de chóu dí jiù shì zì jǐ jiā lǐ de rén."],[7,7,"至於我，我要仰望耶和華， 要等候那救我的神； 我的神必應允我。","zhì yú wǒ， wǒ yào yǎng wàng yé hé huá， yào děng hòu nà jiù wǒ de shén； wǒ de shén bì yīng yǔn wǒ."],[7,8,"我的仇敵啊，不要向我誇耀。 我雖跌倒，卻要起來； 我雖坐在黑暗裏， 耶和華卻作我的光。","wǒ de chóu dí a， bù yào xiàng wǒ kuā yào. wǒ suī diē dào， què yào qǐ lái； wǒ suī zuò zài hēi àn lǐ， yé hé huá què zuò wǒ de guāng."],[7,9,"我要忍受耶和華的惱怒； 因我得罪了他， 直等他為我辨屈，為我伸冤。 他必領我到光明中； 我必得見他的公義。","wǒ yào rěn shòu yé hé huá de nǎo nù； yīn wǒ dé zuì le tā， zhí děng tā wèi wǒ biàn qū， wèi wǒ shēn yuān. tā bì lǐng wǒ dào guāng míng zhōng； wǒ bì dé jiàn tā de gōng yì."],[7,10,"那時我的仇敵， 就是曾對我說「耶和華－你神在哪裏」的， 他一看見這事就被羞愧遮蓋。 我必親眼見他 遭報； 他必被踐踏，如同街上的泥土。","nà shí wǒ de chóu dí， jiù shì céng duì wǒ shuō‘yé hé huá－nǐ shén zài nǎ lǐ’ de， tā yī kàn jiàn zhè shì jiù bèi xiū kuì zhē gài. wǒ bì qīn yǎn jiàn tā zāo bào； tā bì bèi jiàn tà， rú tóng jiē shàng de ní tǔ."],[7,11,"以色列啊，日子必到， 你的牆垣必重修； 到那日，你的境界必開展。","yǐ sè liè a， rì zǐ bì dào， nǐ de qiáng yuán bì zhòng xiū； dào nà rì， nǐ de jìng jiè bì kāi zhǎn."],[7,12,"當那日，人必從 亞述， 從 埃及的城邑， 從 埃及到大河， 從這海到那海， 從這山到那山， 都歸到你這裏。","dāng nà rì， rén bì cóng yà shù， cóng āi jí de chéng yì， cóng āi jí dào dà hé， cóng zhè hǎi dào nà hǎi， cóng zhè shān dào nà shān， dōu guī dào nǐ zhè lǐ."],[7,13,"然而，這地因居民的緣故， 又因他們行事的結果，必然荒涼。","rán ér， zhè de yīn jū mín de yuán gù， yòu yīn tā men xíng shì de jié guǒ， bì rán huāng liáng."],[7,14,"求 耶和華在 迦密山的樹林中， 用你的杖牧放你獨居的民， 就是你產業的羊群。 求你容他們在 巴珊和 基列得食物，像古時一樣。","qiú yé hé huá zài jiā mì shān de shù lín zhōng， yòng nǐ de zhàng mù fàng nǐ dú jū de mín， jiù shì nǐ chǎn yè de yáng qún. qiú nǐ róng tā men zài bā shān hé jī liè dé shí wù， xiàng gǔ shí yī yàng."],[7,15,"耶和華說： 我要把奇事顯給他們看， 好像出 埃及地的時候一樣。","yé hé huá shuō： wǒ yào bǎ qí shì xiǎn gěi tā men kàn， hǎo xiàng chū āi jí de de shí hòu yī yàng."],[7,16,"列國看見這事就必為自己的勢力慚愧； 他們必用手摀口，掩耳不聽。","liè guó kàn jiàn zhè shì jiù bì wèi zì jǐ de shì lì cán kuì； tā men bì yòng shǒu wǔ kǒu， yǎn ěr bù tīng."],[7,17,"他們必舔土如蛇， 又如土中腹行的物， 戰戰兢兢地出他們的營寨。 他們必戰懼投降耶和華， 也必因我們的神而懼怕。","tā men bì tiǎn tǔ rú shé， yòu rú tǔ zhōng fù xíng de wù， zhàn zhàn jīng jīng de chū tā men de yíng zhài. tā men bì zhàn jù tóu jiàng yé hé huá， yě bì yīn wǒ men de shén ér jù pà."],[7,18,"神啊，有何神像你，赦免罪孽， 饒恕你產業之餘民的罪過， 不永遠懷怒，喜愛施恩？","shén a， yǒu hé shén xiàng nǐ， shè miǎn zuì niè， ráo shù nǐ chǎn yè zhī yú mín de zuì guò， bù yǒng yuǎn huái nù， xǐ ài shī ēn？"],[7,19,"必再憐憫我們， 將我們的罪孽踏在腳下， 又將我們的一切罪投於深海。","bì zài lián mǐn wǒ men， jiāng wǒ men de zuì niè tà zài jiǎo xià， yòu jiāng wǒ men de yī qiè zuì tóu yú shēn hǎi."],[7,20,"你必按古時起誓應許我們列祖的話， 向 雅各發誠實， 向 亞伯拉罕施慈愛。","nǐ bì àn gǔ shí qǐ shì yīng xǔ wǒ men liè zǔ de huà， xiàng yǎ gè fā chéng shí， xiàng yà bó lā hǎn shī cí ài."]],"arb-vandyck":[[1,1,"قَوْلُ ٱلرَّبِّ ٱلَّذِي صَارَ إِلَى مِيخَا ٱلْمُورَشْتِيِّ فِي أَيَّامِ يُوثَامَ وَآحَازَ وَحَزَقِيَّا مُلُوكِ يَهُوذَا، ٱلَّذِي رَآهُ عَلَى ٱلسَّامِرَةِ وَأُورُشَلِيمَ:","qaẘlu ٱlrãbĩ ٱlãdẖī ṣāra ại̹lay̱ mīkẖā ٱl̊mūrasẖ̊tīĩ fī ạảyãạmi yūtẖāma wā̂ḥāza waḥazaqīãạ mulūki yahūdẖā, ٱlãdẖī rā̂hu ʿalay̱ ٱlsãạmiraẗi wāủwrusẖalīma:"],[1,2,"اِسْمَعُوا أَيُّهَا ٱلشُّعُوبُ جَمِيعُكُمْ. أَصْغِي أَيَّتُهَا ٱلْأَرْضُ وَمِلْؤُهَا. وَلْيَكُنِ ٱلسَّيِّدُ ٱلرَّبُّ شَاهِدًا عَلَيْكُمُ، ٱلسَّيِّدُ مِنْ هَيْكَلِ قُدْسِهِ.","ạis̊maʿūạ ạảyũhā ٱlsẖũʿūbu jamīʿukum̊. ạảṣ̊gẖī ạảyãtuhā ٱl̊ạảr̊ḍu wamil̊wủhā. wal̊yakuni ٱlsãyĩdu ٱlrãbũ sẖāhidaⁿạ ʿalaẙkumu, ٱlsãyĩdu min̊ haẙkali qud̊sihi."],[1,3,"فَإِنَّهُ هُوَذَا ٱلرَّبُّ يَخْرُجُ مِنْ مَكَانِهِ وَيَنْزِلُ وَيَمْشِي عَلَى شَوَامِخِ ٱلْأَرْضِ،","fāi̹nãhu hūadẖā ٱlrãbũ yakẖ̊ruju min̊ makānihi wayan̊zilu wayam̊sẖī ʿalay̱ sẖawāmikẖi ٱl̊ạảr̊ḍi,"],[1,4,"فَتَذُوبُ ٱلْجِبَالُ تَحْتَهُ، وَتَنْشَقُّ ٱلْوِدْيَانُ كَٱلشَّمْعِ قُدَّامَ ٱلنَّارِ. كَٱلْمَاءِ ٱلْمُنْصَبِّ فِي مُنْحَدَرٍ.","fatadẖūbu ٱl̊jibālu taḥ̊tahu, watan̊sẖaqũ ٱl̊wid̊yānu kaٱlsẖãm̊ʿi qudãạma ٱlnãạri. kaٱl̊māʾi ٱl̊mun̊ṣabĩ fī mun̊ḥadariⁿ."],[1,5,"كُلُّ هَذَا مِنْ أَجْلِ إِثْمِ يَعْقُوبَ، وَمِنْ أَجْلِ خَطِيَّةِ بَيْتِ إِسْرَائِيلَ. مَا هُوَ ذَنْبُ يَعْقُوبَ؟ أَلَيْسَ هُوَ ٱلسَّامِرَةَ؟ وَمَا هِيَ مُرْتَفَعَاتُ يَهُوذَا؟ أَلَيْسَتْ هِيَ أُورُشَلِيمَ؟","kulũ hadẖā min̊ ạảj̊li ại̹tẖ̊mi yaʿ̊qūba, wamin̊ ạảj̊li kẖaṭīãẗi baẙti ại̹s̊rāyỉyla. mā hūa dẖan̊bu yaʿ̊qūba? ạảlaẙsa hūa ٱlsãạmiraẗa? wamā hīa mur̊tafaʿātu yahūdẖā? ạảlaẙsat̊ hīa ạủwrusẖalīma?"],[1,6,"«فَأَجْعَلُ ٱلسَّامِرَةَ خَرِبَةً فِي ٱلْبَرِّيَّةِ، مَغَارِسَ لِلْكُرُومِ، وَأُلْقِي حِجَارَتَهَا إِلَى ٱلْوَادِي، وَأَكْشِفُ أُسُسَهَا.","«fāảj̊ʿalu ٱlsãạmiraẗa kẖaribaẗaⁿ fī ٱl̊barĩyãẗi, magẖārisa lil̊kurūmi, wāủl̊qī ḥijāratahā ại̹lay̱ ٱl̊wādī, wāảk̊sẖifu ạủsusahā."],[1,7,"وَجَمِيعُ تَمَاثِيلِهَا ٱلْمَنْحُوتَةِ تُحَطَّمُ، وَكُلُّ أَعْقَارِهَا تُحْرَقُ بِٱلنَّارِ، وَجَمِيعُ أَصْنَامِهَا أَجْعَلُهَا خَرَابًا، لِأَنَّهَا مِنْ عُقْرِ ٱلزَّانِيَةِ جَمَعَتْهَا وَإِلَى عُقْرِ ٱلزَّانِيَةِ تَعُودُ».","wajamīʿu tamātẖīlihā ٱl̊man̊ḥūtaẗi tuḥaṭãmu, wakulũ ạảʿ̊qārihā tuḥ̊raqu biٱlnãạri, wajamīʿu ạảṣ̊nāmihā ạảj̊ʿaluhā kẖarābaⁿạ, liạảnãhā min̊ ʿuq̊ri ٱlzãạnīaẗi jamaʿat̊hā wāi̹lay̱ ʿuq̊ri ٱlzãạnīaẗi taʿūdu»."],[1,8,"مِنْ أَجْلِ ذَلِكَ أَنُوحُ وَأُوَلْوِلُ. أَمْشِي حَافِيًا وَعُرْيَانًا. أَصْنَعُ نَحِيبًا كَبَنَاتِ آوَى، وَنَوْحًا كَرِعَالِ ٱلنَّعَامِ.","min̊ ạảj̊li dẖalika ạảnūḥu wāủwal̊wilu. ạảm̊sẖī ḥāfīaⁿạ waʿur̊yānaⁿạ. ạảṣ̊naʿu naḥībaⁿạ kabanāti ậway̱, wanaẘḥaⁿạ kariʿāli ٱlnãʿāmi."],[1,9,"لِأَنَّ جِرَاحَاتِهَا عَدِيمَةُ ٱلشِّفَاءِ، لِأَنَّهَا قَدْ أَتَتْ إِلَى يَهُوذَا، وَصَلَتْ إِلَى بَابِ شَعْبِي إِلَى أُورُشَلِيمَ.","liạảnã jirāḥātihā ʿadīmaẗu ٱlsẖĩfāʾi, liạảnãhā qad̊ ạảtat̊ ại̹lay̱ yahūdẖā, waṣalat̊ ại̹lay̱ bābi sẖaʿ̊bī ại̹lay̱ ạủwrusẖalīma."],[1,10,"لَا تُخْبِرُوا فِي جَتَّ، لَا تَبْكُوا فِي عَكَّاءَ. تَمَرَّغِي فِي ٱلتُّرَابِ فِي بَيْتِ عَفْرَةَ.","lā tukẖ̊birūạ fī jatã, lā tab̊kūạ fī ʿakãạʾa. tamarãgẖī fī ٱltũrābi fī baẙti ʿaf̊raẗa."],[1,11,"اُعْبُرِي يَا سَاكِنَةَ شَافِيرَ عُرْيَانَةً وَخَجِلَةً. ٱلسَّاكِنَةُ فِي صَانَانَ لَا تَخْرُجُ. نَوْحُ بَيْتِ هَأَيْصِلَ يَأْخُذُ عِنْدَكُمْ مَقَامَهُ،","ạuʿ̊burī yā sākinaẗa sẖāfīra ʿur̊yānaẗaⁿ wakẖajilaẗaⁿ. ٱlsãạkinaẗu fī ṣānāna lā takẖ̊ruju. naẘḥu baẙti hāảẙṣila yā̊̉kẖudẖu ʿin̊dakum̊ maqāmahu,"],[1,12,"لِأَنَّ ٱلسَّاكِنَةَ فِي مَارُوثَ ٱغْتَمَّتْ لِأَجْلِ خَيْرَاتِهَا، لِأَنَّ شَرًّا قَدْ نَزَلَ مِنْ عِنْدِ ٱلرَّبِّ إِلَى بَابِ أُورُشَلِيمَ.","liạảnã ٱlsãạkinaẗa fī mārūtẖa ٱgẖ̊tamãt̊ liạảj̊li kẖaẙrātihā, liạảnã sẖaraⁿ̃ạ qad̊ nazala min̊ ʿin̊di ٱlrãbĩ ại̹lay̱ bābi ạủwrusẖalīma."],[1,13,"شُدِّي ٱلْمَرْكَبَةَ بِٱلْجَوَادِ يَا سَاكِنَةَ لَاخِيشَ، هِيَ أَوَّلُ خَطِيَّةٍ لِٱبْنَةِ صِهْيَوْنَ، لِأَنَّهُ فِيكِ وُجِدَتْ ذُنُوبُ إِسْرَائِيلَ.","sẖudĩy ٱl̊mar̊kabaẗa biٱl̊jawādi yā sākinaẗa lākẖīsẖa, hīa ạảwãlu kẖaṭīãẗiⁿ liٱb̊naẗi ṣih̊yaẘna, liạảnãhu fīki wujidat̊ dẖunūbu ại̹s̊rāyỉyla."],[1,14,"لِذَلِكَ تُعْطِينَ إِطْلَاقًا لِمُورَشَةِ جَتَّ. تَصِيرُ بُيُوتُ أَكْزِيبَ كَاذِبَةً لِمُلُوكِ إِسْرَائِيلَ.","lidẖalika tuʿ̊ṭīna ại̹ṭ̊lāqaⁿạ limūrasẖaẗi jatã. taṣīru buyūtu ạảk̊zība kādẖibaẗaⁿ limulūki ại̹s̊rāyỉyla."],[1,15,"آتِي إِلَيْكِ أَيْضًا بِٱلْوَارِثِ يَا سَاكِنَةَ مَرِيشَةَ. يَأْتِي إِلَى عَدُلَّامَ مَجْدُ إِسْرَائِيلَ.","ậtī ại̹laẙki ạảẙḍaⁿạ biٱl̊wāritẖi yā sākinaẗa marīsẖaẗa. yā̊̉tī ại̹lay̱ ʿadulãạma maj̊du ại̹s̊rāyỉyla."],[1,16,"كُونِي قَرْعَاءَ وَجُزِّي مِنْ أَجْلِ بَنِي تَنَعُّمِكِ. وَسِّعِي قَرْعَتَكِ كَٱلنَّسْرِ، لِأَنَّهُمْ قَدِ ٱنْتَفَوْا عَنْكِ.","kūnī qar̊ʿāʾa wajuzĩy min̊ ạảj̊li banī tanaʿũmiki. wasĩʿī qar̊ʿataki kaٱlnãs̊ri, liạảnãhum̊ qadi ٱn̊tafaẘạ ʿan̊ki."],[2,1,"وَيْلٌ لِلْمُفْتَكِرِينَ بِٱلْبُطْلِ، وَٱلصَّانِعِينَ ٱلشَّرَّ عَلَى مَضَاجِعِهِمْ! فِي نُورِ ٱلصَّبَاحِ يَفْعَلُونَهُ لِأَنَّهُ فِي قُدْرَةِ يَدِهِمْ.","waẙluⁿ lil̊muf̊takirīna biٱl̊buṭ̊li, waٱlṣãạniʿīna ٱlsẖãrã ʿalay̱ maḍājiʿihim̊! fī nūri ٱlṣãbāḥi yaf̊ʿalūnahu liạảnãhu fī qud̊raẗi yadihim̊."],[2,2,"فَإِنَّهُمْ يَشْتَهُونَ ٱلْحُقُولَ وَيَغْتَصِبُونَهَا، وَٱلْبُيُوتَ وَيَأْخُذُونَهَا، وَيَظْلِمُونَ ٱلرَّجُلَ وَبَيْتَهُ وَٱلْإِنْسَانَ وَمِيرَاثَهُ.","fāi̹nãhum̊ yasẖ̊tahūna ٱl̊ḥuqūla wayagẖ̊taṣibūnahā, waٱl̊buyūta wayā̊̉kẖudẖūnahā, wayaẓ̊limūna ٱlrãjula wabaẙtahu waٱl̊ại̹n̊sāna wamīrātẖahu."],[2,3,"لِذَلِكَ هَكَذَا قَالَ ٱلرَّبُّ: «هَأَنَذَا أَفْتَكِرُ عَلَى هَذِهِ ٱلْعَشِيرَةِ بِشَرٍّ لَا تُزِيلُونَ مِنْهُ أَعْنَاقَكُمْ، وَلَا تَسْلُكُونَ بِٱلتَّشَامُخِ لِأَنَّهُ زَمَانٌ رَدِيءٌ.","lidẖalika hakadẖā qāla ٱlrãbũ: «hāảnadẖā ạảf̊takiru ʿalay̱ hadẖihi ٱl̊ʿasẖīraẗi bisẖariⁿ̃ lā tuzīlūna min̊hu ạảʿ̊nāqakum̊, walā tas̊lukūna biٱltãsẖāmukẖi liạảnãhu zamānuⁿ radīʾuⁿ."],[2,4,"«فِي ذَلِكَ ٱلْيَوْمِ يُنْطَقُ عَلَيْكُمْ بِهَجْوٍ وَيُرْثَى بِمَرْثَاةٍ، وَيُقَالُ: خَرِبْنَا خَرَابًا. بَدَلَ نَصِيبِ شَعْبِي. كَيْفَ يَنْزِعُهُ عَنِّي؟ يَقْسِمُ لِلْمُرْتَدِّ حُقُولَنَا».","«fī dẖalika ٱl̊yaẘmi yun̊ṭaqu ʿalaẙkum̊ bihaj̊wiⁿ wayur̊tẖay̱ bimar̊tẖāẗiⁿ, wayuqālu: kẖarib̊nā kẖarābaⁿạ. badala naṣībi sẖaʿ̊bī. kaẙfa yan̊ziʿuhu ʿanĩy? yaq̊simu lil̊mur̊tadĩ ḥuqūlanā»."],[2,5,"لِذَلِكَ لَا يَكُونُ لَكَ مَنْ يُلْقِي حَبْلًا فِي نَصِيبٍ بَيْنَ جَمَاعَةِ ٱلرَّبِّ.","lidẖalika lā yakūnu laka man̊ yul̊qī ḥab̊laⁿạ fī naṣībiⁿ baẙna jamāʿaẗi ٱlrãbĩ."],[2,6,"يَتَنَبَّأُونَ قَائِلِينَ: «لَا تَتَنَبَّأُوا». لَا يَتَنَبَّأُونَ عَنْ هَذِهِ ٱلْأُمُورِ. لَا يَزُولُ ٱلْعَارُ.","yatanabãạủwna qāyỉlīna: «lā tatanabãạủwạ». lā yatanabãạủwna ʿan̊ hadẖihi ٱl̊ạủmūri. lā yazūlu ٱl̊ʿāru."],[2,7,"أَيُّهَا ٱلْمُسَمَّى بَيْتَ يَعْقُوبَ، هَلْ قَصُرَتْ رُوحُ ٱلرَّبِّ؟ أَهَذِهِ أَفْعَالُهُ؟ «أَلَيْسَتْ أَقْوَالِي صَالِحَةً نَحْوَ مَنْ يَسْلُكُ بِٱلِٱسْتِقَامَةِ؟","ạảyũhā ٱl̊musamãy̱ baẙta yaʿ̊qūba, hal̊ qaṣurat̊ rūḥu ٱlrãbĩ? ạảhadẖihi ạảf̊ʿāluhu? «ạảlaẙsat̊ ạảq̊wālī ṣāliḥaẗaⁿ naḥ̊wa man̊ yas̊luku biٱliٱs̊tiqāmaẗi?"],[2,8,"وَلَكِنْ بِٱلْأَمْسِ قَامَ شَعْبِي كَعَدُوٍّ. تَنْزِعُونَ ٱلرِّدَاءَ عَنِ ٱلثَّوْبِ مِنَ ٱلْمُجْتَازِينَ بِٱلطُّمَأْنِينَةِ، وَمِنَ ٱلرَّاجِعِينَ مِنَ ٱلْقِتَالِ.","walakin̊ biٱl̊ạảm̊si qāma sẖaʿ̊bī kaʿadūiⁿ̃. tan̊ziʿūna ٱlrĩdāʾa ʿani ٱltẖãẘbi mina ٱl̊muj̊tāzīna biٱlṭũmā̊̉nīnaẗi, wamina ٱlrãạjiʿīna mina ٱl̊qitāli."],[2,9,"تَطْرُدُونَ نِسَاءَ شَعْبِي مِنْ بَيْتِ تَنَعُّمِهِنَّ. تَأْخُذُونَ عَنْ أَطْفَالِهِنَّ زِينَتِي إِلَى ٱلْأَبَدِ.","taṭ̊rudūna nisāʾa sẖaʿ̊bī min̊ baẙti tanaʿũmihinã. tā̊̉kẖudẖūna ʿan̊ ạảṭ̊fālihinã zīnatī ại̹lay̱ ٱl̊ạảbadi."],[2,10,"«قُومُوا وَٱذْهَبُوا، لِأَنَّهُ لَيْسَتْ هَذِهِ هِيَ ٱلرَّاحَةَ. مِنْ أَجْلِ نَجَاسَةٍ تُهْلِكُ وَٱلْهَلَاكُ شَدِيدٌ.","«qūmūạ waٱdẖ̊habūạ, liạảnãhu laẙsat̊ hadẖihi hīa ٱlrãạḥaẗa. min̊ ạảj̊li najāsaẗiⁿ tuh̊liku waٱl̊halāku sẖadīduⁿ."],[2,11,"لَوْ كَانَ أَحَدٌ وَهُوَ سَالِكٌ بِٱلرِّيحِ وَٱلْكَذِبِ يَكْذِبُ قَائِلًا: أَتَنَبَّأُ لَكَ عَنِ ٱلْخَمْرِ وَٱلْمُسْكِرِ لَكَانَ هُوَ نَبِيَّ هَذَا ٱلشَّعْبِ!","laẘ kāna ạảḥaduⁿ wahūa sālikuⁿ biٱlrĩyḥi waٱl̊kadẖibi yak̊dẖibu qāyỉlaⁿạ: ạảtanabãạủ laka ʿani ٱl̊kẖam̊ri waٱl̊mus̊kiri lakāna hūa nabīã hadẖā ٱlsẖãʿ̊bi!"],[2,12,"«إِنِّي أَجْمَعُ جَمِيعَكَ يَا يَعْقُوبُ. أَضُمُّ بَقِيَّةَ إِسْرَائِيلَ. أَضَعُهُمْ مَعًا كَغَنَمِ ٱلْحَظِيرَةِ، كَقَطِيعٍ فِي وَسَطِ مَرْعَاهُ يَضِجُّ مِنَ ٱلنَّاسِ.","«ại̹nĩy ạảj̊maʿu jamīʿaka yā yaʿ̊qūbu. ạảḍumũ baqīãẗa ại̹s̊rāyỉyla. ạảḍaʿuhum̊ maʿaⁿạ kagẖanami ٱl̊ḥaẓīraẗi, kaqaṭīʿiⁿ fī wasaṭi mar̊ʿāhu yaḍijũ mina ٱlnãạsi."],[2,13,"قَدْ صَعِدَ ٱلْفَاتِكُ أَمَامَهُمْ. يَقْتَحِمُونَ وَيَعْبُرُونَ مِنَ ٱلْبَابِ، وَيَخْرُجُونَ مِنْهُ، وَيَجْتَازُ مَلِكُهُمْ أَمَامَهُمْ، وَٱلرَّبُّ فِي رَأْسِهِمْ».","qad̊ ṣaʿida ٱl̊fātiku ạảmāmahum̊. yaq̊taḥimūna wayaʿ̊burūna mina ٱl̊bābi, wayakẖ̊rujūna min̊hu, wayaj̊tāzu malikuhum̊ ạảmāmahum̊, waٱlrãbũ fī rā̊̉sihim̊»."],[3,1,"وَقُلْتُ: «ٱسْمَعُوا يَا رُؤَسَاءَ يَعْقُوبَ، وَقُضَاةَ بَيْتِ إِسْرَائِيلَ. أَلَيْسَ لَكُمْ أَنْ تَعْرِفُوا ٱلْحَقَّ؟","waqul̊tu: «ٱs̊maʿūạ yā rūảsāʾa yaʿ̊qūba, waquḍāẗa baẙti ại̹s̊rāyỉyla. ạảlaẙsa lakum̊ ạản̊ taʿ̊rifūạ ٱl̊ḥaqã?"],[3,2,"ٱلْمُبْغِضِينَ ٱلْخَيْرَ وَٱلْمُحِبِّينَ ٱلشَّرَّ، ٱلنَّازِعِينَ جُلُودَهُمْ عَنْهُمْ، وَلَحْمَهُمْ عَنْ عِظَامِهِمْ.","ٱl̊mub̊gẖiḍīna ٱl̊kẖaẙra waٱl̊muḥibĩyna ٱlsẖãrã, ٱlnãạziʿīna julūdahum̊ ʿan̊hum̊, walaḥ̊mahum̊ ʿan̊ ʿiẓāmihim̊."],[3,3,"وَٱلَّذِينَ يَأْكُلُونَ لَحْمَ شَعْبِي، وَيَكْشُطُونَ جِلْدَهُمْ عَنْهُمْ، وَيُهَشِّمُونَ عِظَامَهُمْ، وَيُشَقِّقُونَ كَمَا فِي ٱلْقِدْرِ، وَكَٱللَّحْمِ فِي وَسَطِ ٱلْمِقْلَى».","waٱlãdẖīna yā̊̉kulūna laḥ̊ma sẖaʿ̊bī, wayak̊sẖuṭūna jil̊dahum̊ ʿan̊hum̊, wayuhasẖĩmūna ʿiẓāmahum̊, wayusẖaqĩqūna kamā fī ٱl̊qid̊ri, wakaٱllãḥ̊mi fī wasaṭi ٱl̊miq̊lay̱»."],[3,4,"حِينَئِذٍ يَصْرُخُونَ إِلَى ٱلرَّبِّ فَلَا يُجِيبُهُمْ، بَلْ يَسْتُرُ وَجْهَهُ عَنْهُمْ فِي ذَلِكَ ٱلْوَقْتِ كَمَا أَسَاءُوا أَعْمَالَهُمْ.","ḥīnayỉdẖiⁿ yaṣ̊rukẖūna ại̹lay̱ ٱlrãbĩ falā yujībuhum̊, bal̊ yas̊turu waj̊hahu ʿan̊hum̊ fī dẖalika ٱl̊waq̊ti kamā ạảsāʾūạ ạảʿ̊mālahum̊."],[3,5,"هَكَذَا قَالَ ٱلرَّبُّ عَلَى ٱلْأَنْبِيَاءِ ٱلَّذِينَ يُضِلُّونَ شَعْبِي، ٱلَّذِينَ يَنْهَشُونَ بِأَسْنَانِهِمْ، وَيُنَادُونَ: «سَلَامٌ»! وَٱلَّذِي لَا يَجْعَلُ فِي أَفْوَاهِهِمْ شَيْئًا، يَفْتَحُونَ عَلَيْهِ حَرْبًا:","hakadẖā qāla ٱlrãbũ ʿalay̱ ٱl̊ạản̊bīāʾi ٱlãdẖīna yuḍilũwna sẖaʿ̊bī, ٱlãdẖīna yan̊hasẖūna biạảs̊nānihim̊, wayunādūna: «salāmuⁿ»! waٱlãdẖī lā yaj̊ʿalu fī ạảf̊wāhihim̊ sẖaẙyaⁿ̉ạ, yaf̊taḥūna ʿalaẙhi ḥar̊baⁿạ:"],[3,6,"«لِذَلِكَ تَكُونُ لَكُمْ لَيْلَةٌ بِلَا رُؤْيَا. ظَلَامٌ لَكُمْ بِدُونِ عِرَافَةٍ. وَتَغِيبُ ٱلشَّمْسُ عَنِ ٱلْأَنْبِيَاءِ، وَيُظْلِمُ عَلَيْهِمِ ٱلنَّهَارُ.","«lidẖalika takūnu lakum̊ laẙlaẗuⁿ bilā rū̊̉yā. ẓalāmuⁿ lakum̊ bidūni ʿirāfaẗiⁿ. watagẖību ٱlsẖãm̊su ʿani ٱl̊ạản̊bīāʾi, wayuẓ̊limu ʿalaẙhimi ٱlnãhāru."],[3,7,"فَيَخْزَى ٱلرَّاؤُونَ، وَيَخْجَلُ ٱلْعَرَّافُونَ، وَيُغَطُّونَ كُلُّهُمْ شَوَارِبَهُمْ، لِأَنَّهُ لَيْسَ جَوَابٌ مِنَ ٱللهِ».","fayakẖ̊zay̱ ٱlrãạwủwna, wayakẖ̊jalu ٱl̊ʿarãạfūna, wayugẖaṭũwna kulũhum̊ sẖawāribahum̊, liạảnãhu laẙsa jawābuⁿ mina ٱllhi»."],[3,8,"لَكِنَّنِي أَنَا مَلْآنٌ قُوَّةَ رُوحِ ٱلرَّبِّ وَحَقًّا وَبَأْسًا، لِأُخَبِّرَ يَعْقُوبَ بِذَنْبِهِ وَإِسْرَائِيلَ بِخَطِيَّتِهِ.","lakinãnī ạảnā mal̊ậnuⁿ qūãẗa rūḥi ٱlrãbĩ waḥaqaⁿ̃ạ wabā̊̉saⁿạ, liạủkẖabĩra yaʿ̊qūba bidẖan̊bihi wāi̹s̊rāyỉyla bikẖaṭīãtihi."],[3,9,"اِسْمَعُوا هَذَا يَا رُؤَسَاءَ بَيْتِ يَعْقُوبَ وَقُضَاةَ بَيْتِ إِسْرَائِيلَ، ٱلَّذِينَ يَكْرَهُونَ ٱلْحَقَّ وَيُعَوِّجُونَ كُلَّ مُسْتَقِيمٍ.","ạis̊maʿūạ hadẖā yā rūảsāʾa baẙti yaʿ̊qūba waquḍāẗa baẙti ại̹s̊rāyỉyla, ٱlãdẖīna yak̊rahūna ٱl̊ḥaqã wayuʿawĩjūna kulã mus̊taqīmiⁿ."],[3,10,"ٱلَّذِينَ يَبْنُونَ صِهْيَوْنَ بِٱلدِّمَاءِ، وَأُورُشَلِيمَ بِٱلظُّلْمِ.","ٱlãdẖīna yab̊nūna ṣih̊yaẘna biٱldĩmāʾi, wāủwrusẖalīma biٱlẓũl̊mi."],[3,11,"رُؤَسَاؤُهَا يَقْضُونَ بِٱلرَّشْوَةِ، وَكَهَنَتُهَا يُعَلِّمُونَ بِٱلْأُجْرَةِ، وَأَنْبِيَاؤُهَا يَعْرِفُونَ بِٱلْفِضَّةِ، وَهُمْ يَتَوَكَّلُونَ عَلَى ٱلرَّبِّ قَائِلِينَ: «أَلَيْسَ ٱلرَّبُّ فِي وَسَطِنَا؟ لَا يَأْتِي عَلَيْنَا شَرٌّ!».","rūảsāwủhā yaq̊ḍūna biٱlrãsẖ̊waẗi, wakahanatuhā yuʿalĩmūna biٱl̊ạủj̊raẗi, wāản̊bīāwủhā yaʿ̊rifūna biٱl̊fiḍãẗi, wahum̊ yatawakãlūna ʿalay̱ ٱlrãbĩ qāyỉlīna: «ạảlaẙsa ٱlrãbũ fī wasaṭinā? lā yā̊̉tī ʿalaẙnā sẖaruⁿ̃!»."],[3,12,"لِذَلِكَ بِسَبَبِكُمْ تُفْلَحُ صِهْيَوْنُ كَحَقْلٍ، وَتَصِيرُ أُورُشَلِيمُ خِرَبًا، وَجَبَلُ ٱلْبَيْتِ شَوَامِخَ وَعْرٍ.","lidẖalika bisababikum̊ tuf̊laḥu ṣih̊yaẘnu kaḥaq̊liⁿ, wataṣīru ạủwrusẖalīmu kẖirabaⁿạ, wajabalu ٱl̊baẙti sẖawāmikẖa waʿ̊riⁿ."],[4,1,"وَيَكُونُ فِي آخِرِ ٱلْأَيَّامِ أَنَّ جَبَلَ بَيْتِ ٱلرَّبِّ يَكُونُ ثَابِتًا فِي رَأْسِ ٱلْجِبَالِ، وَيَرْتَفِعُ فَوْقَ ٱلتِّلَالِ، وَتَجْرِي إِلَيْهِ شُعُوبٌ.","wayakūnu fī ậkẖiri ٱl̊ạảyãạmi ạảnã jabala baẙti ٱlrãbĩ yakūnu tẖābitaⁿạ fī rā̊̉si ٱl̊jibāli, wayar̊tafiʿu faẘqa ٱltĩlāli, wataj̊rī ại̹laẙhi sẖuʿūbuⁿ."],[4,2,"وَتَسِيرُ أُمَمٌ كَثِيرَةٌ وَيَقُولُونَ: «هَلُمَّ نَصْعَدْ إِلَى جَبَلِ ٱلرَّبِّ، وَإِلَى بَيْتِ إِلَهِ يَعْقُوبَ، فَيُعَلِّمَنَا مِنْ طُرُقِهِ، وَنَسْلُكَ فِي سُبُلِهِ». لِأَنَّهُ مِنْ صِهْيَوْنَ تَخْرُجُ ٱلشَّرِيعَةُ، وَمِنْ أُورُشَلِيمَ كَلِمَةُ ٱلرَّبِّ.","watasīru ạủmamuⁿ katẖīraẗuⁿ wayaqūlūna: «halumã naṣ̊ʿad̊ ại̹lay̱ jabali ٱlrãbĩ, wāi̹lay̱ baẙti ại̹lahi yaʿ̊qūba, fayuʿalĩmanā min̊ ṭuruqihi, wanas̊luka fī subulihi». liạảnãhu min̊ ṣih̊yaẘna takẖ̊ruju ٱlsẖãrīʿaẗu, wamin̊ ạủwrusẖalīma kalimaẗu ٱlrãbĩ."],[4,3,"فَيَقْضِي بَيْنَ شُعُوبٍ كَثِيرِينَ. يُنْصِفُ لِأُمَمٍ قَوِيَّةٍ بَعِيدَةٍ، فَيَطْبَعُونَ سُيُوفَهُمْ سِكَكًا، وَرِمَاحَهُمْ مَنَاجِلَ. لَا تَرْفَعُ أُمَّةٌ عَلَى أُمَّةٍ سَيْفًا، وَلَا يَتَعَلَّمُونَ ٱلْحَرْبَ فِي مَا بَعْدُ.","fayaq̊ḍī baẙna sẖuʿūbiⁿ katẖīrīna. yun̊ṣifu liạủmamiⁿ qawīãẗiⁿ baʿīdaẗiⁿ, fayaṭ̊baʿūna suyūfahum̊ sikakaⁿạ, warimāḥahum̊ manājila. lā tar̊faʿu ạủmãẗuⁿ ʿalay̱ ạủmãẗiⁿ saẙfaⁿạ, walā yataʿalãmūna ٱl̊ḥar̊ba fī mā baʿ̊du."],[4,4,"بَلْ يَجْلِسُونَ كُلُّ وَاحِدٍ تَحْتَ كَرْمَتِهِ وَتَحْتَ تِينَتِهِ، وَلَا يَكُونُ مَنْ يُرْعِبُ، لِأَنَّ فَمَ رَبِّ ٱلْجُنُودِ تَكَلَّمَ.","bal̊ yaj̊lisūna kulũ wāḥidiⁿ taḥ̊ta kar̊matihi wataḥ̊ta tīnatihi, walā yakūnu man̊ yur̊ʿibu, liạảnã fama rabĩ ٱl̊junūdi takalãma."],[4,5,"لِأَنَّ جَمِيعَ ٱلشُّعُوبِ يَسْلُكُونَ كُلُّ وَاحِدٍ بِٱسْمِ إِلَهِهِ، وَنَحْنُ نَسْلُكُ بِٱسْمِ ٱلرَّبِّ إِلَهِنَا إِلَى ٱلدَّهْرِ وَٱلْأَبَدِ.","liạảnã jamīʿa ٱlsẖũʿūbi yas̊lukūna kulũ wāḥidiⁿ biٱs̊mi ại̹lahihi, wanaḥ̊nu nas̊luku biٱs̊mi ٱlrãbĩ ại̹lahinā ại̹lay̱ ٱldãh̊ri waٱl̊ạảbadi."],[4,6,"«فِي ذَلِكَ ٱلْيَوْمِ، يَقُولُ ٱلرَّبُّ، أَجْمَعُ ٱلظَّالِعَةَ، وَأَضُمُّ ٱلْمَطْرُودَةَ، وَٱلَّتِي أَضْرَرْتُ بِهَا","«fī dẖalika ٱl̊yaẘmi, yaqūlu ٱlrãbũ, ạảj̊maʿu ٱlẓãạliʿaẗa, wāảḍumũ ٱl̊maṭ̊rūdaẗa, waٱlãtī ạảḍ̊rar̊tu bihā"],[4,7,"وَأَجْعَلُ ٱلظَّالِعَةَ بَقِيَّةً، وَٱلْمُقْصَاةَ أُمَّةً قَوِيَّةً، وَيَمْلِكُ ٱلرَّبُّ عَلَيْهِمْ فِي جَبَلِ صِهْيَوْنَ مِنَ ٱلْآنَ إِلَى ٱلْأَبَدِ.","wāảj̊ʿalu ٱlẓãạliʿaẗa baqīãẗaⁿ, waٱl̊muq̊ṣāẗa ạủmãẗaⁿ qawīãẗaⁿ, wayam̊liku ٱlrãbũ ʿalaẙhim̊ fī jabali ṣih̊yaẘna mina ٱl̊ậna ại̹lay̱ ٱl̊ạảbadi."],[4,8,"وَأَنْتَ يَا بُرْجَ ٱلْقَطِيعِ، أَكَمَةَ بِنْتِ صِهْيَوْنَ إِلَيْكِ يَأْتِي. وَيَجِيءُ ٱلْحُكْمُ ٱلْأَوَّلُ مُلْكُ بِنْتِ أُورُشَلِيمَ».","wāản̊ta yā bur̊ja ٱl̊qaṭīʿi, ạảkamaẗa bin̊ti ṣih̊yaẘna ại̹laẙki yā̊̉tī. wayajīʾu ٱl̊ḥuk̊mu ٱl̊ạảwãlu mul̊ku bin̊ti ạủwrusẖalīma»."],[4,9,"اَلْآنَ لِمَاذَا تَصْرُخِينَ صُرَاخًا؟ أَلَيْسَ فِيكِ مَلِكٌ، أَمْ هَلَكَ مُشِيرُكِ حَتَّى أَخَذَكِ وَجَعٌ كَٱلْوَالِدَةِ؟","ạal̊ậna limādẖā taṣ̊rukẖīna ṣurākẖaⁿạ? ạảlaẙsa fīki malikuⁿ, ạảm̊ halaka musẖīruki ḥatãy̱ ạảkẖadẖaki wajaʿuⁿ kaٱl̊wālidaẗi?"],[4,10,"تَلَوَّيِ، ٱدْفَعِي يَا بِنْتَ صِهْيَوْنَ كَٱلْوَالِدَةِ، لِأَنَّكِ ٱلْآنَ تَخْرُجِينَ مِنَ ٱلْمَدِينَةِ، وَتَسْكُنِينَ فِي ٱلْبَرِّيَّةِ، وَتَأْتِينَ إِلَى بَابِلَ. هُنَاكَ تُنْقَذِينَ. هُنَاكَ يَفْدِيكِ ٱلرَّبُّ مِنْ يَدِ أَعْدَائِكِ.","talawãyi, ٱd̊faʿī yā bin̊ta ṣih̊yaẘna kaٱl̊wālidaẗi, liạảnãki ٱl̊ậna takẖ̊rujīna mina ٱl̊madīnaẗi, watas̊kunīna fī ٱl̊barĩyãẗi, watā̊̉tīna ại̹lay̱ bābila. hunāka tun̊qadẖīna. hunāka yaf̊dīki ٱlrãbũ min̊ yadi ạảʿ̊dāyỉki."],[4,11,"وَٱلْآنَ قَدِ ٱجْتَمَعَتْ عَلَيْكِ أُمَمٌ كَثِيرَةٌ، ٱلَّذِينَ يَقُولُونَ: «لِتَتَدَنَّسْ وَلْتَتَفَرَّسْ عُيُونُنَا فِي صِهْيَوْنَ».","waٱl̊ậna qadi ٱj̊tamaʿat̊ ʿalaẙki ạủmamuⁿ katẖīraẗuⁿ, ٱlãdẖīna yaqūlūna: «litatadanãs̊ wal̊tatafarãs̊ ʿuyūnunā fī ṣih̊yaẘna»."],[4,12,"وَهُمْ لَا يَعْرِفُونَ أَفْكَارَ ٱلرَّبِّ وَلَا يَفْهَمُونَ قَصْدَهُ، إِنَّهُ قَدْ جَمَعَهُمْ كَحُزَمٍ إِلَى ٱلْبَيْدَرِ.","wahum̊ lā yaʿ̊rifūna ạảf̊kāra ٱlrãbĩ walā yaf̊hamūna qaṣ̊dahu, ại̹nãhu qad̊ jamaʿahum̊ kaḥuzamiⁿ ại̹lay̱ ٱl̊baẙdari."],[4,13,"«قُومِي وَدُوسِي يَا بِنْتَ صِهْيَوْنَ، لِأَنِّي أَجْعَلُ قَرْنَكِ حَدِيدًا، وَأَظْلَافَكِ أَجْعَلُهَا نُحَاسًا، فَتَسْحَقِينَ شُعُوبًا كَثِيرِينَ، وَأُحَرِّمُ غَنِيمَتَهُمْ لِلرَّبِّ، وَثَرْوَتَهُمْ لِسَيِّدِ كُلِّ ٱلْأَرْضِ».","«qūmī wadūsī yā bin̊ta ṣih̊yaẘna, liạảnĩy ạảj̊ʿalu qar̊naki ḥadīdaⁿạ, wāảẓ̊lāfaki ạảj̊ʿaluhā nuḥāsaⁿạ, fatas̊ḥaqīna sẖuʿūbaⁿạ katẖīrīna, wāủḥarĩmu gẖanīmatahum̊ lilrãbĩ, watẖar̊watahum̊ lisayĩdi kulĩ ٱl̊ạảr̊ḍi»."],[5,1,"اَلْآنَ تَتَجَيَّشِينَ يَا بِنْتَ ٱلْجُيُوشِ. قَدْ أَقَامَ عَلَيْنَا مِتْرَسَةً. يَضْرِبُونَ قَاضِيَ إِسْرَائِيلَ بِقَضِيبٍ عَلَى خَدِّهِ.","ạal̊ậna tatajayãsẖīna yā bin̊ta ٱl̊juyūsẖi. qad̊ ạảqāma ʿalaẙnā mit̊rasaẗaⁿ. yaḍ̊ribūna qāḍīa ại̹s̊rāyỉyla biqaḍībiⁿ ʿalay̱ kẖadĩhi."],[5,2,"«أَمَّا أَنْتِ يَا بَيْتَ لَحْمِ أَفْرَاتَةَ، وَأَنْتِ صَغِيرَةٌ أَنْ تَكُونِي بَيْنَ أُلُوفِ يَهُوذَا، فَمِنْكِ يَخْرُجُ لِي ٱلَّذِي يَكُونُ مُتَسَلِّطًا عَلَى إِسْرَائِيلَ، وَمَخَارِجُهُ مُنْذُ ٱلْقَدِيمِ، مُنْذُ أَيَّامِ ٱلْأَزَلِ».","«ạảmãạ ạản̊ti yā baẙta laḥ̊mi ạảf̊rātaẗa, wāản̊ti ṣagẖīraẗuⁿ ạản̊ takūnī baẙna ạủlūfi yahūdẖā, famin̊ki yakẖ̊ruju lī ٱlãdẖī yakūnu mutasalĩṭaⁿạ ʿalay̱ ại̹s̊rāyỉyla, wamakẖārijuhu mun̊dẖu ٱl̊qadīmi, mun̊dẖu ạảyãạmi ٱl̊ạảzali»."],[5,3,"لِذَلِكَ يُسَلِّمُهُمْ إِلَى حِينَمَا تَكُونُ قَدْ وَلَدَتْ وَالِدَةٌ، ثُمَّ تَرْجِعُ بَقِيَّةُ إِخْوَتِهِ إِلَى بَنِي إِسْرَائِيلَ.","lidẖalika yusalĩmuhum̊ ại̹lay̱ ḥīnamā takūnu qad̊ waladat̊ wālidaẗuⁿ, tẖumã tar̊jiʿu baqīãẗu ại̹kẖ̊watihi ại̹lay̱ banī ại̹s̊rāyỉyla."],[5,4,"وَيَقِفُ وَيَرْعَى بِقُدْرَةِ ٱلرَّبِّ، بِعَظَمَةِ ٱسْمِ ٱلرَّبِّ إِلَهِهِ، وَيَثْبُتُونَ. لِأَنَّهُ ٱلْآنَ يَتَعَظَّمُ إِلَى أَقَاصِي ٱلْأَرْضِ.","wayaqifu wayar̊ʿay̱ biqud̊raẗi ٱlrãbĩ, biʿaẓamaẗi ٱs̊mi ٱlrãbĩ ại̹lahihi, wayatẖ̊butūna. liạảnãhu ٱl̊ậna yataʿaẓãmu ại̹lay̱ ạảqāṣī ٱl̊ạảr̊ḍi."],[5,5,"وَيَكُونُ هَذَا سَلَامًا. إِذَا دَخَلَ أَشُّورُ فِي أَرْضِنَا، وَإِذَا دَاسَ فِي قُصُورِنَا، نُقِيمُ عَلَيْهِ سَبْعَةَ رُعَاةٍ وَثَمَانِيَةً مِنْ أُمَرَاءِ ٱلنَّاسِ،","wayakūnu hadẖā salāmaⁿạ. ại̹dẖā dakẖala ạảsẖũwru fī ạảr̊ḍinā, wāi̹dẖā dāsa fī quṣūrinā, nuqīmu ʿalaẙhi sab̊ʿaẗa ruʿāẗiⁿ watẖamānīaẗaⁿ min̊ ạủmarāʾi ٱlnãạsi,"],[5,6,"فَيَرْعَوْنَ أَرْضَ أَشُّورَ بِٱلسَّيْفِ، وَأَرْضَ نِمْرُودَ فِي أَبْوَابِهَا، فَيَنْفُذُ مِنْ أَشُّورَ إِذَا دَخَلَ أَرْضَنَا وَإِذَا دَاسَ تُخُومَنَا.","fayar̊ʿaẘna ạảr̊ḍa ạảsẖũwra biٱlsãẙfi, wāảr̊ḍa nim̊rūda fī ạảb̊wābihā, fayan̊fudẖu min̊ ạảsẖũwra ại̹dẖā dakẖala ạảr̊ḍanā wāi̹dẖā dāsa tukẖūmanā."],[5,7,"وَتَكُونُ بَقِيَّةُ يَعْقُوبَ فِي وَسَطِ شُعُوبٍ كَثِيرِينَ كَٱلنَّدَى مِنْ عِنْدِ ٱلرَّبِّ، كَٱلْوَابِلِ عَلَى ٱلْعُشْبِ ٱلَّذِي لَا يَنْتَظِرُ إِنْسَانًا وَلَا يَصْبِرُ لِبَنِي ٱلْبَشَرِ.","watakūnu baqīãẗu yaʿ̊qūba fī wasaṭi sẖuʿūbiⁿ katẖīrīna kaٱlnãday̱ min̊ ʿin̊di ٱlrãbĩ, kaٱl̊wābili ʿalay̱ ٱl̊ʿusẖ̊bi ٱlãdẖī lā yan̊taẓiru ại̹n̊sānaⁿạ walā yaṣ̊biru libanī ٱl̊basẖari."],[5,8,"وَتَكُونُ بَقِيَّةُ يَعْقُوبَ بَيْنَ ٱلْأُمَمِ فِي وَسَطِ شُعُوبٍ كَثِيرِينَ كَٱلْأَسَدِ بَيْنَ وُحُوشِ ٱلْوَعْرِ، كَشِبْلِ ٱلْأَسَدِ بَيْنَ قُطْعَانِ ٱلْغَنَمِ، ٱلَّذِي إِذَا عَبَرَ يَدُوسُ وَيَفْتَرِسُ وَلَيْسَ مَنْ يُنْقِذُ.","watakūnu baqīãẗu yaʿ̊qūba baẙna ٱl̊ạủmami fī wasaṭi sẖuʿūbiⁿ katẖīrīna kaٱl̊ạảsadi baẙna wuḥūsẖi ٱl̊waʿ̊ri, kasẖib̊li ٱl̊ạảsadi baẙna quṭ̊ʿāni ٱl̊gẖanami, ٱlãdẖī ại̹dẖā ʿabara yadūsu wayaf̊tarisu walaẙsa man̊ yun̊qidẖu."],[5,9,"لِتَرْتَفِعْ يَدُكَ عَلَى مُبْغِضِيكَ وَيَنْقَرِضْ كُلُّ أَعْدَائِكَ.","litar̊tafiʿ̊ yaduka ʿalay̱ mub̊gẖiḍīka wayan̊qariḍ̊ kulũ ạảʿ̊dāyỉka."],[5,10,"«وَيَكُونُ فِي ذَلِكَ ٱلْيَوْمِ، يَقُولُ ٱلرَّبُّ، أَنِّي أَقْطَعُ خَيْلَكَ مِنْ وَسَطِكَ، وَأُبِيدُ مَرْكَبَاتِكَ.","«wayakūnu fī dẖalika ٱl̊yaẘmi, yaqūlu ٱlrãbũ, ạảnĩy ạảq̊ṭaʿu kẖaẙlaka min̊ wasaṭika, wāủbīdu mar̊kabātika."],[5,11,"وَأَقْطَعُ مُدُنَ أَرْضِكَ، وَأَهْدِمُ كُلَّ حُصُونِكَ.","wāảq̊ṭaʿu muduna ạảr̊ḍika, wāảh̊dimu kulã ḥuṣūnika."],[5,12,"وَأَقْطَعُ ٱلسِّحْرَ مِنْ يَدِكَ، وَلَا يَكُونُ لَكَ عَائِفُونَ.","wāảq̊ṭaʿu ٱlsĩḥ̊ra min̊ yadika, walā yakūnu laka ʿāyỉfūna."],[5,13,"وَأَقْطَعُ تَمَاثِيلَكَ ٱلْمَنْحُوتَةَ وَأَنْصَابَكَ مِنْ وَسَطِكَ، فَلَا تَسْجُدُ لِعَمَلِ يَدَيْكَ فِي مَا بَعْدُ.","wāảq̊ṭaʿu tamātẖīlaka ٱl̊man̊ḥūtaẗa wāản̊ṣābaka min̊ wasaṭika, falā tas̊judu liʿamali yadaẙka fī mā baʿ̊du."],[5,14,"وَأَقْلَعُ سَوَارِيَكَ مِنْ وَسَطِكَ وَأُبِيدُ مُدُنَكَ.","wāảq̊laʿu sawārīaka min̊ wasaṭika wāủbīdu mudunaka."],[5,15,"وَبِغَضَبٍ وَغَيْظٍ أَنْتَقِمُ مِنَ ٱلْأُمَمِ ٱلَّذِينَ لَمْ يَسْمَعُوا».","wabigẖaḍabiⁿ wagẖaẙẓiⁿ ạản̊taqimu mina ٱl̊ạủmami ٱlãdẖīna lam̊ yas̊maʿūạ»."],[6,1,"اِسْمَعُوا مَا قَالَهُ ٱلرَّبُّ: «قُمْ خَاصِمْ لَدَى ٱلْجِبَالِ وَلْتَسْمَعِ ٱلتِّلَالُ صَوْتَكَ.","ạis̊maʿūạ mā qālahu ٱlrãbũ: «qum̊ kẖāṣim̊ laday̱ ٱl̊jibāli wal̊tas̊maʿi ٱltĩlālu ṣaẘtaka."],[6,2,"اِسْمَعِي خُصُومَةَ ٱلرَّبِّ أَيَّتُهَا ٱلْجِبَالُ وَيَا أُسُسَ ٱلْأَرْضِ ٱلدَّائِمَةَ. فَإِنَّ لِلرَّبِّ خُصُومَةً مَعَ شَعْبِهِ وَهُوَ يُحَاكِمُ إِسْرَائِيلَ:","ạis̊maʿī kẖuṣūmaẗa ٱlrãbĩ ạảyãtuhā ٱl̊jibālu wayā ạủsusa ٱl̊ạảr̊ḍi ٱldãạyỉmaẗa. fāi̹nã lilrãbĩ kẖuṣūmaẗaⁿ maʿa sẖaʿ̊bihi wahūa yuḥākimu ại̹s̊rāyỉyla:"],[6,3,"«يَا شَعْبِي، مَاذَا صَنَعْتُ بِكَ وَبِمَاذَا أَضْجَرْتُكَ؟ ٱشْهَدْ عَلَيَّ!","«yā sẖaʿ̊bī, mādẖā ṣanaʿ̊tu bika wabimādẖā ạảḍ̊jar̊tuka? ٱsẖ̊had̊ ʿalayã!"],[6,4,"إِنِّي أَصْعَدْتُكَ مِنْ أَرْضِ مِصْرَ، وَفَكَكْتُكَ مِنْ بَيْتِ ٱلْعُبُودِيَّةِ، وَأَرْسَلْتُ أَمَامَكَ مُوسَى وَهَارُونَ وَمَرْيَمَ.","ại̹nĩy ạảṣ̊ʿad̊tuka min̊ ạảr̊ḍi miṣ̊ra, wafakak̊tuka min̊ baẙti ٱl̊ʿubūdīãẗi, wāảr̊sal̊tu ạảmāmaka mūsay̱ wahārūna wamar̊yama."],[6,5,"يَا شَعْبِي ٱذْكُرْ بِمَاذَا تَآمَرَ بَالَاقُ مَلِكُ مُوآبَ، وَبِمَاذَا أَجَابَهُ بَلْعَامُ بْنُ بَعُورَ، مِنْ شِطِّيمَ إِلَى ٱلْجِلْجَالِ، لِكَيْ تَعْرِفَ إِجَادَةَ ٱلرَّبِّ».","yā sẖaʿ̊bī ٱdẖ̊kur̊ bimādẖā tā̂mara bālāqu maliku mūậba, wabimādẖā ạảjābahu bal̊ʿāmu b̊nu baʿūra, min̊ sẖiṭĩyma ại̹lay̱ ٱl̊jil̊jāli, likaẙ taʿ̊rifa ại̹jādaẗa ٱlrãbĩ»."],[6,6,"بِمَ أَتَقَدَّمُ إِلَى ٱلرَّبِّ وَأَنْحَنِي لِلإِلَهِ ٱلْعَلِيِّ؟ هَلْ أَتَقَدَّمُ بِمُحْرَقَاتٍ، بِعُجُولٍ أَبْنَاءِ سَنَةٍ؟","bima ạảtaqadãmu ại̹lay̱ ٱlrãbĩ wāản̊ḥanī lilại̹lahi ٱl̊ʿalīĩ? hal̊ ạảtaqadãmu bimuḥ̊raqātiⁿ, biʿujūliⁿ ạảb̊nāʾi sanaẗiⁿ?"],[6,7,"هَلْ يُسَرُّ ٱلرَّبُّ بِأُلُوفِ ٱلْكِبَاشِ، بِرِبَوَاتِ أَنْهَارِ زَيْتٍ؟ هَلْ أُعْطِي بِكْرِي عَنْ مَعْصِيَتِي، ثَمَرَةَ جَسَدِي عَنْ خَطِيَّةِ نَفْسِي؟","hal̊ yusarũ ٱlrãbũ biạủlūfi ٱl̊kibāsẖi, biribawāti ạản̊hāri zaẙtiⁿ? hal̊ ạủʿ̊ṭī bik̊rī ʿan̊ maʿ̊ṣīatī, tẖamaraẗa jasadī ʿan̊ kẖaṭīãẗi naf̊sī?"],[6,8,"قَدْ أَخْبَرَكَ أَيُّهَا ٱلْإِنْسَانُ مَا هُوَ صَالِحٌ، وَمَاذَا يَطْلُبُهُ مِنْكَ ٱلرَّبُّ، إِلَّا أَنْ تَصْنَعَ ٱلْحَقَّ وَتُحِبَّ ٱلرَّحْمَةَ، وَتَسْلُكَ مُتَوَاضِعًا مَعَ إِلَهِكَ.","qad̊ ạảkẖ̊baraka ạảyũhā ٱl̊ại̹n̊sānu mā hūa ṣāliḥuⁿ, wamādẖā yaṭ̊lubuhu min̊ka ٱlrãbũ, ại̹lãạ ạản̊ taṣ̊naʿa ٱl̊ḥaqã watuḥibã ٱlrãḥ̊maẗa, watas̊luka mutawāḍiʿaⁿạ maʿa ại̹lahika."],[6,9,"صَوْتُ ٱلرَّبِّ يُنَادِي لِلْمَدِينَةِ، وَٱلْحِكْمَةُ تَرَى ٱسْمَكَ: «اِسْمَعُوا لِلْقَضِيبِ وَمَنْ رَسَمَهُ.","ṣaẘtu ٱlrãbĩ yunādī lil̊madīnaẗi, waٱl̊ḥik̊maẗu taray̱ ٱs̊maka: «ạis̊maʿūạ lil̊qaḍībi waman̊ rasamahu."],[6,10,"أَفِي بَيْتِ ٱلشِّرِّيرِ بَعْدُ كُنُوزُ شَرٍّ وَإِيفَةٌ نَاقِصَةٌ مَلْعُونَةٌ؟","ạảfī baẙti ٱlsẖĩrĩyri baʿ̊du kunūzu sẖariⁿ̃ wāi̹yfaẗuⁿ nāqiṣaẗuⁿ mal̊ʿūnaẗuⁿ?"],[6,11,"هَلْ أَتَزَكَّى مَعَ مَوَازِينِ ٱلشَّرِّ وَمَعَ كِيسِ مَعَايِيرِ ٱلْغِشِّ؟","hal̊ ạảtazakãy̱ maʿa mawāzīni ٱlsẖãrĩ wamaʿa kīsi maʿāyīri ٱl̊gẖisẖĩ?"],[6,12,"فَإِنَّ أَغْنِيَاءَهَا مَلْآنُونَ ظُلْمًا، وَسُكَّانَهَا يَتَكَلَّمُونَ بِٱلْكَذِبِ، وَلِسَانَهُمْ فِي فَمِهِمْ غَاشٌّ.","fāi̹nã ạảgẖ̊nīāʾahā mal̊ậnūna ẓul̊maⁿạ, wasukãạnahā yatakalãmūna biٱl̊kadẖibi, walisānahum̊ fī famihim̊ gẖāsẖuⁿ̃."],[6,13,"فَأَنَا قَدْ جَعَلْتُ جُرُوحَكَ عَدِيمَةَ ٱلشِّفَاءِ، مُخْرِبًا مِنْ أَجْلِ خَطَايَاكَ.","fāảnā qad̊ jaʿal̊tu jurūḥaka ʿadīmaẗa ٱlsẖĩfāʾi, mukẖ̊ribaⁿạ min̊ ạảj̊li kẖaṭāyāka."],[6,14,"أَنْتَ تَأْكُلُ وَلَا تَشْبَعُ، وَجُوعُكَ فِي جَوْفِكَ. وَتُعَزِّلُ وَلَا تُنَجِّي، وَٱلَّذِي تُنَجِّيهِ أَدْفَعُهُ إِلَى ٱلسَّيْفِ.","ạản̊ta tā̊̉kulu walā tasẖ̊baʿu, wajūʿuka fī jaẘfika. watuʿazĩlu walā tunajĩy, waٱlãdẖī tunajĩyhi ạảd̊faʿuhu ại̹lay̱ ٱlsãẙfi."],[6,15,"أَنْتَ تَزْرَعُ وَلَا تَحْصُدُ. أَنْتَ تَدُوسُ زَيْتُونًا وَلَا تَدَّهِنُ بِزَيْتٍ، وَسُلَافَةً وَلَا تَشْرَبُ خَمْرًا.","ạản̊ta taz̊raʿu walā taḥ̊ṣudu. ạản̊ta tadūsu zaẙtūnaⁿạ walā tadãhinu bizaẙtiⁿ, wasulāfaẗaⁿ walā tasẖ̊rabu kẖam̊raⁿạ."],[6,16,"وَتُحْفَظُ فَرَائِضُ: عُمْرِي، وَجَمِيعُ أَعْمَالِ بَيْتِ: أَخْآبَ، وَتَسْلُكُونَ بِمَشُورَاتِهِمْ، لِكَيْ أُسَلِّمَكَ لِلْخَرَابِ، وَسُكَّانَهَا لِلصَّفِيرِ، فَتَحْمِلُونَ عَارَ شَعْبِي».","watuḥ̊faẓu farāyỉḍu: ʿum̊rī, wajamīʿu ạảʿ̊māli baẙti: ạảkẖ̊ậba, watas̊lukūna bimasẖūrātihim̊, likaẙ ạủsalĩmaka lil̊kẖarābi, wasukãạnahā lilṣãfīri, fataḥ̊milūna ʿāra sẖaʿ̊bī»."],[7,1,"وَيْلٌ لِي! لِأَنِّي صِرْتُ كَجَنَى ٱلصَّيْفِ، كَخُصَاصَةِ ٱلْقِطَافِ، لَا عُنْقُودَ لِلْأَكْلِ وَلَا بَاكُورَةَ تِينَةٍ ٱشْتَهَتْهَا نَفْسِي.","waẙluⁿ lī! liạảnĩy ṣir̊tu kajanay̱ ٱlṣãẙfi, kakẖuṣāṣaẗi ٱl̊qiṭāfi, lā ʿun̊qūda lil̊ạảk̊li walā bākūraẗa tīnaẗiⁿ ٱsẖ̊tahat̊hā naf̊sī."],[7,2,"قَدْ بَادَ ٱلتَّقِيُّ مِنَ ٱلْأَرْضِ، وَلَيْسَ مُسْتَقِيمٌ بَيْنَ ٱلنَّاسِ. جَمِيعُهُمْ يَكْمُنُونَ لِلدِّمَاءِ، يَصْطَادُونَ بَعْضُهُمْ بَعْضًا بِشَبَكَةٍ.","qad̊ bāda ٱltãqīũ mina ٱl̊ạảr̊ḍi, walaẙsa mus̊taqīmuⁿ baẙna ٱlnãạsi. jamīʿuhum̊ yak̊munūna lildĩmāʾi, yaṣ̊ṭādūna baʿ̊ḍuhum̊ baʿ̊ḍaⁿạ bisẖabakaẗiⁿ."],[7,3,"اَلْيَدَانِ إِلَى ٱلشَّرِّ مُجْتَهِدَتَانِ. ٱلرَّئِيسُ طَالِبٌ وَٱلْقَاضِي بِٱلْهَدِيَّةِ، وَٱلْكَبِيرُ مُتَكَلِّمٌ بِهَوَى نَفْسِهِ فَيُعَكِّشُونَهَا.","ạal̊yadāni ại̹lay̱ ٱlsẖãrĩ muj̊tahidatāni. ٱlrãyỉysu ṭālibuⁿ waٱl̊qāḍī biٱl̊hadīãẗi, waٱl̊kabīru mutakalĩmuⁿ bihaway̱ naf̊sihi fayuʿakĩsẖūnahā."],[7,4,"أَحْسَنُهُمْ مِثْلُ ٱلْعَوْسَجِ، وَأَعْدَلُهُمْ مِنْ سِيَاجِ ٱلشَّوْكِ. يَوْمَ مُرَاقِبِيكَ عِقَابُكَ قَدْ جَاءَ. ٱلْآنَ يَكُونُ ٱرْتِبَاكُهُمْ.","ạảḥ̊sanuhum̊ mitẖ̊lu ٱl̊ʿaẘsaji, wāảʿ̊daluhum̊ min̊ sīāji ٱlsẖãẘki. yaẘma murāqibīka ʿiqābuka qad̊ jāʾa. ٱl̊ậna yakūnu ٱr̊tibākuhum̊."],[7,5,"لَا تَأْتَمِنُوا صَاحِبًا. لَا تَثِقُوا بِصَدِيقٍ. ٱحْفَظْ أَبْوَابَ فَمِكَ عَنِ ٱلْمُضْطَجِعَةِ فِي حِضْنِكَ.","lā tā̊̉taminūạ ṣāḥibaⁿạ. lā tatẖiqūạ biṣadīqiⁿ. ٱḥ̊faẓ̊ ạảb̊wāba famika ʿani ٱl̊muḍ̊ṭajiʿaẗi fī ḥiḍ̊nika."],[7,6,"لِأَنَّ ٱلِٱبْنَ مُسْتَهِينٌ بِٱلْأَبِ، وَٱلْبِنْتَ قَائِمَةٌ عَلَى أُمِّهَا، وَٱلْكَنَّةَ عَلَى حَمَاتِهَا، وَأَعْدَاءُ ٱلْإِنْسَانِ أَهْلُ بَيْتِهِ.","liạảnã ٱliٱb̊na mus̊tahīnuⁿ biٱl̊ạảbi, waٱl̊bin̊ta qāyỉmaẗuⁿ ʿalay̱ ạủmĩhā, waٱl̊kanãẗa ʿalay̱ ḥamātihā, wāảʿ̊dāʾu ٱl̊ại̹n̊sāni ạảh̊lu baẙtihi."],[7,7,"وَلَكِنَّنِي أُرَاقِبُ ٱلرَّبَّ، أَصْبِرُ لِإِلَهِ خَلَاصِي. يَسْمَعُنِي إِلَهِي.","walakinãnī ạủrāqibu ٱlrãbã, ạảṣ̊biru liại̹lahi kẖalāṣī. yas̊maʿunī ại̹lahī."],[7,8,"لَا تَشْمَتِي بِي يَا عَدُوَّتِي، إِذَا سَقَطْتُ أَقُومُ. إِذَا جَلَسْتُ فِي ٱلظُّلْمَةِ فَٱلرَّبُّ نُورٌ لِي.","lā tasẖ̊matī bī yā ʿadūãtī, ại̹dẖā saqaṭ̊tu ạảqūmu. ại̹dẖā jalas̊tu fī ٱlẓũl̊maẗi faٱlrãbũ nūruⁿ lī."],[7,9,"أَحْتَمِلُ غَضَبَ ٱلرَّبِّ لِأَنِّي أَخْطَأْتُ إِلَيْهِ، حَتَّى يُقِيمَ دَعْوَايَ وَيُجْرِيَ حَقِّي. سَيُخْرِجُنِي إِلَى ٱلنُّورِ، سَأَنْظُرُ بِرَّهُ.","ạảḥ̊tamilu gẖaḍaba ٱlrãbĩ liạảnĩy ạảkẖ̊ṭā̊̉tu ại̹laẙhi, ḥatãy̱ yuqīma daʿ̊wāya wayuj̊rīa ḥaqĩy. sayukẖ̊rijunī ại̹lay̱ ٱlnũwri, sāản̊ẓuru birãhu."],[7,10,"وَتَرَى عَدُوَّتِي فَيُغَطِّيهَا ٱلْخِزْيُ، ٱلْقَائِلَةُ لِي: «أَيْنَ هُوَ ٱلرَّبُّ إِلَهُكِ؟» عَيْنَايَ سَتَنْظُرَانِ إِلَيْهَا. اَلْآنَ تَصِيرُ لِلدَّوْسِ كَطِينِ ٱلْأَزِقَّةِ.","wataray̱ ʿadūãtī fayugẖaṭĩyhā ٱl̊kẖiz̊yu, ٱl̊qāyỉlaẗu lī: «ạảẙna hūa ٱlrãbũ ại̹lahuki?» ʿaẙnāya satan̊ẓurāni ại̹laẙhā. ạal̊ậna taṣīru lildãẘsi kaṭīni ٱl̊ạảziqãẗi."],[7,11,"يَوْمَ بِنَاءِ حِيطَانِكِ، ذَلِكَ ٱلْيَوْمَ يَبْعُدُ ٱلْمِيعَادُ.","yaẘma bināʾi ḥīṭāniki, dẖalika ٱl̊yaẘma yab̊ʿudu ٱl̊mīʿādu."],[7,12,"هُوَ يَوْمٌ يَأْتُونَ إِلَيْكِ مِنْ أَشُّورَ وَمُدُنِ مِصْرَ، وَمِنْ مِصْرَ إِلَى ٱلنَّهْرِ. وَمِنَ ٱلْبَحْرِ إِلَى ٱلْبَحْرِ. وَمِنَ ٱلْجَبَلِ إِلَى ٱلْجَبَلِ.","hūa yaẘmuⁿ yā̊̉tūna ại̹laẙki min̊ ạảsẖũwra wamuduni miṣ̊ra, wamin̊ miṣ̊ra ại̹lay̱ ٱlnãh̊ri. wamina ٱl̊baḥ̊ri ại̹lay̱ ٱl̊baḥ̊ri. wamina ٱl̊jabali ại̹lay̱ ٱl̊jabali."],[7,13,"وَلَكِنْ تَصِيرُ ٱلْأَرْضُ خَرِبَةً بِسَبَبِ سُكَّانِهَا، مِنْ أَجْلِ ثَمَرِ أَفْعَالِهِمْ.","walakin̊ taṣīru ٱl̊ạảr̊ḍu kẖaribaẗaⁿ bisababi sukãạnihā, min̊ ạảj̊li tẖamari ạảf̊ʿālihim̊."],[7,14,"اِرْعَ بِعَصَاكَ شَعْبَكَ غَنَمَ مِيرَاثِكَ، سَاكِنَةً وَحْدَهَا فِي وَعْرٍ فِي وَسَطِ ٱلْكَرْمَلِ. لِتَرْعَ فِي بَاشَانَ وَجِلْعَادَ كَأَيَّامِ ٱلْقِدَمِ.","ạir̊ʿa biʿaṣāka sẖaʿ̊baka gẖanama mīrātẖika, sākinaẗaⁿ waḥ̊dahā fī waʿ̊riⁿ fī wasaṭi ٱl̊kar̊mali. litar̊ʿa fī bāsẖāna wajil̊ʿāda kāảyãạmi ٱl̊qidami."],[7,15,"«كَأَيَّامِ خُرُوجِكَ مِنْ أَرْضِ مِصْرَ أُرِيهِ عَجَائِبَ».","«kāảyãạmi kẖurūjika min̊ ạảr̊ḍi miṣ̊ra ạủrīhi ʿajāyỉba»."],[7,16,"يَنْظُرُ ٱلْأُمَمُ وَيَخْجَلُونَ مِنْ كُلِّ بَطْشِهِمْ. يَضَعُونَ أَيْدِيَهُمْ عَلَى أَفْوَاهِهِمْ، وَتَصُمُّ آذَانُهُمْ.","yan̊ẓuru ٱl̊ạủmamu wayakẖ̊jalūna min̊ kulĩ baṭ̊sẖihim̊. yaḍaʿūna ạảẙdīahum̊ ʿalay̱ ạảf̊wāhihim̊, wataṣumũ ậdẖānuhum̊."],[7,17,"يَلْحَسُونَ ٱلتُّرَابَ كَٱلْحَيَّةِ، كَزَوَاحِفِ ٱلْأَرْضِ. يَخْرُجُونَ بِٱلرِّعْدَةِ مِنْ حُصُونِهِمْ، يَأْتُونَ بِٱلرُّعْبِ إِلَى ٱلرَّبِّ إِلَهِنَا وَيَخَافُونَ مِنْكَ.","yal̊ḥasūna ٱltũrāba kaٱl̊ḥayãẗi, kazawāḥifi ٱl̊ạảr̊ḍi. yakẖ̊rujūna biٱlrĩʿ̊daẗi min̊ ḥuṣūnihim̊, yā̊̉tūna biٱlrũʿ̊bi ại̹lay̱ ٱlrãbĩ ại̹lahinā wayakẖāfūna min̊ka."],[7,18,"مَنْ هُوَ إِلَهٌ مِثْلُكَ غَافِرٌ ٱلْإِثْمَ وَصَافِحٌ عَنِ ٱلذَّنْبِ لِبَقِيَّةِ مِيرَاثِهِ! لَا يَحْفَظُ إِلَى ٱلْأَبَدِ غَضَبَهُ، فَإِنَّهُ يُسَرُّ بِٱلرَّأْفَةِ.","man̊ hūa ại̹lahuⁿ mitẖ̊luka gẖāfiruⁿ ٱl̊ại̹tẖ̊ma waṣāfiḥuⁿ ʿani ٱldẖãn̊bi libaqīãẗi mīrātẖihi! lā yaḥ̊faẓu ại̹lay̱ ٱl̊ạảbadi gẖaḍabahu, fāi̹nãhu yusarũ biٱlrãạ̊̉faẗi."],[7,19,"يَعُودُ يَرْحَمُنَا، يَدُوسُ آثَامَنَا، وَتُطْرَحُ فِي أَعْمَاقِ ٱلْبَحْرِ جَمِيعُ خَطَايَاهُمْ.","yaʿūdu yar̊ḥamunā, yadūsu ậtẖāmanā, watuṭ̊raḥu fī ạảʿ̊māqi ٱl̊baḥ̊ri jamīʿu kẖaṭāyāhum̊."],[7,20,"تَصْنَعُ ٱلْأَمَانَةَ لِيَعْقُوبَ وَٱلرَّأْفَةَ لِإِبْرَاهِيمَ، ٱللَّتَيْنِ حَلَفْتَ لِآبَائِنَا مُنْذُ أَيَّامِ ٱلْقِدَمِ.","taṣ̊naʿu ٱl̊ạảmānaẗa līaʿ̊qūba waٱlrãạ̊̉faẗa liại̹b̊rāhīma, ٱllãtaẙni ḥalaf̊ta liậbāyỉnā mun̊dẖu ạảyãạmi ٱl̊qidami."]],"bis-obbr":[[1,1,"Bifo, long taem blong King Jotam, mo long taem blong King Ahas, mo long taem blong King Hesekia, we trifala i king long Juda,* Hae God i stap toktok long Profet Maeka, wan man Juda blong vilej ya Moreset. Hem i stap soemaot ol vison* long hem, mo long ol vison ya, hem i stap tokbaot ol man blong taon ya Sameria,* we i kaptel blong Isrel,* mo ol man blong taon ya Jerusalem,* we i kaptel blong Juda.","Bifo, long taem blong King Jotam, mo long taem blong King Ahas, mo long taem blong King Hesekia, we trifala i king long Juda,* Hae God i stap toktok long Profet Maeka, wan man Juda blong vilej ya Moreset. Hem i stap soemaot ol vison* long hem, mo long ol vison ya, hem i stap tokbaot ol man blong taon ya Sameria,* we i kaptel blong Isrel,* mo ol man blong taon ya Jerusalem,* we i kaptel blong Juda."],[1,2,"Nao Profet Maeka i talem se, “Olgeta man long evri ples. Yufala i lesin gud. Olgeta man long wol. Yufala i harem tok blong mi. Hae God i Masta* blong yumi, mo hem bambae i talemaot ol poen blong hem agens long yufala. !Yufala i lesin! Hem i stap long haos* blong hem long heven, i stap toktok i kam.","Nao Profet Maeka i talem se, “Olgeta man long evri ples. Yufala i lesin gud. Olgeta man long wol. Yufala i harem tok blong mi. Hae God i Masta* blong yumi, mo hem bambae i talemaot ol poen blong hem agens long yufala. !Yufala i lesin! Hem i stap long haos* blong hem long heven, i stap toktok i kam."],[1,3,"Bambae hem i aot long haos ya blong hem, i kamdaon, i wokbaot long top blong ol hil.","Bambae hem i aot long haos ya blong hem, i kamdaon, i wokbaot long top blong ol hil."],[1,4,"Nao ol hil ya bambae oli ronaot, olsem kandel we i stap klosap long faea. Bambae oli ron bigwan olsem wota, oli folem ol krik i kamdaon, olsem wota we i aot long hil, i ron bigwan i kam.","Nao ol hil ya bambae oli ronaot, olsem kandel we i stap klosap long faea. Bambae oli ron bigwan olsem wota, oli folem ol krik i kamdaon, olsem wota we i aot long hil, i ron bigwan i kam."],[1,5,"“Ol samting ya bambae i kamtru olsem, from we yumi ol laen* blong Isrel,* yumi evriwan i mekem sin, mo yumi stap girap agens long God. Ol man Isrel. ?Yufala i stap girap agens long hem, be stamba blong hem hu? Yufala long Sameria* nomo i stamba blong hem. Ol man Juda.* ?Yufala i stap mekem wosip long ol narafala god, be hu i stamba blong hem? !Yufala long Jerusalem* nomo i stamba blong hem!","“Ol samting ya bambae i kamtru olsem, from we yumi ol laen* blong Isrel,* yumi evriwan i mekem sin, mo yumi stap girap agens long God. Ol man Isrel. ?Yufala i stap girap agens long hem, be stamba blong hem hu? Yufala long Sameria* nomo i stamba blong hem. Ol man Juda.* ?Yufala i stap mekem wosip long ol narafala god, be hu i stamba blong hem? !Yufala long Jerusalem* nomo i stamba blong hem!"],[1,6,"Nao from samting ya, Hae God i talem se, ‘Ol man Isrel. Bigfala taon ya Sameria, bambae mi mi spolemgud. Bambae mi brebrekem ol haos blong hem, we ol ston blong hem bambae i stap long ol hip olbaot long open ples, nao ples blong hem bambae i kam ples blong planem rop ya grep* nomo. Ol ston blong taon ya, bambae mi kafsaedem i go long krik, nao oli ron i godaon, mo fandesen blong taon ya bambae i stap nating nomo long klia ples.","Nao from samting ya, Hae God i talem se, ‘Ol man Isrel. Bigfala taon ya Sameria, bambae mi mi spolemgud. Bambae mi brebrekem ol haos blong hem, we ol ston blong hem bambae i stap long ol hip olbaot long open ples, nao ples blong hem bambae i kam ples blong planem rop ya grep* nomo. Ol ston blong taon ya, bambae mi kafsaedem i go long krik, nao oli ron i godaon, mo fandesen blong taon ya bambae i stap nating nomo long klia ples."],[1,7,"Ol aedol we yufala i laekem tumas, bambae ol enemi blong yufala oli brebrekem long ol smosmol pis, mo ol presen we yufala i stap givim long ol woman pris we yufala i stap go slip wetem olgeta long haos blong ol god ya blong yufala, bambae ol enemi ya oli bonem evriwan. Ol aedol ya blong yufala bambae oli kam hip blong doti nomo. Ol samting ya we yufala ol man Sameria i kasem blong yusum long wosip blong yufala, ol enemi blong yufala bambae oli kam tekemaot, blong go givim long ol woman pris blong ol god blong olgeta.’ ”","Ol aedol we yufala i laekem tumas, bambae ol enemi blong yufala oli brebrekem long ol smosmol pis, mo ol presen we yufala i stap givim long ol woman pris we yufala i stap go slip wetem olgeta long haos blong ol god ya blong yufala, bambae ol enemi ya oli bonem evriwan. Ol aedol ya blong yufala bambae oli kam hip blong doti nomo. Ol samting ya we yufala ol man Sameria i kasem blong yusum long wosip blong yufala, ol enemi blong yufala bambae oli kam tekemaot, blong go givim long ol woman pris blong ol god blong olgeta.’ ”"],[1,8,"Nao profet i talem se, “From ol samting ya, mi harem se bambae mi mas krae we mi krae bigwan. Bambae mi mas tekemaot klos blong mi mo sandel blong mi, mi stap wokbaot olsem man we i stap krae from dedman, blong soemaot we mi mi harem nogud tumas. Bambae mi stap singaot bigwan olsem wael dog ya jakol,* mo mi mas singaot nogud olsem bigfala pijin ya ostrij.*","Nao profet i talem se, “From ol samting ya, mi harem se bambae mi mas krae we mi krae bigwan. Bambae mi mas tekemaot klos blong mi mo sandel blong mi, mi stap wokbaot olsem man we i stap krae from dedman, blong soemaot we mi mi harem nogud tumas. Bambae mi stap singaot bigwan olsem wael dog ya jakol,* mo mi mas singaot nogud olsem bigfala pijin ya ostrij.*"],[1,9,"Sik ya we i kasem ol man Sameria i olsem wan bigfala soa long leg blong man, we neva i save kam gud bakegen samtaem. Mo sem samting i kam kasem yumi finis long Juda. Mi luk we ol enemi blong yumi oli stap spolem ples ya blong yumi, kam kasem doa* blong bigfala taon ya Jerusalem, we ol man ples blong mi oli stap long hem.”","Sik ya we i kasem ol man Sameria i olsem wan bigfala soa long leg blong man, we neva i save kam gud bakegen samtaem. Mo sem samting i kam kasem yumi finis long Juda. Mi luk we ol enemi blong yumi oli stap spolem ples ya blong yumi, kam kasem doa* blong bigfala taon ya Jerusalem, we ol man ples blong mi oli stap long hem.”"],[1,10,"Nao long vison* ya, Profet Maeka i gohed, i talem se, “Ol man Juda.* !Yufala i no go talemaot long ol man Filistia long taon ya Gat, we yumi lus long faet! !Yufala i no letem olgeta oli luk we yufala i stap krae! Ol man blong taon ya Betleafra oli stap rol olbaot long asis blong soemaot we tingting blong olgeta i foldaon finis.","Nao long vison* ya, Profet Maeka i gohed, i talem se, “Ol man Juda.* !Yufala i no go talemaot long ol man Filistia long taon ya Gat, we yumi lus long faet! !Yufala i no letem olgeta oli luk we yufala i stap krae! Ol man blong taon ya Betleafra oli stap rol olbaot long asis blong soemaot we tingting blong olgeta i foldaon finis."],[1,11,"Ol man blong taon ya Safiri, naoia oli stap go wok slef* long narafala kantri, we oli neked nomo, mo oli sem tumas. Mo ol man blong taon ya Jahanan oli fraet blong kam afsaed long taon blong olgeta. Mo olgeta blong taon ya Betejel oli stap krae from ol man blong olgeta we oli ded. Yufala i no save go haed long ples blong olgeta.","Ol man blong taon ya Safiri, naoia oli stap go wok slef* long narafala kantri, we oli neked nomo, mo oli sem tumas. Mo ol man blong taon ya Jahanan oli fraet blong kam afsaed long taon blong olgeta. Mo olgeta blong taon ya Betejel oli stap krae from ol man blong olgeta we oli ded. Yufala i no save go haed long ples blong olgeta."],[1,12,"Mo olgeta blong taon ya Marot oli stap harem nogud, oli wantem tumas blong man i kam sevem olgeta. Be bigfala trabol ya, Hae God nomo i tekem i kam, mo i stap klosap finis long doa* blong Jerusalem.*","Mo olgeta blong taon ya Marot oli stap harem nogud, oli wantem tumas blong man i kam sevem olgeta. Be bigfala trabol ya, Hae God nomo i tekem i kam, mo i stap klosap finis long doa* blong Jerusalem.*"],[1,13,"Ol man Lakis. Yufala i mas fasem ol kat blong yufala long ol hos blong yufala, yufala i ronwe. Yufala nao i faswan blong folem rabis fasin blong ol man Isrel,* nao yufala i pulum ol man Jerusalem blong oli mekem sin.","Ol man Lakis. Yufala i mas fasem ol kat blong yufala long ol hos blong yufala, yufala i ronwe. Yufala nao i faswan blong folem rabis fasin blong ol man Isrel,* nao yufala i pulum ol man Jerusalem blong oli mekem sin."],[1,14,"Ol man Juda.* I taem blong yumi evriwan i talem tata long taon ya Moresetgat, from we ol enemi oli stap kam blong holem taon ya. Mo ol man long taon ya Aksib bambae oli no save givhan long ol king blong yumi, nao ol king ya bambae oli harem nogud.","Ol man Juda.* I taem blong yumi evriwan i talem tata long taon ya Moresetgat, from we ol enemi oli stap kam blong holem taon ya. Mo ol man long taon ya Aksib bambae oli no save givhan long ol king blong yumi, nao ol king ya bambae oli harem nogud."],[1,15,"“Ol man Maresa. I no longtaem Hae God bambae i letem ol enemi blong yumi oli kam holem taon ya blong yufala. Nao ol gudgudfala lida blong yumi bambae oli ronwe, oli go haed long ol hol long ston long ples ya Adulam.","“Ol man Maresa. I no longtaem Hae God bambae i letem ol enemi blong yumi oli kam holem taon ya blong yufala. Nao ol gudgudfala lida blong yumi bambae oli ronwe, oli go haed long ol hol long ston long ples ya Adulam."],[1,16,"Ol man Juda. Yufala i mas katem hea blong yufala, blong soemaot we yufala i harem nogud tumas, yufala i stap krae from ol pikinini ya blong yufala, we yufala i lavem olgeta tumas. Yufala i mas katemaot olgeta hea blong yufala, we bambae yufala i bolhed nomo, olsem pijin ya valja,* from we ol enemi blong yumi bambae oli kam tekemaot ol pikinini blong yumi, blong oli go wok slef* long ples blong olgeta.”","Ol man Juda. Yufala i mas katem hea blong yufala, blong soemaot we yufala i harem nogud tumas, yufala i stap krae from ol pikinini ya blong yufala, we yufala i lavem olgeta tumas. Yufala i mas katemaot olgeta hea blong yufala, we bambae yufala i bolhed nomo, olsem pijin ya valja,* from we ol enemi blong yumi bambae oli kam tekemaot ol pikinini blong yumi, blong oli go wok slef* long ples blong olgeta.”"],[2,1,"Nao Profet Maeka i talem se, “!Sore tumas long yufala ya we yufala i no save slip long naet, yufala i stap tingbaot ol rabis plan blong yufala gogo kasem delaet! Long moning, taem yufala i gat janis, be oltaem yufala i stap gohed blong wokem ol plan ya blong yufala.","Nao Profet Maeka i talem se, “!Sore tumas long yufala ya we yufala i no save slip long naet, yufala i stap tingbaot ol rabis plan blong yufala gogo kasem delaet! Long moning, taem yufala i gat janis, be oltaem yufala i stap gohed blong wokem ol plan ya blong yufala."],[2,2,"Taem yufala i wantem graon blong narafala man, yufala i girap, yufala i go tekem isi nomo, mo taem yufala i wantem haos blong narafala man, yufala i girap, yufala i go tekemaot. I no gat man we i naf blong blokem yufala, blong holemtaet graon blong hem, mo haos blong hem, mo ol samting we bambae ol pikinini blong hem oli holem biaen long hem.","Taem yufala i wantem graon blong narafala man, yufala i girap, yufala i go tekem isi nomo, mo taem yufala i wantem haos blong narafala man, yufala i girap, yufala i go tekemaot. I no gat man we i naf blong blokem yufala, blong holemtaet graon blong hem, mo haos blong hem, mo ol samting we bambae ol pikinini blong hem oli holem biaen long hem."],[2,3,"“Nao from samting ya, Hae God i talem se, ‘Mi mi stap mekem plan blong tekem bigfala trabol i kam kasem yufala, mo bambae yufala i no gat rod blong ronwe. Bambae yufala i luk we oltaem nomo, yufala i stap long trabol, nao bambae yufala i no moa save flas, olsem we yufala i stap mekem naoia.","“Nao from samting ya, Hae God i talem se, ‘Mi mi stap mekem plan blong tekem bigfala trabol i kam kasem yufala, mo bambae yufala i no gat rod blong ronwe. Bambae yufala i luk we oltaem nomo, yufala i stap long trabol, nao bambae yufala i no moa save flas, olsem we yufala i stap mekem naoia."],[2,4,"Biaen long taem ya, ol man bambae oli stap jikim yufala from bigfala trabol ya we bambae i kam kasem yufala. Mo bambae oli wokem wan singsing blong talemaot trabol ya we yufala i foldaon long hem. Bambae oli save singsing se, “!Naoia yumi kam nogud olgeta! Olgeta graon blong yumi, Hae God i tekemaot finis i gowe long yumi. Hem i givim long olgeta ya we oli holem yumi blong yumi go wok slef* blong olgeta.”","Biaen long taem ya, ol man bambae oli stap jikim yufala from bigfala trabol ya we bambae i kam kasem yufala. Mo bambae oli wokem wan singsing blong talemaot trabol ya we yufala i foldaon long hem. Bambae oli save singsing se, “!Naoia yumi kam nogud olgeta! Olgeta graon blong yumi, Hae God i tekemaot finis i gowe long yumi. Hem i givim long olgeta ya we oli holem yumi blong yumi go wok slef* blong olgeta.”"],[2,5,"“ ‘Nao from samting ya, long taem ya we bambae mi givimbak ol graon ya, mo ol man blong mi oli stap seraot graon ya bakegen, bambae i no gat man i save stanap long nem blong yufala, blong karem graon blong yufala.’ ”","“ ‘Nao from samting ya, long taem ya we bambae mi givimbak ol graon ya, mo ol man blong mi oli stap seraot graon ya bakegen, bambae i no gat man i save stanap long nem blong yufala, blong karem graon blong yufala.’ ”"],[2,6,"Nao profet i talem se, “Yufala i stap tok strong long mi, yufala i talem se, ‘!Ei! !Yu no stap prij agens long mifala olsem! I nogud yu stap tokbaot ol samting ya oltaem. God i no save mekem mifala i sem.","Nao profet i talem se, “Yufala i stap tok strong long mi, yufala i talem se, ‘!Ei! !Yu no stap prij agens long mifala olsem! I nogud yu stap tokbaot ol samting ya oltaem. God i no save mekem mifala i sem."],[2,7,"!Yumi ol laen* blong Isrel* ya! ?Yu ting se God i save singaot* trabol i kam long yumi? ?Yu ting se tingting blong hem i save finis long yumi? !Fasin blong hem i no olsem! Oltaem hem i stap tok gud long ol man we oli stap folem stret fasin.’ ”","!Yumi ol laen* blong Isrel* ya! ?Yu ting se God i save singaot* trabol i kam long yumi? ?Yu ting se tingting blong hem i save finis long yumi? !Fasin blong hem i no olsem! Oltaem hem i stap tok gud long ol man we oli stap folem stret fasin.’ ”"],[2,8,"Be profet i talemaot we Hae God i tok agens long olgeta, i talem se, “!Olgeta! Oltaem yufala i girap, yufala i stap faet agens long ol man blong mi, olsem we oli enemi blong yufala. Taem olgeta oli kambak long faet, we oli ting se bambae i no moa gat wan samting i save spolem olgeta, be yufala i girap, yufala i go tekemaot ol klos ya we oli stap werem, yufala i karem i blong yufala.","Be profet i talemaot we Hae God i tok agens long olgeta, i talem se, “!Olgeta! Oltaem yufala i girap, yufala i stap faet agens long ol man blong mi, olsem we oli enemi blong yufala. Taem olgeta oli kambak long faet, we oli ting se bambae i no moa gat wan samting i save spolem olgeta, be yufala i girap, yufala i go tekemaot ol klos ya we oli stap werem, yufala i karem i blong yufala."],[2,9,"Ol woman blong ol man blong mi oli laekem ol haos blong olgeta tumas, be yufala i girap, yufala i go ronemaot olgeta i gowe. Mo i gat promes blong mi i stap long ol pikinini blong olgeta, se bambae mi blesem olgeta, be oltaem, yufala i stap blokem olgeta, blong oli no save kasem.","Ol woman blong ol man blong mi oli laekem ol haos blong olgeta tumas, be yufala i girap, yufala i go ronemaot olgeta i gowe. Mo i gat promes blong mi i stap long ol pikinini blong olgeta, se bambae mi blesem olgeta, be oltaem, yufala i stap blokem olgeta, blong oli no save kasem."],[2,10,"Naoia i no moa gat ples blong haed blong yufala long ples ya. !Yufala i girap! !Yufala i gowe! Ol enemi blong yufala bambae oli kam spolemgud olgeta ples ya, from ol sin ya blong yufala.","Naoia i no moa gat ples blong haed blong yufala long ples ya. !Yufala i girap! !Yufala i gowe! Ol enemi blong yufala bambae oli kam spolemgud olgeta ples ya, from ol sin ya blong yufala."],[2,11,"“Yufala i wantem tumas blong lesin long man we tok blong hem i blong giaman nomo, i blong trikim man. Man we i stap talem se, ‘Tru mi talem long yufala, bambae i no longtaem, ples blong yumi i fulap gud long waen, mo ol narafala dring olsem,’ hemia nao prija we yufala i glad long hem.”","“Yufala i wantem tumas blong lesin long man we tok blong hem i blong giaman nomo, i blong trikim man. Man we i stap talem se, ‘Tru mi talem long yufala, bambae i no longtaem, ples blong yumi i fulap gud long waen, mo ol narafala dring olsem,’ hemia nao prija we yufala i glad long hem.”"],[2,12,"Nao profet i talemaot we Hae God i talem se, “Ol laen* blong Isrel.* I gat taem i stap kam, we mi bambae mi kam lukaot olgeta ya we oli kamaot biaen long yufala we i no ded long ol trabol ya. Nao bambae mi tekem olgeta evriwan oli kam wanples bakegen. Bambae mi mekem olsem man blong lukaot long sipsip, we i tekem ol sipsip blong hem oli kambak long fenis blong olgeta. Bambae ples blong yufala i stap fulap bakegen long man, olsem ples blong gudfala gras, we oltaem i gat fulap sipsip i stap long hem.”","Nao profet i talemaot we Hae God i talem se, “Ol laen* blong Isrel.* I gat taem i stap kam, we mi bambae mi kam lukaot olgeta ya we oli kamaot biaen long yufala we i no ded long ol trabol ya. Nao bambae mi tekem olgeta evriwan oli kam wanples bakegen. Bambae mi mekem olsem man blong lukaot long sipsip, we i tekem ol sipsip blong hem oli kambak long fenis blong olgeta. Bambae ples blong yufala i stap fulap bakegen long man, olsem ples blong gudfala gras, we oltaem i gat fulap sipsip i stap long hem.”"],[2,13,"Nao profet i talem se, “Long taem ya, God bambae i openem rod blong ol man blong hem, we bambae i tekemaot olgeta long kantri ya longwe we bambae oli stap wok slef* long hem, i lidim olgeta i kam. Bambae oli kamaot long ol taon ya longwe, nao bambae oli fri. Hae God nomo bambae i king blong olgeta, mo hem bambae i stap lidim olgeta oli aot long ples ya, oli kam.”","Nao profet i talem se, “Long taem ya, God bambae i openem rod blong ol man blong hem, we bambae i tekemaot olgeta long kantri ya longwe we bambae oli stap wok slef* long hem, i lidim olgeta i kam. Bambae oli kamaot long ol taon ya longwe, nao bambae oli fri. Hae God nomo bambae i king blong olgeta, mo hem bambae i stap lidim olgeta oli aot long ples ya, oli kam.”"],[3,1,"Nao Profet Maeka i tok long ol lida blong ol laen* blong Isrel,* i talem se, “Olgeta. Yufala i lesin long tok blong mi. Yufala i lida blong ol man ya blong mi. Mo wok blong yufala i blong jajem olgeta long stret fasin.","Nao Profet Maeka i tok long ol lida blong ol laen* blong Isrel,* i talem se, “Olgeta. Yufala i lesin long tok blong mi. Yufala i lida blong ol man ya blong mi. Mo wok blong yufala i blong jajem olgeta long stret fasin."],[3,2,"Be yufala i girap, yufala i tanem baksaed long stret fasin, yufala i agens long hem, nao yufala i wantem mekem ol rabis fasin nomo. Taem yufala i jajem ol man, i olsem we yufala i stap tekemaot skin blong olgeta we oli laef yet, nao yufala i stap terem mit blong olgeta i kamaot long bun blong olgeta.","Be yufala i girap, yufala i tanem baksaed long stret fasin, yufala i agens long hem, nao yufala i wantem mekem ol rabis fasin nomo. Taem yufala i jajem ol man, i olsem we yufala i stap tekemaot skin blong olgeta we oli laef yet, nao yufala i stap terem mit blong olgeta i kamaot long bun blong olgeta."],[3,3,"Yufala i stap kakae olgeta. Yufala i stap teremaot skin blong olgeta, yufala i stap brekem bun blong olgeta, mo yufala i stap katkatem olgeta long ol smosmol pis, olsem we man i stap katkatem mit blong putum i go long sospen.","Yufala i stap kakae olgeta. Yufala i stap teremaot skin blong olgeta, yufala i stap brekem bun blong olgeta, mo yufala i stap katkatem olgeta long ol smosmol pis, olsem we man i stap katkatem mit blong putum i go long sospen."],[3,4,"I gat taem i stap kam we bambae yufala i krae i go long Hae God blong i givhan long yufala, be bambae hem i no save ansa long yufala. Bambae hem i no save harem prea blong yufala, from we yufala i stap mekem ol fasin ya we i no stret.","I gat taem i stap kam we bambae yufala i krae i go long Hae God blong i givhan long yufala, be bambae hem i no save ansa long yufala. Bambae hem i no save harem prea blong yufala, from we yufala i stap mekem ol fasin ya we i no stret."],[3,5,"“Ol profet. Yufala i stap giaman long ol man blong yumi, yufala i stap pulum olgeta oli go krangke. Taem man i pem yufala, yufala i promes se bambae hem i gat pis, be taem man i no pem yufala, yufala i talem se bambae i no longtaem, faet i kam. Nao from samting ya, Hae God i talem long yufala se,","“Ol profet. Yufala i stap giaman long ol man blong yumi, yufala i stap pulum olgeta oli go krangke. Taem man i pem yufala, yufala i promes se bambae hem i gat pis, be taem man i no pem yufala, yufala i talem se bambae i no longtaem, faet i kam. Nao from samting ya, Hae God i talem long yufala se,"],[3,6,"‘Ol profet. Naoia klosap wok ya blong yufala i finis. Bambae yufala i no moa save luk vison* bakegen, mo bambae yufala i no moa save talemaot ol samting we bambae i hapen long fiuja, from we yufala i stap lidim ol man blong mi oli gorong.","‘Ol profet. Naoia klosap wok ya blong yufala i finis. Bambae yufala i no moa save luk vison* bakegen, mo bambae yufala i no moa save talemaot ol samting we bambae i hapen long fiuja, from we yufala i stap lidim ol man blong mi oli gorong."],[3,7,"Mo sipos ol man oli luk we ol samting ya we yufala i stap talemaot oli no kamtru, bambae yufala i sem bigwan. Taem yufala i luk we mi mi no save ansa long yufala, bambae yufala i harem nogud tumas.’ ”","Mo sipos ol man oli luk we ol samting ya we yufala i stap talemaot oli no kamtru, bambae yufala i sem bigwan. Taem yufala i luk we mi mi no save ansa long yufala, bambae yufala i harem nogud tumas.’ ”"],[3,8,"Mo profet i talem se, “Be mi, oltaem Hae God i stap givim paoa long mi. Oltaem, hem i stap mekem Spirit blong hem i kam bigwan long mi, i holem mi, mo i stap mekem mi mi savegud ol stret fasin blong jajem man. Mo hem i stap mekem tingting blong mi i strong blong mi save talemaot ol sin blong ol man ya blong hem, stret long fes blong olgeta.","Mo profet i talem se, “Be mi, oltaem Hae God i stap givim paoa long mi. Oltaem, hem i stap mekem Spirit blong hem i kam bigwan long mi, i holem mi, mo i stap mekem mi mi savegud ol stret fasin blong jajem man. Mo hem i stap mekem tingting blong mi i strong blong mi save talemaot ol sin blong ol man ya blong hem, stret long fes blong olgeta."],[3,9,"“Ol lida blong ol laen blong Isrel. Yufala i mas lesin long mi. Yufala i stap tanem baksaed long stret fasin blong jajem man. Yufala i stap tanem ol stret fasin i kam rabis fasin nomo.","“Ol lida blong ol laen blong Isrel. Yufala i mas lesin long mi. Yufala i stap tanem baksaed long stret fasin blong jajem man. Yufala i stap tanem ol stret fasin i kam rabis fasin nomo."],[3,10,"Bigfala taon ya Jerusalem,* hem i taon blong Hae God, be yufala i stap tekem mane long fasin blong kilim man i ded, mo long rabis fasin blong jajem man, nao yufala i stap yusum ol mane ya blong bildimap taon ya.","Bigfala taon ya Jerusalem,* hem i taon blong Hae God, be yufala i stap tekem mane long fasin blong kilim man i ded, mo long rabis fasin blong jajem man, nao yufala i stap yusum ol mane ya blong bildimap taon ya."],[3,11,"Ol jaj long taon ya, oltaem oli stap letem ol man oli pem olgeta blong oli folem tingting blong olgeta, blong oli jajem man long fasin we i no stret. Mo ol pris* tu, oli save talemaot mining blong ol loa blong God, long ol man nomo we oli save pem olgeta from. Mo ol profet tu, oli stap talemaot mining blong ol vison, be blong kasem mane nomo. Be oltaem, olgeta ya oli stap ting se Hae God bambae i lukaot long olgeta. Oltaem oli stap talem se, ‘Hae God i stap wetem yumi ya. Trabol i no save kasem yumi.’","Ol jaj long taon ya, oltaem oli stap letem ol man oli pem olgeta blong oli folem tingting blong olgeta, blong oli jajem man long fasin we i no stret. Mo ol pris* tu, oli save talemaot mining blong ol loa blong God, long ol man nomo we oli save pem olgeta from. Mo ol profet tu, oli stap talemaot mining blong ol vison, be blong kasem mane nomo. Be oltaem, olgeta ya oli stap ting se Hae God bambae i lukaot long olgeta. Oltaem oli stap talem se, ‘Hae God i stap wetem yumi ya. Trabol i no save kasem yumi.’"],[3,12,"“Nao from ol rabis fasin ya blong yufala, Hae God bambae i tekem ol enemi blong yumi oli kam spolemgud bigfala taon ya Jerusalem, we bambae oli mekem i kam bigfala hip blong ol ston blong ol haos we oli brobrok. Olgeta ya bambae oli brebrekem graon long tabu hil* ya Saeon* we haos* blong Hae God i stap long hem, oli mekem i kam olsem ples blong garen nomo, nao bambae bigfala bus i kam kavremap hil ya.”","“Nao from ol rabis fasin ya blong yufala, Hae God bambae i tekem ol enemi blong yumi oli kam spolemgud bigfala taon ya Jerusalem, we bambae oli mekem i kam bigfala hip blong ol ston blong ol haos we oli brobrok. Olgeta ya bambae oli brebrekem graon long tabu hil* ya Saeon* we haos* blong Hae God i stap long hem, oli mekem i kam olsem ples blong garen nomo, nao bambae bigfala bus i kam kavremap hil ya.”"],[4,1,"Nao Profet Maeka i talem se, “Olgeta. I gat taem i stap kam we hil* ya we haos* blong Hae God i stap long hem bambae i kam hae moa, i winim ol narafala hil. Mo ol man blong plante ples long wol bambae oli save wokbaot blong kam long hem.","Nao Profet Maeka i talem se, “Olgeta. I gat taem i stap kam we hil* ya we haos* blong Hae God i stap long hem bambae i kam hae moa, i winim ol narafala hil. Mo ol man blong plante ples long wol bambae oli save wokbaot blong kam long hem."],[4,2,"Olgeta ya bambae oli kam, oli talem se, ‘Hae God i God blong Jekob.* Yufala i kam. Yumi go antap long hil ya blong hem. Yumi go mekem wosip long haos blong hem. Hem bambae i tijim yumi long ol fasin we hem i wantem blong yumi folem, nao bambae yumi save folem ol rod we hem i jusumaot, from we oltaem, tok blong hem i stap kamaot // long taon ya Jerusalem,* mo oltaem, long hil ya Saeon,* hem i stap tijim ol man blong hem // long ol loa blong hem.’","Olgeta ya bambae oli kam, oli talem se, ‘Hae God i God blong Jekob.* Yufala i kam. Yumi go antap long hil ya blong hem. Yumi go mekem wosip long haos blong hem. Hem bambae i tijim yumi long ol fasin we hem i wantem blong yumi folem, nao bambae yumi save folem ol rod we hem i jusumaot, from we oltaem, tok blong hem i stap kamaot // long taon ya Jerusalem,* mo oltaem, long hil ya Saeon,* hem i stap tijim ol man blong hem // long ol loa blong hem.’"],[4,3,"“Hem bambae i jajem ol trabol blong ol man blong plante ples, mo bambae i stretem ol rao blong ol kantri we oli gat paoa, nating we oli stap klosap no longwe. Long taem ya, ol man bambae oli hamarem ol naef blong faet blong olgeta, gogo oli kam aean blong digim graon. Mo ol spia blong olgeta, bambae oli wokem olgeta oli kam huknaef blong katem gru blong ol grep* blong olgeta. Nao olbaot long wol, ol man bambae oli no moa save girap blong go kilim ol narafala man, neva bambae oli save mekemrere bakegen blong go mekem faet.","“Hem bambae i jajem ol trabol blong ol man blong plante ples, mo bambae i stretem ol rao blong ol kantri we oli gat paoa, nating we oli stap klosap no longwe. Long taem ya, ol man bambae oli hamarem ol naef blong faet blong olgeta, gogo oli kam aean blong digim graon. Mo ol spia blong olgeta, bambae oli wokem olgeta oli kam huknaef blong katem gru blong ol grep* blong olgeta. Nao olbaot long wol, ol man bambae oli no moa save girap blong go kilim ol narafala man, neva bambae oli save mekemrere bakegen blong go mekem faet."],[4,4,"Olgeta man bambae oli stap gud, mo oli gat pis olwe. Bambae oli save stap gud long ol plantesen blong grep blong olgeta, mo oli save sidaon aninit long ol figtri* blong olgeta. Bambae i no moa gat man blong mekem olgeta oli fraet. Hae God i gat olgeta paoa, mo hemia tok blong hem.”","Olgeta man bambae oli stap gud, mo oli gat pis olwe. Bambae oli save stap gud long ol plantesen blong grep blong olgeta, mo oli save sidaon aninit long ol figtri* blong olgeta. Bambae i no moa gat man blong mekem olgeta oli fraet. Hae God i gat olgeta paoa, mo hemia tok blong hem.”"],[4,5,"“Nating we olgeta man long wol ya oli stap mekem wosip long ol god blong olgeta, mo oli stap obei long olgeta, be yumi ya, Hae God i God blong yumi, mo bambae yumi stap mekem wosip long hem, mo yumi stap obei long hem oltaem nomo, gogo i no save finis.”","“Nating we olgeta man long wol ya oli stap mekem wosip long ol god blong olgeta, mo oli stap obei long olgeta, be yumi ya, Hae God i God blong yumi, mo bambae yumi stap mekem wosip long hem, mo yumi stap obei long hem oltaem nomo, gogo i no save finis.”"],[4,6,"Nao Profet Maeka i talemaot we Hae God i talem se, “Olgeta. Bambae mi mi panisim yufala. Bambae yufala i aot long ples ya, yufala i go stap long wan narafala kantri longwe, yufala i stap wok slef,* we bambae yufala i stap harem nogud tumas from. Bambae yufala i no gat paoa nating, olsem man we haf bodi blong hem i ded finis. Be i gat taem i stap kam, we bambae mi tekem olgeta we i stap kamaot biaen long smol haf blong yufala we bambae oli stap, oli kam wanples bakegen. Bambae mi givim niufala laef long olgeta. Bambae mi mekem olgeta oli kam plante bakegen, we bambae oli kam wan kantri we i gat paoa. Olgeta ya bambae oli stap long hil ya Saeon,* mo mi bambae mi king blong olgeta olwe, gogo i no save finis.","Nao Profet Maeka i talemaot we Hae God i talem se, “Olgeta. Bambae mi mi panisim yufala. Bambae yufala i aot long ples ya, yufala i go stap long wan narafala kantri longwe, yufala i stap wok slef,* we bambae yufala i stap harem nogud tumas from. Bambae yufala i no gat paoa nating, olsem man we haf bodi blong hem i ded finis. Be i gat taem i stap kam, we bambae mi tekem olgeta we i stap kamaot biaen long smol haf blong yufala we bambae oli stap, oli kam wanples bakegen. Bambae mi givim niufala laef long olgeta. Bambae mi mekem olgeta oli kam plante bakegen, we bambae oli kam wan kantri we i gat paoa. Olgeta ya bambae oli stap long hil ya Saeon,* mo mi bambae mi king blong olgeta olwe, gogo i no save finis.",7],[4,8,"“Jerusalem.* Yu yu olsem wajhaos* blong mi, we mi mi stap long yu blong lukaot gud long ol sipsip blong mi. Bambae king blong yu i kambak, i stap long yu bakegen, nao bambae i stap rul long olgeta ples, olsem we i stap mekem fastaem.","“Jerusalem.* Yu yu olsem wajhaos* blong mi, we mi mi stap long yu blong lukaot gud long ol sipsip blong mi. Bambae king blong yu i kambak, i stap long yu bakegen, nao bambae i stap rul long olgeta ples, olsem we i stap mekem fastaem."],[4,9,"“Ol man Jerusalem. ?Yufala i stap krae tumas olsem from wanem? ?Yufala i stap harem nogud tumas olsem woman we i bonem pikinini, be from wanem? ?Yufala i harem nogud from we yufala i no moa gat king blong yufala, mo ol haeman blong yufala oli ded evriwan finis?","“Ol man Jerusalem. ?Yufala i stap krae tumas olsem from wanem? ?Yufala i stap harem nogud tumas olsem woman we i bonem pikinini, be from wanem? ?Yufala i harem nogud from we yufala i no moa gat king blong yufala, mo ol haeman blong yufala oli ded evriwan finis?"],[4,10,"Olgeta. I stret nomo blong yufala i harem nogud, yufala i stap tantanem yufala, mo yufala i stap singaot bigwan olsem woman we i bonem pikinini. Bambae i no longtaem, ol enemi oli fosem yufala blong yufala i aot long taon ya blong yufala, nao yufala i go stap long open ples nomo. Bambae oli tekem yufala i go long Babilonia, be biaen, mi bambae mi sevem olgeta we oli kamaot biaen long yufala, mi tekemaot olgeta long han blong ol enemi ya blong yufala, oli kambak.”","Olgeta. I stret nomo blong yufala i harem nogud, yufala i stap tantanem yufala, mo yufala i stap singaot bigwan olsem woman we i bonem pikinini. Bambae i no longtaem, ol enemi oli fosem yufala blong yufala i aot long taon ya blong yufala, nao yufala i go stap long open ples nomo. Bambae oli tekem yufala i go long Babilonia, be biaen, mi bambae mi sevem olgeta we oli kamaot biaen long yufala, mi tekemaot olgeta long han blong ol enemi ya blong yufala, oli kambak.”"],[4,11,"Mo bakegen, Profet Maeka i talemaot we Hae God i talem se, “Olgeta. Naoia, ol man blong plante kantri oli kam hivap finis blong mekem faet agens long yufala. Oli stap taltalem se, ‘!Yumi mas spolem taon ya Jerusalem*! !Yumi mas mekem taon ya i kam nogud olgeta!’","Mo bakegen, Profet Maeka i talemaot we Hae God i talem se, “Olgeta. Naoia, ol man blong plante kantri oli kam hivap finis blong mekem faet agens long yufala. Oli stap taltalem se, ‘!Yumi mas spolem taon ya Jerusalem*! !Yumi mas mekem taon ya i kam nogud olgeta!’"],[4,12,"Olgeta ya oli stap tok olsem, be oli no save nating tingting blong mi. Oli no save we mi mi tekem olgeta i kam wanples long ples ya, blong mi panisim olgeta, mi flatemgud olgeta, olsem we man i tekem ol hed blong wit* i kam wanples blong buluk i stap purumpurumbut long hem blong tekemaot ol kakae blong hem.","Olgeta ya oli stap tok olsem, be oli no save nating tingting blong mi. Oli no save we mi mi tekem olgeta i kam wanples long ples ya, blong mi panisim olgeta, mi flatemgud olgeta, olsem we man i tekem ol hed blong wit* i kam wanples blong buluk i stap purumpurumbut long hem blong tekemaot ol kakae blong hem."],[4,13,"!Yufala i girap! !Yufala i go givim panis long olgeta! Mi bambae mi mekem yufala i gat paoa. Bambae yufala i strong olsem bul we hon blong hem, aean, mo leg blong hem daon, bras. Bambae yufala i flatemgud ol man blong plante kantri. Nao ol samting we olgeta ya oli bin winim long taem blong faet, bambae yufala i save givim i kam long mi, we mi mi Hae God, mi Masta* blong olgeta man long wol.”","!Yufala i girap! !Yufala i go givim panis long olgeta! Mi bambae mi mekem yufala i gat paoa. Bambae yufala i strong olsem bul we hon blong hem, aean, mo leg blong hem daon, bras. Bambae yufala i flatemgud ol man blong plante kantri. Nao ol samting we olgeta ya oli bin winim long taem blong faet, bambae yufala i save givim i kam long mi, we mi mi Hae God, mi Masta* blong olgeta man long wol.”"],[5,1,"Nao profet i talem se, “!Ol man Jerusalem! !Yumi mas tekem ol soldia blong yumi i kam wanples! !Naoia ol enemi blong yumi oli raonem yumi finis! !Oli stap mekem i nogud long king blong yumi, blong mekem hem i sem!”","Nao profet i talem se, “!Ol man Jerusalem! !Yumi mas tekem ol soldia blong yumi i kam wanples! !Naoia ol enemi blong yumi oli raonem yumi finis! !Oli stap mekem i nogud long king blong yumi, blong mekem hem i sem!”"],[5,2,"Nao Profet Maeka i talemaot we Hae God i talem se, “Yufala long taon ya Betlehem, long distrik ya Efrata long Juda,* taon ya blong yufala i wan smol taon long ol narafala taon we oli stap raonabaot long yufala, be mi bambae mi mekem we wan pikinini* bambae i kamaot long yufala, we hem bambae i rul long ol laen* blong Isrel.* Man ya, stamba blong hem, wan olfala bubu blong yufala bifo.”","Nao Profet Maeka i talemaot we Hae God i talem se, “Yufala long taon ya Betlehem, long distrik ya Efrata long Juda,* taon ya blong yufala i wan smol taon long ol narafala taon we oli stap raonabaot long yufala, be mi bambae mi mekem we wan pikinini* bambae i kamaot long yufala, we hem bambae i rul long ol laen* blong Isrel.* Man ya, stamba blong hem, wan olfala bubu blong yufala bifo.”"],[5,3,"Nao profet i talem se, “Be fastaem, Hae God bambae i letem yumi i go stap long han blong ol enemi blong yumi, gogo kasem taem we woman ya we bambae i bonem pikinini ya, hem i bonem pikinini ya blong hem. Taem pikinini ya i bon, olgeta man ples blong hem we oli go stap wok slef* long narafala kantri, bambae oli kam joen wanples bakegen long ol man ples blong olgeta.","Nao profet i talem se, “Be fastaem, Hae God bambae i letem yumi i go stap long han blong ol enemi blong yumi, gogo kasem taem we woman ya we bambae i bonem pikinini ya, hem i bonem pikinini ya blong hem. Taem pikinini ya i bon, olgeta man ples blong hem we oli go stap wok slef* long narafala kantri, bambae oli kam joen wanples bakegen long ol man ples blong olgeta."],[5,4,"Taem pikinini ya i kamtru, hem bambae i lukaot gud long ol man blong hem. Hem bambae i man blong Hae God, mo bambae hem i rul long olgeta long paoa ya we Hae God bambae i givim long hem, mo bambae hem i karem nem ya King, we i nem blong Hae God nomo. Nao long taem ya, ol man blong hem bambae oli stap gud, from we olgeta man olbaot long wol bambae oli luksave we hem i gat paoa.","Taem pikinini ya i kamtru, hem bambae i lukaot gud long ol man blong hem. Hem bambae i man blong Hae God, mo bambae hem i rul long olgeta long paoa ya we Hae God bambae i givim long hem, mo bambae hem i karem nem ya King, we i nem blong Hae God nomo. Nao long taem ya, ol man blong hem bambae oli stap gud, from we olgeta man olbaot long wol bambae oli luksave we hem i gat paoa."],[5,5,"“Yufala i stap talem se, ‘Sipos ol man Asiria oli kam long ples blong yumi, mo oli stat kam insaed long ol haos blong yumi, bambae yumi save sanem ol nambawan lida blong yumi wetem ol soldia blong olgeta, blong go faet agens long olgeta. Nao ol strong soldia ya blong yumi bambae oli winim ol man Asiria ya, oli kilim olgeta i ded.’ Be sipos ol man Asiria oli kam long ples ya, mo oli stat kam insaed long graon blong yumi, man ya bambae i blokem olgeta, mo hem bambae i mekem we yumi gat pis.”","“Yufala i stap talem se, ‘Sipos ol man Asiria oli kam long ples blong yumi, mo oli stat kam insaed long ol haos blong yumi, bambae yumi save sanem ol nambawan lida blong yumi wetem ol soldia blong olgeta, blong go faet agens long olgeta. Nao ol strong soldia ya blong yumi bambae oli winim ol man Asiria ya, oli kilim olgeta i ded.’ Be sipos ol man Asiria oli kam long ples ya, mo oli stat kam insaed long graon blong yumi, man ya bambae i blokem olgeta, mo hem bambae i mekem we yumi gat pis.”",6],[5,7,"Nao Profet Maeka i gohed i talem se, “Bambae yumi ol laen* blong Isrel,* yumi go wok slef* long ol narafala kantri, be long taem ya ol laen ya blong yumi we bambae oli stap laef yet long ol kantri ya, bambae oli stap givhan gud long ol man raonabaot long olgeta. Bambae oli olsem wota blong naet, no smosmol ren, we Hae God i stap sanem i kam blong mekem kakae i gru gud. Mo ol man ya, oltaem nomo bambae oli stap luk long God blong i givhan long olgeta, oli no save luk long man.","Nao Profet Maeka i gohed i talem se, “Bambae yumi ol laen* blong Isrel,* yumi go wok slef* long ol narafala kantri, be long taem ya ol laen ya blong yumi we bambae oli stap laef yet long ol kantri ya, bambae oli stap givhan gud long ol man raonabaot long olgeta. Bambae oli olsem wota blong naet, no smosmol ren, we Hae God i stap sanem i kam blong mekem kakae i gru gud. Mo ol man ya, oltaem nomo bambae oli stap luk long God blong i givhan long olgeta, oli no save luk long man."],[5,8,"Be bambae olgeta oli stap long medel blong ol man ya olsem laeon tu, we i stap lukaot anamol long bus no sipsip long open ples, blong i kakae. Taem laeon olsem i faenem sipsip, bambae i jam long hem wantaem, i terem long ol smosmol pis, mo i no gat man i save blokem.","Be bambae olgeta oli stap long medel blong ol man ya olsem laeon tu, we i stap lukaot anamol long bus no sipsip long open ples, blong i kakae. Taem laeon olsem i faenem sipsip, bambae i jam long hem wantaem, i terem long ol smosmol pis, mo i no gat man i save blokem."],[5,9,"Long fasin ya nao, bambae olgeta ya oli go mekem faet long ol enemi blong olgeta, we bambae oli winim olgeta, oli spolem olgeta evriwan.”","Long fasin ya nao, bambae olgeta ya oli go mekem faet long ol enemi blong olgeta, we bambae oli winim olgeta, oli spolem olgeta evriwan.”"],[5,10,"Nao profet i talemaot we Hae God i talem se, “Long taem ya, bambae mi mi tekemaot ol hos blong yufala, mo bambae mi spolem ol kat blong faet blong yufala, blong tingting blong yufala i no moa stap long ol samting ya.","Nao profet i talemaot we Hae God i talem se, “Long taem ya, bambae mi mi tekemaot ol hos blong yufala, mo bambae mi spolem ol kat blong faet blong yufala, blong tingting blong yufala i no moa stap long ol samting ya."],[5,11,"Bambae mi spolem ol bigbigfala taon long kantri blong yufala, mo bambae mi brekemdaon ol strong ples blong haed blong yufala.","Bambae mi spolem ol bigbigfala taon long kantri blong yufala, mo bambae mi brekemdaon ol strong ples blong haed blong yufala."],[5,12,"Bambae mi tekemaot ol tabu ston blong yufala we yufala i stap trastem olgeta, mo bambae mi kilim ol kleva ya we oli stap talemaot ol samting we bambae i hapen long fiuja, gogo i no moa gat wan i stap.","Bambae mi tekemaot ol tabu ston blong yufala we yufala i stap trastem olgeta, mo bambae mi kilim ol kleva ya we oli stap talemaot ol samting we bambae i hapen long fiuja, gogo i no moa gat wan i stap."],[5,13,"Ol aedol blong yufala mo ol longlongfala ston ya we yufala i stanemap blong mekem wosip long olgeta, bambae mi spolem olgeta, blong yufala i no moa save mekem wosip long ol samting ya bakegen we yufala nomo i wokem.","Ol aedol blong yufala mo ol longlongfala ston ya we yufala i stanemap blong mekem wosip long olgeta, bambae mi spolem olgeta, blong yufala i no moa save mekem wosip long ol samting ya bakegen we yufala nomo i wokem."],[5,14,"Bambae mi brekemdaon ol pija blong woman god ya Asera* we oli stap olbaot long kantri blong yufala, mo bambae mi spolem ol taon blong yufala.","Bambae mi brekemdaon ol pija blong woman god ya Asera* we oli stap olbaot long kantri blong yufala, mo bambae mi spolem ol taon blong yufala."],[5,15,"Mo bambae mi panisim ol man blong ol kantri raonabaot long yufala, we oli stap mekem mi mi kros tumas from we oli no save obei long mi.”","Mo bambae mi panisim ol man blong ol kantri raonabaot long yufala, we oli stap mekem mi mi kros tumas from we oli no save obei long mi.”"],[6,1,"Nao Profet Maeka i talem se, “Olgeta. Yufala i lesin gud long ol tok we Hae God bambae i talem agens long yufala. “Hae God. Plis yu kam, yu talemaot ol poen blong yu long fes blong ol bigbigfala hil ya, blong oli save harem. Yu tok strong, blong oli save kasem tok blong yu.","Nao Profet Maeka i talem se, “Olgeta. Yufala i lesin gud long ol tok we Hae God bambae i talem agens long yufala. “Hae God. Plis yu kam, yu talemaot ol poen blong yu long fes blong ol bigbigfala hil ya, blong oli save harem. Yu tok strong, blong oli save kasem tok blong yu."],[6,2,"“Ol bigbigfala hil. !Yufala i stamba blong wol ya! !Yufala i stap bifo olgeta! Yufala i lesin gud long ol poen ya we Hae God bambae i talemaot. Mifala ya we i laen* blong Isrel,* mifala i man blong hem, be hem i gat poen agens long mifala, we hem i wantem talemaot.”","“Ol bigbigfala hil. !Yufala i stamba blong wol ya! !Yufala i stap bifo olgeta! Yufala i lesin gud long ol poen ya we Hae God bambae i talemaot. Mifala ya we i laen* blong Isrel,* mifala i man blong hem, be hem i gat poen agens long mifala, we hem i wantem talemaot.”"],[6,3,"Nao profet i talemaot we Hae God i talem se, “Ol man blong mi. ?Tingting blong yufala i nogud from wanem? ?Mi mi putum wanem long yufala we i hevi tumas, we yufala i harem se yufala i no save karem? !I gud yufala i traem talem long mi!","Nao profet i talemaot we Hae God i talem se, “Ol man blong mi. ?Tingting blong yufala i nogud from wanem? ?Mi mi putum wanem long yufala we i hevi tumas, we yufala i harem se yufala i no save karem? !I gud yufala i traem talem long mi!"],[6,4,"Taem ol olfala bubu blong yufala oli stap long Ijip bifo, mi nao mi tekemaot olgeta i kam long ples ya. Olgeta oli stap wok slef* long kantri ya, be mi tekemaot olgeta, mi mekem olgeta oli fri. Moses mo Eron mo Meriam, mi nao mi sanem trifala, blong trifala i lidim olgeta i kam.","Taem ol olfala bubu blong yufala oli stap long Ijip bifo, mi nao mi tekemaot olgeta i kam long ples ya. Olgeta oli stap wok slef* long kantri ya, be mi tekemaot olgeta, mi mekem olgeta oli fri. Moses mo Eron mo Meriam, mi nao mi sanem trifala, blong trifala i lidim olgeta i kam."],[6,5,"Ol man blong mi. Yufala i mas tingbaot ol samting ya we King Balak, king blong ol man Moab bifo i wantem mekem agens long olgeta ya, mo ansa we Balam, we papa blong hem Beo i givim long hem. Mo yufala i mas tingbaot ol samting ya we i hapen long rod, long taem ya we olgeta oli aot long ples ya Sitim we oli stap long hem, oli kam stap long ples ya Gilgal. I gud yufala i tingting gud long ol samting ya bakegen, nao bambae yufala i save ol samting ya we mi mekem long taem ya blong sevem olgeta.”","Ol man blong mi. Yufala i mas tingbaot ol samting ya we King Balak, king blong ol man Moab bifo i wantem mekem agens long olgeta ya, mo ansa we Balam, we papa blong hem Beo i givim long hem. Mo yufala i mas tingbaot ol samting ya we i hapen long rod, long taem ya we olgeta oli aot long ples ya Sitim we oli stap long hem, oli kam stap long ples ya Gilgal. I gud yufala i tingting gud long ol samting ya bakegen, nao bambae yufala i save ol samting ya we mi mekem long taem ya blong sevem olgeta.”"],[6,6,"Nao Profet Maeka i talem se, “?Hae God i God blong heven, mo sipos mi mi go blong mekem wosip long hem, bambae mi karem wanem samting blong mekem sakrefaes long hem? ?Bambae mi tekem ol yang buluk we i nambawan, blong bonem blong givim long hem?","Nao Profet Maeka i talem se, “?Hae God i God blong heven, mo sipos mi mi go blong mekem wosip long hem, bambae mi karem wanem samting blong mekem sakrefaes long hem? ?Bambae mi tekem ol yang buluk we i nambawan, blong bonem blong givim long hem?"],[6,7,"?No sipos mi givim plante taosen sipsip long hem, bambae hem i save glad? ?No sipos mi stap karem fulap olifoel* i kam long hem, bambae hem i save harem gud? ?No sipos mi kilim fasbon pikinini boe blong mi, mi givim long hem, sakrefaes ya i save pemaot sin blong mi? !Nogat!","?No sipos mi givim plante taosen sipsip long hem, bambae hem i save glad? ?No sipos mi stap karem fulap olifoel* i kam long hem, bambae hem i save harem gud? ?No sipos mi kilim fasbon pikinini boe blong mi, mi givim long hem, sakrefaes ya i save pemaot sin blong mi? !Nogat!"],[6,8,"Ol samting we i gud blong mekem, Hae God i talemaot finis long yumi. Hem i God blong yumi, mo hem i wantem blong yumi stap mekem ol fasin we i stret gud, mo blong yumi stap soemaot we yumi lavem ol man tumas, mo blong yumi stap fren gud wetem hem long evri haf blong laef blong yumi, we tingting blong yumi i stap daon.”","Ol samting we i gud blong mekem, Hae God i talemaot finis long yumi. Hem i God blong yumi, mo hem i wantem blong yumi stap mekem ol fasin we i stret gud, mo blong yumi stap soemaot we yumi lavem ol man tumas, mo blong yumi stap fren gud wetem hem long evri haf blong laef blong yumi, we tingting blong yumi i stap daon.”"],[6,9,"Mo Profet Maeka i gohed i talem se, “Man we i waes i mas fraet long Hae God, i mas ona gud long hem. Naoia, hem i stap singaot long yumi long taon ya se, ‘Yufala evriwan we i stap hivap long taon ya, yufala i lesin gud.","Mo Profet Maeka i gohed i talem se, “Man we i waes i mas fraet long Hae God, i mas ona gud long hem. Naoia, hem i stap singaot long yumi long taon ya se, ‘Yufala evriwan we i stap hivap long taon ya, yufala i lesin gud."],[6,10,"Long ol haos blong ol man nogud, i gat ol gudgudfala samting we oli stap winim long ol fasin we i no stret. Long ol stoa blong olgeta, ol skel mo ol kap blong makem ol samting, oli blong giaman nomo. Fasin ya i nogud we i nogud, mi mi no laekem nating, mi agens long hem.","Long ol haos blong ol man nogud, i gat ol gudgudfala samting we oli stap winim long ol fasin we i no stret. Long ol stoa blong olgeta, ol skel mo ol kap blong makem ol samting, oli blong giaman nomo. Fasin ya i nogud we i nogud, mi mi no laekem nating, mi agens long hem."],[6,11,"Mi mi no save fogivim man we i stap yusum skel we i blong giaman nomo.","Mi mi no save fogivim man we i stap yusum skel we i blong giaman nomo."],[6,12,"Oltaem long ples ya, ol rijman oli stap ravem ol puaman, mo yufala evriwan i man blong giaman. !I no gat man i save trastem yufala!","Oltaem long ples ya, ol rijman oli stap ravem ol puaman, mo yufala evriwan i man blong giaman. !I no gat man i save trastem yufala!"],[6,13,"Mo from we yufala i stap mekem sin olsem, naoia mi mi stat finis blong daonem yufala, blong mekem yufala i kam nogud.","Mo from we yufala i stap mekem sin olsem, naoia mi mi stat finis blong daonem yufala, blong mekem yufala i kam nogud."],[6,14,"Oltaem bambae yufala i kakae, be neva bambae yufala i save harem gud. !Bambae yufala i stap hanggri olwe nomo! Bambae yufala i tekem plante samting long ol narafala man, be ol samting ya bambae oli no save stap longtaem long han blong yufala. Mo ol samting we yufala i ting se yufala i stap holem, bambae mi mi spolem evriwan long taem blong faet.","Oltaem bambae yufala i kakae, be neva bambae yufala i save harem gud. !Bambae yufala i stap hanggri olwe nomo! Bambae yufala i tekem plante samting long ol narafala man, be ol samting ya bambae oli no save stap longtaem long han blong yufala. Mo ol samting we yufala i ting se yufala i stap holem, bambae mi mi spolem evriwan long taem blong faet."],[6,15,"Long yia ya, bambae yufala i planem garen, be bambae yufala i no save karem kakae blong hem i kam. Mo bambae yufala i wokem plante olifoel,* be bambae yufala i no save yusum oel ya. Mo bambae yufala i wokem plante waen, be bambae yufala i no save dring waen ya.","Long yia ya, bambae yufala i planem garen, be bambae yufala i no save karem kakae blong hem i kam. Mo bambae yufala i wokem plante olifoel,* be bambae yufala i no save yusum oel ya. Mo bambae yufala i wokem plante waen, be bambae yufala i no save dring waen ya."],[6,16,"Samting ya bambae i kasem yufala olsem, from we yufala i stap folem ol rabis fasin blong tufala king ya bifo, King Omri mo pikinini blong hem King Ehab. Oltaem, yufala i wantem tumas blong folem ol tingting blong tufala ya, nao from samting ya, bambae mi mi spolem yufala, nao ol man blong olgeta ples long wol bambae oli stap lukluk nogud long yufala, oli stap ting rabis nomo long yufala.”","Samting ya bambae i kasem yufala olsem, from we yufala i stap folem ol rabis fasin blong tufala king ya bifo, King Omri mo pikinini blong hem King Ehab. Oltaem, yufala i wantem tumas blong folem ol tingting blong tufala ya, nao from samting ya, bambae mi mi spolem yufala, nao ol man blong olgeta ples long wol bambae oli stap lukluk nogud long yufala, oli stap ting rabis nomo long yufala.”"],[7,1,"Nao Profet Maeka i talem se, “!Naoia tingting blong mi i foldaon olgeta! Mi mi olsem man we i hanggri tumas, i stap go olbaot blong lukaot frut blong i kakae, be i no moa gat frut long ol figtri,* mo long ol rop blong grep* tu. Ol gudfala fig, mo ol grep, ol man oli tekem evriwan finis.","Nao Profet Maeka i talem se, “!Naoia tingting blong mi i foldaon olgeta! Mi mi olsem man we i hanggri tumas, i stap go olbaot blong lukaot frut blong i kakae, be i no moa gat frut long ol figtri,* mo long ol rop blong grep* tu. Ol gudfala fig, mo ol grep, ol man oli tekem evriwan finis."],[7,2,"Naoia, long kantri ya, i no moa gat man i stap we fasin blong hem i stret, mo we tingting blong hem i stap strong long God. Olgeta evriwan i stap lukaot rod blong kilim man i ded. Ol man oli stap ronem ol man ples blong olgeta bakegen blong kilim olgeta i ded.","Naoia, long kantri ya, i no moa gat man i stap we fasin blong hem i stret, mo we tingting blong hem i stap strong long God. Olgeta evriwan i stap lukaot rod blong kilim man i ded. Ol man oli stap ronem ol man ples blong olgeta bakegen blong kilim olgeta i ded."],[7,3,"Ol man oli waes gud blong mekem ol rabis fasin. Oltaem long kot, ol haeman wetem ol jaj oli stap askem long man blong i pem olgeta, blong oli save haedem rong blong hem. Taem wan man we i gat paoa i wantem wan samting we i no stret, hem i save go talem long olgeta ya, nao wantaem nomo, olgeta oli stap joen wanples blong mekem.","Ol man oli waes gud blong mekem ol rabis fasin. Oltaem long kot, ol haeman wetem ol jaj oli stap askem long man blong i pem olgeta, blong oli save haedem rong blong hem. Taem wan man we i gat paoa i wantem wan samting we i no stret, hem i save go talem long olgeta ya, nao wantaem nomo, olgeta oli stap joen wanples blong mekem."],[7,4,"Nating we sam long olgeta ya, fasin blong olgeta i stret lelebet winim ol narawan, be olgeta tu oli no stret nating long fes blong God, oli olsem rabis gras nomo.” Nao profet i talem long ol man se, “Olgeta. Ol profet ya bifo, we Hae God i sanem olgeta olsem wajman blong wekemap yumi, oli talem finis, se taem blong panis bambae i kam, mo taem ya i kamtru finis. Ol trabol ya we oli tokbaot, oli stap kamtru nao.","Nating we sam long olgeta ya, fasin blong olgeta i stret lelebet winim ol narawan, be olgeta tu oli no stret nating long fes blong God, oli olsem rabis gras nomo.” Nao profet i talem long ol man se, “Olgeta. Ol profet ya bifo, we Hae God i sanem olgeta olsem wajman blong wekemap yumi, oli talem finis, se taem blong panis bambae i kam, mo taem ya i kamtru finis. Ol trabol ya we oli tokbaot, oli stap kamtru nao."],[7,5,"Olgeta we oli stap raonabaot long yufala, be bambae yufala i no bilif long tok blong olgeta, mo ol fren blong yufala, bambae yufala i no trastem olgeta. Yufala i mas lukaot gud long ol tok we yufala i stap talem. Nating we yufala i stap toktok wetem woman blong yufala nomo, be yufala i mas lukaot gud.","Olgeta we oli stap raonabaot long yufala, be bambae yufala i no bilif long tok blong olgeta, mo ol fren blong yufala, bambae yufala i no trastem olgeta. Yufala i mas lukaot gud long ol tok we yufala i stap talem. Nating we yufala i stap toktok wetem woman blong yufala nomo, be yufala i mas lukaot gud."],[7,6,"Long taem ya, ol pikinini bambae oli stap ting rabis long ol papa blong olgeta, mo ol gel bambae oli stap girap agens long ol mama blong olgeta. Ol yang woman bambae oli stap rao long mama blong ol man blong olgeta. Olgeta we oli blong wan haos nomo bambae oli stap enemi long olgeta bakegen.","Long taem ya, ol pikinini bambae oli stap ting rabis long ol papa blong olgeta, mo ol gel bambae oli stap girap agens long ol mama blong olgeta. Ol yang woman bambae oli stap rao long mama blong ol man blong olgeta. Olgeta we oli blong wan haos nomo bambae oli stap enemi long olgeta bakegen."],[7,7,"“Be mi, Hae God i God blong mi, mo oltaem bambae mi putum tingting blong mi i stap strong long hem nomo, from we mi save se hem bambae i harem mi. Bambae mi stap wet long hem, from we hem nao bambae i kam sevem mi.”","“Be mi, Hae God i God blong mi, mo oltaem bambae mi putum tingting blong mi i stap strong long hem nomo, from we mi save se hem bambae i harem mi. Bambae mi stap wet long hem, from we hem nao bambae i kam sevem mi.”"],[7,8,"Nao profet i talem se, “Nating we yumi foldaon finis, be ol enemi blong yumi oli no gat rod nating blong laf long yumi, from we bambae yumi girap bakegen yet. Naoia yumi stap long tudak, be Hae God bambae i givim laet long yumi.","Nao profet i talem se, “Nating we yumi foldaon finis, be ol enemi blong yumi oli no gat rod nating blong laf long yumi, from we bambae yumi girap bakegen yet. Naoia yumi stap long tudak, be Hae God bambae i givim laet long yumi."],[7,9,"Yumi mekem sin agens long hem, yumi mekem hem i kros, nao from samting ya, yumi mas mekem tingting blong yumi i stap daon, blong karem kros ya blong hem gogo hem bambae i faet long saed blong yumi bakegen, mo bambae i stretem ol fasin nogud ya we ol enemi blong yumi oli mekem long yumi. Bambae hem i tekemaot yumi long tudak, yumi kam long delaet bakegen. Bambae yumi stap gogo, yumi luk we hem bambae i sevem yumi.","Yumi mekem sin agens long hem, yumi mekem hem i kros, nao from samting ya, yumi mas mekem tingting blong yumi i stap daon, blong karem kros ya blong hem gogo hem bambae i faet long saed blong yumi bakegen, mo bambae i stretem ol fasin nogud ya we ol enemi blong yumi oli mekem long yumi. Bambae hem i tekemaot yumi long tudak, yumi kam long delaet bakegen. Bambae yumi stap gogo, yumi luk we hem bambae i sevem yumi."],[7,10,"Nao long taem ya, ol enemi blong yumi bambae oli luk samting ya, mo tingting blong olgeta bambae i foldaon, oli sem, from we bifo oli bin jikim yumi, oli talem se, ‘?Wehem Hae God ya we i God blong yufala?’ Bambae yumi luk we hem bambae i winim olgeta, i purumbut long olgeta, olsem we man i wokbaot long sofmad long rod.","Nao long taem ya, ol enemi blong yumi bambae oli luk samting ya, mo tingting blong olgeta bambae i foldaon, oli sem, from we bifo oli bin jikim yumi, oli talem se, ‘?Wehem Hae God ya we i God blong yufala?’ Bambae yumi luk we hem bambae i winim olgeta, i purumbut long olgeta, olsem we man i wokbaot long sofmad long rod."],[7,11,"“Ol man Jerusalem.* I gat taem i stap kam we ol man blong taon ya bambae oli stanemap bigfala stonwol blong taon ya bakegen. Long taem ya, bambae ples blong yufala i kam bigwan moa.","“Ol man Jerusalem.* I gat taem i stap kam we ol man blong taon ya bambae oli stanemap bigfala stonwol blong taon ya bakegen. Long taem ya, bambae ples blong yufala i kam bigwan moa."],[7,12,"Long taem ya, olgeta we bambae oli kamaot biaen long yumi, we bambae oli stap olbaot long ol narafala kantri, bambae oli kambak long taon ya bakegen. Olgeta we oli stap long Asiria long is, wetem olgeta we oli stap long Ijip long saot, mo olgeta we oli stap olbaot klosap long Yufretes Reva, mo olgeta we oli stap long ol narafala ples daon long solwota, mo long ol ples antap long hil, olgeta evriwan bambae oli kambak, oli stap wanples bakegen.","Long taem ya, olgeta we bambae oli kamaot biaen long yumi, we bambae oli stap olbaot long ol narafala kantri, bambae oli kambak long taon ya bakegen. Olgeta we oli stap long Asiria long is, wetem olgeta we oli stap long Ijip long saot, mo olgeta we oli stap olbaot klosap long Yufretes Reva, mo olgeta we oli stap long ol narafala ples daon long solwota, mo long ol ples antap long hil, olgeta evriwan bambae oli kambak, oli stap wanples bakegen."],[7,13,"Be olgeta ples olbaot long wol ya, bambae oli kam draeples, from we ol man blong hem oli stap mekem ol fasin we i nogud.”","Be olgeta ples olbaot long wol ya, bambae oli kam draeples, from we ol man blong hem oli stap mekem ol fasin we i nogud.”"],[7,14,"Nao Profet Maeka i prea, i talem se, “Hae God. Mifala i man blong yu. Mifala i olsem ol sipsip blong yu we yu nomo yu jusumaot mifala. Plis yu lukaot gud long mifala, olsem we man blong lukaot long sipsip i stap lukaot long ol sipsip blong hem. Ol sipsip ya blong yu oli stap wanwan olbaot long draeples, be olbaot long ples blong mifala, i gat ol gudfala gras i stap nating. Plis yu letem olgeta oli kam kakae long gudfala graon ya long Basan mo long Gilead, olsem we oli stap kakae long hem bifo.","Nao Profet Maeka i prea, i talem se, “Hae God. Mifala i man blong yu. Mifala i olsem ol sipsip blong yu we yu nomo yu jusumaot mifala. Plis yu lukaot gud long mifala, olsem we man blong lukaot long sipsip i stap lukaot long ol sipsip blong hem. Ol sipsip ya blong yu oli stap wanwan olbaot long draeples, be olbaot long ples blong mifala, i gat ol gudfala gras i stap nating. Plis yu letem olgeta oli kam kakae long gudfala graon ya long Basan mo long Gilead, olsem we oli stap kakae long hem bifo."],[7,15,"“Hae God, yu yu God blong mifala. Plis yu kam mekem ol merikel long medel blong mifala bakegen, olsem we yu mekem bifo, long medel blong ol olfala blong mifala, long taem ya we yu tekemaot olgeta long Ijip.","“Hae God, yu yu God blong mifala. Plis yu kam mekem ol merikel long medel blong mifala bakegen, olsem we yu mekem bifo, long medel blong ol olfala blong mifala, long taem ya we yu tekemaot olgeta long Ijip."],[7,16,"Nating we ol man blong ol narafala kantri, oli strong mo oli gat paoa, be taem oli luk ol merikel ya, bambae oli harem nogud. Tingting blong olgeta bambae i foldaon, nao bambae oli satem maot blong olgeta, mo oli blokem sora blong olgeta.","Nating we ol man blong ol narafala kantri, oli strong mo oli gat paoa, be taem oli luk ol merikel ya, bambae oli harem nogud. Tingting blong olgeta bambae i foldaon, nao bambae oli satem maot blong olgeta, mo oli blokem sora blong olgeta."],[7,17,"Bambae oli fraet tumas, oli seksek, nao oli stap kamkamaot long ol strong ples blong haed blong olgeta, we oli stap pulum bel blong olgeta long asis blong graon olsem snek. Mo from we oli fraet tumas, bambae oli tanem tingting blong olgeta blong ona long yu.","Bambae oli fraet tumas, oli seksek, nao oli stap kamkamaot long ol strong ples blong haed blong olgeta, we oli stap pulum bel blong olgeta long asis blong graon olsem snek. Mo from we oli fraet tumas, bambae oli tanem tingting blong olgeta blong ona long yu."],[7,18,"“Hae God. I no gat wan narafala god we i olsem yu. Bambae yu save fogivim olgeta we oli stap kamaot biaen long mifala, yu save tekemaot ol sin blong olgeta. Taem yu yu kros, be kros blong yu i no save stap longtaem. Oltaem yu yu glad blong soemaot long mifala we yu stap lavem mifala tumas.","“Hae God. I no gat wan narafala god we i olsem yu. Bambae yu save fogivim olgeta we oli stap kamaot biaen long mifala, yu save tekemaot ol sin blong olgeta. Taem yu yu kros, be kros blong yu i no save stap longtaem. Oltaem yu yu glad blong soemaot long mifala we yu stap lavem mifala tumas."],[7,19,"Hae God. Mifala i save se yu bambae yu sore bakegen long mifala, yu tekemaot sin blong mifala i gowe long mifala, olsem we yu purumbut long hem i godaon long graon, yu sakem i godaon olgeta long medel solwota.","Hae God. Mifala i save se yu bambae yu sore bakegen long mifala, yu tekemaot sin blong mifala i gowe long mifala, olsem we yu purumbut long hem i godaon long graon, yu sakem i godaon olgeta long medel solwota."],[7,20,"Mifala evriwan i laen* blong Ebraham, mo Jekob,* mo bambae yu yu save soemaot long mifala we yu stap holemstrong ol promes blong yu, mo oltaem yu stap lavem man tumas, olsem we yu promes blong mekem long ol olfala bubu blong mifala bifo.”","Mifala evriwan i laen* blong Ebraham, mo Jekob,* mo bambae yu yu save soemaot long mifala we yu stap holemstrong ol promes blong yu, mo oltaem yu stap lavem man tumas, olsem we yu promes blong mekem long ol olfala bubu blong mifala bifo.”"]]}};